window.JASTROW_CHUNKS[4]={"1600":{"h":"אִיקָנוֹס","r":"A01600","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (ἱκανός) </div><div class=\"sense\"><b>1)</b> <i>worthy, fit; wealthy</i>. <span class=\"citation\">Yalk. Job 919</span>.</div><div class=\"sense\"><b>—2)</b> <i>sufficient</i>, v. <a href=\"#\" data-headword=\"אַקְסְיוֹס\">אַקְסְיוֹס</a>.</div>","alt":[]},"1601":{"h":"אִיקָר","r":"A01601","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (= h. <a href=\"#\" data-headword=\"יְקָר\">יְקָר</a>, v. <a href=\"#\" data-headword=\"אִי־\">אִי־</a>) <i>honor, glory</i>.—<span class=\"citation\">Targ. Prov. XI, 16</span>; a. fr.—<span class=\"citation\">Y. Ber. I, 2ᵈ</span> <span dir=\"rtl\">איקרִי וכ׳</span> my honor counts for nothing before the honor of my Maker. Ib. II, 4ᵇ <span dir=\"rtl\">מה את פליג ליה א׳</span> (not <span dir=\"rtl\">אתפליג</span>) what honor dost thou pay it (by passing by)?; <span class=\"citation\">Y. Shek. II, 47ᵃ</span> top.—<span class=\"citation\">Y. Peah VIII, 21ᵇ</span> bot. <span dir=\"rtl\">פרנסה דא׳</span> an honorable livelihood. <span class=\"citation\">Y. Ḥag. I, 76ᵈ</span> top <span dir=\"rtl\">איגרא דא׳</span>, v. <a href=\"#\" data-headword=\"אִיגְּרָא\">אִיגְּרָא</a>.—Pl. <span dir=\"rtl\">אִיקְרִין</span> <i>presents, greetings</i>. <span class=\"citation\">Y. Ab. Zar. II, 41ᵈ</span> (some ed. <a href=\"#\" data-headword=\"איקלין\">איקלין</a>).</div>","alt":["אִיקָרָא"]},"1602":{"h":"אִירָא","r":"A01602","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אוֹר\">אור</a>, cmp. <span dir=\"rtl\">חור</span>) <i>white substance, undyed wool</i> or <i>cotton</i>. <span class=\"citation\">Sabb. 11ᵇ</span>; (Tosef. ib. I, 8 missing). Ib. 79ᵃ <span dir=\"rtl\">דוגמא לא׳</span> a sample color for the wool (given to the dyer).—Pl. <span dir=\"rtl\">אִירִין</span>. <span class=\"citation\">B. Kam. 119ᵇ</span>, the remnants of wool in the hands of the dyer. [R. Hanan. reads <a href=\"#\" data-headword=\"אִידָּא\">אִידָּא</a> q. v.] [<span class=\"citation\">Tosef. Kel. B. Bath. I, 4</span> <span dir=\"rtl\">אִירָה</span>; <span class=\"citation\">Kel. XXI, 1</span> <a href=\"#\" data-headword=\"עִירָה\">עִירָה</a>.]</div>","alt":[]},"1603":{"h":"*אִירוֹנִית","r":"A01603","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"אִירָא\">preced.</a>) <i>made of white clay, unburned and flat clay-dish</i>, a kind of tray extemporized for immediate use in the field.—Pl. <span dir=\"rtl\">אִירוֹנִיֹּות</span> &amp;c. <span class=\"citation\">Eduy. II, 5</span> <span dir=\"rtl\">לפסין אי׳</span> ed. (Ms. <span dir=\"rtl\">אלפסין ארנ׳</span>, Mish. Nap. <span dir=\"rtl\">ארו׳</span>). <span class=\"citation\">Y. Sabb. XI, 13ᵃ</span> <span dir=\"rtl\">ארו׳</span>. <span class=\"citation\">Bets. 32ᵃ</span> חיר׳ Ms. M. (ed. <span dir=\"rtl\">חר׳</span>) expl. = <a href=\"#\" data-headword=\"עַרְבּוּבְיָא\">עיר׳</a> Ms. M. (ed. <a href=\"#\" data-headword=\"עֵירוּבָא\">ער׳</a>) = <span dir=\"rtl\">צעי חקלייתא</span> field-dishes. [Rashi; from <a href=\"#\" data-headword=\"*עַיִר\">עיר</a> <i>used in country towns</i>(!), hence <i>coarse, unfinished</i>.].</div>","alt":["(אִרוֹנִית)","חִירוֹנִית","חִרוֹנִית","עִירוֹנִית","(עִרָנִית)"]},"1604":{"h":"אֵירוּס I","r":"A01604","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (supposed to be = ἴρις) <i>Erus</i>, a lily with an aromatic root. <span class=\"citation\">Kil. V, 8</span>, expl. Y. ib. 30ᵃ bot. <a href=\"#\" data-headword=\"אִירְסַיָּה\">אִירְסַיָּה</a> (pl. of <a href=\"#\" data-headword=\"אֶירֶס\">אִירְסָא</a>, v. P. Sm. s. v.). <span class=\"citation\">Tosef. ib. III, 13</span>. Ohol. VIII, 1.</div>","alt":["אֵרוּס"]},"1605":{"h":"אֵירוּס II","r":"A01605","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (prob. from its use, v. <span dir=\"rtl\">ארס</span> a. deriv.) <i>erus</i>, a musical instrument used at weddings and funerals, <i>drum, taboret</i>. <span class=\"citation\">Sot. IX, 14</span> <span dir=\"rtl\">על האי׳</span>—<span dir=\"rtl\">גזרו</span> the use of the <i>erus</i> at weddings was interdicted; v. expl. Bab. <span class=\"citation\">ib. 49ᵇ</span>; Y. ib. 24ᶜ top. <span class=\"citation\">Kel. XV, 6</span> <span dir=\"rtl\">הא׳</span> (used at funerals).</div>","alt":["אֵרוּס"]},"1606":{"h":"אֵירוּסִין","r":"A01606","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֵרוּסִין\">אֵרוּסִין</a></div>","alt":[]},"1607":{"h":"אִירוּעַ","r":"A01607","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אֲרַע I\">ארע</a>) <i>meeting, festive gathering</i>. <span class=\"citation\">Targ. Y. Num. XXIX, 35</span> (= h. <a href=\"#\" data-headword=\"מִקְרָא\">מִקְרָא</a>).</div>","alt":[]},"1608":{"h":"אִירְיָא","r":"A01608","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִרְיָא\">אִרְיָא</a></div>","alt":["אִירְיָיא"]},"1609":{"h":"אֱירִימוֹן","r":"A01609","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֱרִימִין\">אֱרִימִין</a></div>","alt":[]},"1610":{"h":"אֱירֵימִיאָה","r":"A01610","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (ἐρημία) <i>desert, desolation</i>. Koh. R. beg. (play on <i>Jeremiah</i>).</div>","alt":[]},"1611":{"h":"אירם","r":"A01611","html":"<div class=\"sense\">, Y. Maasr. V, 52ᵃ, read <a href=\"#\" data-headword=\"אֶירֶס\">אֶירֶס</a>.</div>","alt":[]},"1612":{"h":"אֶירֶס","r":"A01612","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֶרֶס\">אֶרֶס</a></div>","alt":["אֵירְסָא"]},"1613":{"h":"אִירְסַיָּה","r":"A01613","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֵירוּס I\"><span dir=\"rtl\">אֵירוּס</span> I</a></div>","alt":[]},"1614":{"h":"אִירַע","r":"A01614","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אָרַע\">אָרַע</a>, <a href=\"#\" data-headword=\"אֲרַע I\"><a href=\"#\" data-headword=\"אֲרַע I\">אֲרַע</a>.</a></div>","alt":[]},"1615":{"h":"אִישׁ","r":"A01615","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> , v. <a href=\"#\" data-headword=\"אֱינָשׁ\">אֱינָשׁ</a>) <i>being, man; husband; lord</i>.—<span dir=\"rtl\">א׳ ירושלים</span> a native or citizen of Jerusalem <span class=\"citation\">Aboth I, 4</span>; a. fr.—<span class=\"citation\">Yoma I, 7</span> <span dir=\"rtl\">אִישִׁי כה&quot;ג</span> my lord the High-priest. <span class=\"citation\">Sot. 17ᵃ</span> <span dir=\"rtl\">א׳ ואשה</span> husband and wife; a. fr.—Pl. <a href=\"#\" data-headword=\"אֲנָשִׁים\">אֲנָשִׁים</a>, v. <a href=\"#\" data-headword=\"אֱנוֹשׁ\">אֱנוֹשׁ</a>.</div>","alt":[]},"1616":{"h":"אִישָּׁא","r":"A01616","html":"<div class=\"sense\"><i>fire</i>, v. <a href=\"#\" data-headword=\"אֶשָּׁא\">אֶשָּׁא</a>.</div>","alt":[]},"1617":{"h":"אֶישְׁבֹּורָן","r":"A01617","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֶשְׁבֹּורָן\">אֶשְׁבֹּורָן</a></div>","alt":[]},"1618":{"h":"אִישֶּׁה","r":"A01618","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> , v. <a href=\"#\" data-headword=\"אֵשׁ\">אֵשׁ</a>) <i>burnt-offering.</i> <i>—</i> Pl. <span dir=\"rtl\">אִישִּׁים</span>, <span dir=\"rtl\">אִשִּׁ׳</span>. <span class=\"citation\">Ned. 13ᵃ</span>. <span class=\"citation\">Zeb. V, 4</span> <span dir=\"rtl\">כליל לא׳</span> altogether to be burnt; a. fr.</div>","alt":[]},"1619":{"h":"אִישֹׁון","r":"A01619","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> constr. (v. <a href=\"#\" data-headword=\"אֲשַׁן\">אֲשַׁן</a> a. b. h. <a href=\"#\" data-headword=\"אִישֹׁון\">אִישֹׁון</a>) <i>essence, exact time, season</i>. <span class=\"citation\">Targ. Y. Gen. XVIII, 5</span>. <span class=\"citation\">Ib. XXVIII, 10</span>; a. fr. (in Targ. Y.).—Pl. <a href=\"#\" data-headword=\"אֲשׁוּחֵי\">אֲשׁוּנֵי</a>, <span dir=\"rtl\">אִשׁוּנֵי</span>. <span class=\"citation\">Targ. Y. Lev. XV, 25</span>; <span class=\"citation\">Deut. XXXI, 10</span>. Cmp. <a href=\"#\" data-headword=\"אֵיתָן\">אֵיתָן</a>.</div>","alt":["אֲשׁוּן"]},"1620":{"h":"אִישּׁוּר","r":"A01620","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><b>1)</b>  (v. <a href=\"#\" data-headword=\"אָשַׁר\">אָשַׁר</a>, <i>Pi</i>. </div><div class=\"sense\"><b>2)</b> <i>praise, adoration</i>. <span class=\"citation\">Cant. R. to VIII, 11</span> <span dir=\"rtl\">אישורְךָ היא</span> it is thy praise. <span class=\"citation\">Y. Succ. III, 54ᵃ</span> top, with ten var. expressions of praise are the psalms headed <span dir=\"rtl\">באי׳</span> with the word <i>ashré</i>, &amp;c.—2) (v. <a href=\"#\" data-headword=\"אָשַׁר\">אָשַׁר</a> <i>Pi.</i> 1) <i>legal attestation</i>. <span class=\"citation\">Y. B. Mets. I, 8ᵃ</span> bot; v. <a href=\"#\" data-headword=\"אַשָּׁרָא\">אַשָּׁרָא</a>. [Some ed. <span dir=\"rtl\">אֵישֶׁר</span>.].</div>","alt":[]},"1621":{"h":"אִישׁוּת","r":"A01621","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"אִישׁ\">אִישׁ</a>) <i>matrimony, marital state</i>. <span class=\"citation\">Ab. Zar. 36ᵇ</span> <span dir=\"rtl\">דאורייתא א׳ דרך חתנות</span> biblically intermarriage with gentiles is forbidden only in the way of legal marriage (opp. concubinage, &amp;c.). <span class=\"citation\">Y. Kidd. I, 59ᶜ</span> bot. <span dir=\"rtl\">שִׁפְחוּת אחר א׳</span> servitude after marriage, i.e. a father selling his daughter after she had been married and had returned to her parental home in widowhood &amp;c. <span class=\"citation\">Yeb. 76ᵃ</span>, a. fr. <span dir=\"rtl\">לשום א׳</span> with the intention of establishing a matrimonial relation.</div>","alt":[]},"1622":{"h":"אישות","r":"A01622","html":"<div class=\"sense\"> <span class=\"citation\">Y. Erub. II, 20ᵃ</span> <span dir=\"rtl\">א׳ קנים</span>, v. <a href=\"#\" data-headword=\"חִיצָה II\"><span dir=\"rtl\">חִיצָה</span> II</a></div>","alt":[]},"1623":{"h":"אֵישׁוּת","r":"A01623","html":"<div class=\"sense\"><i>mole</i>, v. <a href=\"#\" data-headword=\"אָשׁוּת\">אָשׁוּת</a>.</div>","alt":[]},"1624":{"h":"אִישְׂטַטְיוֹן","r":"A01624","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִסְטְרָטָא\">אִיסְטַ׳</a></div>","alt":[]},"1625":{"h":"אֶישְׁפָּה","r":"A01625","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַשְׁפָּה\">אַשְׁפָּה</a></div>","alt":[]},"1626":{"h":"אישפותי","r":"A01626","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*אוּשְׁפַּרְתִּי\">אוּשְפַּרְתִּי</a></div>","alt":[]},"1627":{"h":"אִישְׁפֹּת","r":"A01627","html":"<div class=\"sense\"><i>, </i> pl. <span dir=\"rtl\">אִישְׁפַּתֹּות</span>, v. <span dir=\"rtl\">אַשְׁ׳</span>.</div>","alt":[]},"1628":{"h":"אִישְׁקָק","r":"A01628","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִשְׁקָק\">אִשְׁ׳</a></div>","alt":["אִישְׁקָקָא"]},"1629":{"h":"אַיְשַׁר","r":"A01629","html":"<div class=\"sense\"> (Af. of <a href=\"#\" data-headword=\"אֲשַׁר\">אֲשַׁר</a>) <i>good luck!</i> <span class=\"citation\">Y. Shebi. IV, 35ᵇ</span> what means ‘we salute them’? Ans. (Saying) <a href=\"#\" data-headword=\"אִסְקְרִיטִין\">אי׳</a> good luck. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">איי׳</span>. <span class=\"citation\">Y. Taan. I, 64ᵇ</span> bot.; a. e.</div>","alt":["אַיְישַׁר"]},"1630":{"h":"אִישֵּׁר","r":"A01630","html":"<div class=\"sense\">, <i>Pi</i>. of <a href=\"#\" data-headword=\"אָשַׁר\">אָשַׁר</a>.—<span dir=\"rtl\">אֵישֶׁר</span>, v. <a href=\"#\" data-headword=\"אִישּׁוּר\">אִישּׁוּר</a>.</div>","alt":[]},"1631":{"h":"אִישַׁת","r":"A01631","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חִישָׁה\">חִישָׁה</a></div>","alt":[]},"1632":{"h":"אֶושָּׁתָא","r":"A01632","html":"<div class=\"sense\"><i>fire</i>, v. <a href=\"#\" data-headword=\"אֶשָּׁא\">אֶשָּׁא</a>.</div>","alt":[]},"1633":{"h":"אֶישְׁתָּא","r":"A01633","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (= <a href=\"#\" data-headword=\"שִׁית\">שִׁיתָּא</a>) <i>six</i>. <span class=\"citation\">Targ. I Chr. XII, 24</span>; a. e.—<span class=\"citation\">Y. Sot. VIII, 22ᶜ</span> bot. <span dir=\"rtl\">אמתא א׳</span> a cubit has six handbreadths. <span class=\"citation\">Y. Snh. I, end, 19ᵈ</span> חד מן א׳ <i>one sixth</i>. Ib. X, 28ᵇ top <span dir=\"rtl\">אש׳ ירחין</span> six months.—Pl. <a href=\"#\" data-headword=\"אשתין\">אַשְׁתִּין</a> <i>sixty</i>. <span class=\"citation\">Targ. Y. II, Num. XII, 16</span>. Cmp. <a href=\"#\" data-headword=\"אֲשִׁיתָּא\">אֲשִׁיתָּא</a>.</div>","alt":["אֶשְׁתָּא","אֶשְׁתָּה"]},"1634":{"h":"*אִישְׁתַּטִּית","r":"A01634","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"> or river <i>Ishtattith</i>. <span class=\"citation\">Ḥull. 95ᵃ</span> bot. <span dir=\"rtl\">מברא דאי׳</span> the ford of I.</div>","alt":[]},"1635":{"h":"אִישְׁתִּי","r":"A01635","html":"<div class=\"sense\"><i>he drank;</i> v. <a href=\"#\" data-headword=\"שְׁתִי\">שְׁתִי</a>.</div>","alt":[]},"1636":{"h":"אִישְׁתִּיתָא","r":"A01636","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִשְׁתִּיתָא\">אִשְׁתִּיתָא</a></div>","alt":["אישתתא"]},"1637":{"h":"אִישְׁתְּמוֹדַע","r":"A01637","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִשְׁקָק\">אִשְׁ׳</a></div>","alt":[]},"1638":{"h":"אִיתְ־","r":"A01638","html":"<div class=\"sense\"> formative prefix, v. <a href=\"#\" data-headword=\"אִתְ־\">אִתְ־</a>. [Words not found here below, will be found under <a href=\"#\" data-headword=\"אִתְ־\">אִתְ־</a>.]</div>","alt":[]},"1639":{"h":"אִית","r":"A01639","html":"<div class=\"sense\"> prop. <i>being, existence</i>, hence <i>there is, are; est qui</i> &amp;c. <span class=\"citation\">Targ. Gen. XVIII, 24</span>; a. fr.—<span class=\"citation\">Y. Ber. VI, end, 10ᵈ</span> <span dir=\"rtl\">א׳ תניי תני וכ׳</span> one Tannai reads … <span class=\"citation\">R. Hash. 11ᵇ</span>, a. fr. <span dir=\"rtl\">כדאיתא</span> as it is, i.e. as stated.—אית לי <i>I have, I hold</i> (the opinion).—<span class=\"citation\">Snh. 90ᵃ</span>, a. fr. <span dir=\"rtl\">מר כדאית ליה וכ׳</span> the one in accordance with the opinion he holds, and the other &amp;c.—<span class=\"citation\">B. Mets. 5ᵃ</span>, a. fr. <span dir=\"rtl\">אם איתא לדר׳ …</span> if the opinion of R. … has (had) any substance, i.e. if we must adopt his authority.—<span class=\"citation\">Yoma 41ᵃ</span> <span dir=\"rtl\">מאי א׳ לך למימר</span> what hast thou to reply?—<span class=\"citation\">B. Mets. 3ᵃ</span> <span dir=\"rtl\">מאי א׳ לי גבי וכ׳</span> what have I to do with the hired man?—<span class=\"citation\">Yeb. 116ᵃ</span> <span dir=\"rtl\">כי אִיתְנֵכוּ בש׳</span> when ye are in Shili &amp;c.—Compounds <span dir=\"rtl\">אית־כא</span>, contr. <a href=\"#\" data-headword=\"אִיכָּא\">אִיכָּא</a>; <span dir=\"rtl\">לא איתא</span> contr. <a href=\"#\" data-headword=\"לַיִת\">לֵיתָא</a>. [<span dir=\"rtl\">אִיתָאִי</span>, <a href=\"#\" data-headword=\"אִיתִי\">אִיתִי</a>, <i>my existence, I am</i> = h. <span dir=\"rtl\">עוֹדִי</span>. <span class=\"citation\">Targ. Ps. CIV, 33</span>; a. e.] Cmp. <a href=\"#\" data-headword=\"*אִיתַי\">אִיתַי</a>.</div>","alt":["אִיתָא"]},"1640":{"h":"אִיתָא","r":"A01640","html":"<div class=\"sense\"> come!, Imp. of <a href=\"#\" data-headword=\"אֲתָא\">אֲתָא</a>.</div>","alt":[]},"1641":{"h":"אִיתָּא","r":"A01641","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"אִית\">אִית</a> a. <a href=\"#\" data-headword=\"אִישׁ\">אִישׁ</a>; = h. <a href=\"#\" data-headword=\"אִשָּׁה\">אִשָּׁה</a>; (cmp. <a href=\"#\" data-headword=\"*אִנְתָּא\">אִנְתָּא</a>) <i>woman, wife</i>. <span class=\"citation\">Targ. Gen. II, 22</span>; a. fr.—<span class=\"citation\">Y. Maasr. V, end, 52ᵃ</span> <span dir=\"rtl\">חדא איתא</span> a certain woman. <span class=\"citation\">Y. Taan. I, 64ᵇ</span> bot. <a href=\"#\" data-headword=\"אִיתָּא\">איתה</a>. <span class=\"citation\">Y. Ber. II, 5ᶜ</span> bot. <span dir=\"rtl\">איתתֵיה דאבוהי</span> his father’s wife, step-mother (fig. for Babylon); a. fr.</div>","alt":["אִיתָּה","אִיתְּתָא","אִתְּ׳"]},"1642":{"h":"אִיתּוּ","r":"A01642","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אִיתָּא\">preced.</a>) = h. <a href=\"#\" data-headword=\"אִישׁוּת\">אִישׁוּת</a> <i>matrimony;</i> לא׳ <i>in matrimony, as wife</i>. <span class=\"citation\">Targ. Gen. XII, 19</span>; a. fr.</div>","alt":["אִתּוּ","אִנְתּוּ"]},"1643":{"h":"אִיתוּ","r":"A01643","html":"<div class=\"sense\"><i>come ye!</i>, Imper. of <a href=\"#\" data-headword=\"אֲתָא\">אֲתָא</a>.—[<span class=\"citation\">Pes. 50ᵃ</span> <span dir=\"rtl\">איתו אנן</span>, v. <a href=\"#\" data-headword=\"*אִיתַי\">אִיתַי</a>.]</div>","alt":[]},"1644":{"h":"אִיתֹּודָאָה","r":"A01644","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"ודי\">ודי</a>, = <a href=\"#\" data-headword=\"אִתּוֹדָאָה\">אִתְוַדָּאָה</a>) <i>confession</i> of sin. <span class=\"citation\">Targ. Hos. XIV, 3</span>.</div>","alt":["אִתֹּו׳"]},"1645":{"h":"*אִיתַי","r":"A01645","html":"<div class=\"sense\">, <a href=\"#\" data-headword=\"*אִיתַי\">אִיתַיי</a> (pl. of <a href=\"#\" data-headword=\"אִית\">אִית</a>) <i>there is, there are.</i> <span class=\"citation\">Dan. II, 10</span>; a. fr.—<span class=\"citation\">Y. Shebi. X, 39ᶜ</span> <span dir=\"rtl\">ל׳ יום לא איתיי</span> (Y. Macc. I, 31ᵃ … <span dir=\"rtl\">איתי</span>) a loan on thirty days does not exist, i.e. does not come within the rule whereby a creditor may secure collection by announcing legal action before the Sabbath year limitation takes effect.—*<span class=\"citation\">Pes. 50ᵃ</span> <span dir=\"rtl\">כי היכי דאיתו אנן אִיתִינָן וכ׳</span> (read <span dir=\"rtl\">דאיתי</span> or <span dir=\"rtl\">דאיתינן</span>; Ms. M. <span dir=\"rtl\">אתינן</span>; diff. vers. v. Rabb. D. S. a. l.) as we are esteemed <i>here</i> (in this world) so are we <i>there</i> (in the world of the beatified).</div>","alt":[]},"1646":{"h":"אִיתִי","r":"A01646","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Ithi</i>. <span class=\"citation\">Kerith. 24ᵃ</span></div>","alt":[]},"1647":{"h":"*אִיתְּיַטְרוֹן","r":"A01647","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"תִּיאַטְרוֹן\">תִּיאַטְרוֹן</a>) <i>theatre</i>. <span class=\"citation\">Targ. Ezek. XXVII, 6</span> (ed. Vien. <span dir=\"rtl\">אִתְיָטְרוּן</span>).</div>","alt":["אִיתִּיַטְרוֹן","אִתְּ׳"]},"1648":{"h":"אִיתֵּימָא","r":"A01648","html":"<div class=\"sense\"> (= <a href=\"#\" data-headword=\"אִית\">אִית</a>, <a href=\"#\" data-headword=\"*אִיתַי\">אִיתַי</a> a. <a href=\"#\" data-headword=\"אְמָא I\">אֲמָא</a>) <i>some say</i>.—שׁמואל וא׳ ר׳ יוחנן Samuel or, as some say, R. Johan. <span class=\"citation\">Bets. 6ᵃ</span>; a. fr. [Diff. fr. <span dir=\"rtl\">ואי תימא</span>.]</div>","alt":[]},"1649":{"h":"איתימוס","r":"A01649","html":"<div class=\"sense\">, read <a href=\"#\" data-headword=\"אֱטִימוֹס\">אֱטִימוֹס</a>.</div>","alt":[]},"1650":{"h":"אִיתִינָן","r":"A01650","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*אִיתַי\">אִיתַי</a> and <a href=\"#\" data-headword=\"אִית\">אִית</a>.</div>","alt":[]},"1651":{"h":"אִיתְכָּלָא","r":"A01651","html":"<div class=\"sense\"> (const. <a href=\"#\" data-headword=\"כּוּל ²\">אִיתְכַּל</a>) m. = h. <a href=\"#\" data-headword=\"אֶשְׁכֹּל\">אֶשְׁכֹּל</a> (q. v.) <i>bunch of grapes</i>. <span class=\"citation\">Targ. Num. XIII, 24</span>; a. e.—Pl. <span dir=\"rtl\">אִיתְכָּלִין</span>, <span dir=\"rtl\">אַתְכָּ׳</span>, <span dir=\"rtl\">אִיתְכָּלַיָּיא</span>. <span class=\"citation\">Targ. I Sam. XXV, 18</span>; a. e.—Trnsf. <i>scholars</i>, opp. <a href=\"#\" data-headword=\"עִילָיֵיא\">עילייא</a> (leaves), the untutored. <span class=\"citation\">Ḥull. 92ᵃ</span> <span dir=\"rtl\">ליבעי רחמי וכ׳</span> let the grapes pray for the leaves (the scholars for the untutored); for but for the leaves, the grapes could not exist. V. <a href=\"#\" data-headword=\"אֶשְׁכֹּל\">אֶשְׁכֹּל</a>.</div>","alt":["אֶתְכָּלָא","אַתְ׳"]},"1652":{"h":"אִיתְּלִיס","r":"A01652","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַטְלֵיז\">אַטְלֵיז</a> end.</div>","alt":[]},"1653":{"h":"*אִיתָּם","r":"A01653","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">יתם</span>; v. <a href=\"#\" data-headword=\"אִי־\">אִי־</a>) <i>orphan</i>. <span class=\"citation\">Targ. Ps. X, 14</span>; <span class=\"citation\">Job XXXI, 17</span> Ms. (ed. <span dir=\"rtl\">יתם</span>).</div>","alt":[]},"1654":{"h":"אִיתְּמָל","r":"A01654","html":"<div class=\"sense\"> = h. <a href=\"#\" data-headword=\"אֶתְמוֹל\">אֶתְמוֹל</a> <i>yesterday</i>. <span class=\"citation\">Targ. Ex. IV, 10</span>; a. e.—<span class=\"citation\">Erub. 15ᵃ</span>; a. e.</div>","alt":["אִיתְּמָלֵי","אִתְּמוֹל"]},"1655":{"h":"אֵיתָן","r":"A01655","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><b>1)</b> <i>essence, permanent</i> or <i>normal condition</i>. <span class=\"citation\">Nidd. 48ᵇ</span> <span dir=\"rtl\">חזר לאֵיתָנוֹ</span> obtained again its normal condition. <span class=\"citation\">Sot. 36ᵇ</span> <span dir=\"rtl\">שבה קשתו לא׳</span> his membrum resumed its normal condition. (Cmp. <span class=\"citation\">Ex. XIV, 27</span>).</div><div class=\"sense\"><b>—2)</b>  adj. <i>essential, strong</i>. <span class=\"citation\">R. Hash. 11ᵃ</span> א׳ לישנא דתקיפי <i>ethan</i> means <i>strong.—</i> Pl. <span dir=\"rtl\">אֵיתָנִים</span>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">אֵיתָנֵי עולם</span> the mighty of the world (patriarchs). <span class=\"citation\">Gen. R. s. 98</span> (play on <i>ăthono</i> <span class=\"citation\">Gen. XLIX, 11</span>) <span dir=\"rtl\">בנים אֵתָנִים וכ׳</span> mighty sons (heroes) are destined to descend from him.</div><div class=\"sense\"><b>—3)</b>  pr. n. river <i>Ethan</i>. <span class=\"citation\">Succ. 18ᵃ</span> (Ms. M. <span dir=\"rtl\">נתן</span>); a. e.</div>","alt":["אֵתָן"]},"1656":{"h":"איתנטייה","r":"A01656","html":"<div class=\"sense\"> Koh. R. beg., v. <a href=\"#\" data-headword=\"אַוותֶּנְטְיָא\">אַוְותֶּנְטְיָא</a></div>","alt":[]},"1657":{"h":"אִיתְנִיס","r":"A01657","html":"<div class=\"sense\"> (= <a href=\"#\" data-headword=\"נְסַס\">אתנסיס</a>, <span dir=\"rtl\">אתנסס</span>, v. <a href=\"#\" data-headword=\"נְסַס\">נסס</a>; or Ithpe. of <a href=\"#\" data-headword=\"נוּס\">נוס</a> or <a href=\"#\" data-headword=\"נֵיס\">ניס</a>) <i>to be taken sick</i>. <span class=\"citation\">Sabb. 145ᵇ</span> <a href=\"#\" data-headword=\"נְסֵי\">אִיתְנַסִּי</a> (Ms. M. <span dir=\"rtl\">אִיתְנַיֵּיס אִיתְנַיְּיסִי</span> <i>Ithpa.</i>) I should have grown sick; (Ms. Oxf. <span dir=\"rtl\">איסתכני</span> I should have been in danger). <span class=\"citation\">Git. 56ᵃ</span> <span dir=\"rtl\">אִתְנִיסָא</span> (or <span dir=\"rtl\">אִתְנַיְּסָה</span>) she grew sick (from aversion), fainted. Cmp. <a href=\"#\" data-headword=\"אִיסְתְּנִיס\">אִיסְתְּנִיס</a>. [<a href=\"#\" data-headword=\"אִיתְנִיס\">אִיתְנִיס</a> = <a href=\"#\" data-headword=\"אֲנַס\">אִתְאֲנִיס</a>, v. <a href=\"#\" data-headword=\"אֲנַס\">אֲנַס</a>.]</div>","alt":["אִתְנִיס","אִתְנַס"]},"1658":{"h":"אִיתְנְכוּ","r":"A01658","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִית\">אִית</a></div>","alt":["אִיתְנָן"]},"1659":{"h":"אִיתְקוּטְלָא","r":"A01659","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִסְקוּטְלָא I\"><span dir=\"rtl\">אִסְקוּטְלָא</span> I</a></div>","alt":[]},"1660":{"h":"אִיתְּתָא","r":"A01660","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִיתָּא\">אִיתָּא</a></div>","alt":[]},"1661":{"h":"אַךְ I","r":"A01661","html":"<div class=\"sense\"><i>only, but</i>. <span class=\"citation\">Pes. 5ᵃ</span> <span dir=\"rtl\">אך חלק</span> the word <i>akh</i> (<span class=\"citation\">Ex. XII, 15</span> ‘but on the first [preceding] day’) intimates a division of the day between two categories as to the laws concerning that day. Kerith 7ᵃ; a. fr.—<i>Pl</i>. (<a href=\"#\" data-headword=\"*אָכִים\">אַכִּים</a>) <a href=\"#\" data-headword=\"אָכֵין\">אַכִּין</a> <i>the word akh in the Biblical texts</i>. Y. Ber. IX, 14ᵇ bot., a. e. <span dir=\"rtl\">א׳ ורקין מיעוטין</span> the <i>akh</i> and the <i>rak</i> intimate limiting qualifications.</div>","alt":[]},"1662":{"h":"אַךְ II","r":"A01662","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"אָנַךְ\">אָנַךְ</a></div><div class=\"sense\"><b>2)</b> <i>affliction, calamity</i>. <span class=\"citation\">B. Mets. 59ᵇ</span>; v. <a href=\"#\" data-headword=\"חֲכָךְ\">חֲכָךְ</a>. <span class=\"citation\">Gen. R. s. 32</span>, end; Tanḥ. Noah 9, ed. Bub. 3, cmp. <a href=\"#\" data-headword=\"אַךְ I\">preced.</a></div>","alt":[]},"1663":{"h":"*אַךְ III","r":"A01663","html":"<div class=\"sense\"> = <a href=\"#\" data-headword=\"אֵיךְ\">אֵיךְ</a>, only with <a href=\"#\" data-headword=\"חדא\">חדא</a> <i>together</i>. <span class=\"citation\">Targ. Prov. XXII, 18</span> (ed. Vien. <a href=\"#\" data-headword=\"אֵיךְ\">אֵיךְ</a>).</div>","alt":[]},"1664":{"h":"אַכְאָבִית ²","r":"A01664","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כָּאֵב\">כאב</a>) <i>fever connected with pains</i>, <span dir=\"rtl\">חמה וא׳</span>, a vers. for <a href=\"#\" data-headword=\"אַכְאָבִית\">אַבְאָבִית</a>; q. v.</div>","alt":[]},"1665":{"h":"אֲכָאטֵיס","r":"A01665","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (ἀχάτης) <i>agate</i>. <span class=\"citation\">Ex. R. s. 38</span>, end (ed. <a href=\"#\" data-headword=\"אבאטיס\">אבאטיס</a> corr. acc.).</div>","alt":[]},"1666":{"h":"אַכָּבָא","r":"A01666","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*אַבָּכָא\">אַבָּכָא</a></div>","alt":[]},"1667":{"h":"אכבדא","r":"A01667","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Okhbara</i>. <span class=\"citation\">Kidd. 71ᵇ</span> Ar. (ed. <a href=\"#\" data-headword=\"בַּגְדָּא\">בגדא</a>, <a href=\"#\" data-headword=\"בַּגְדַּת\">בגדת</a>); v. <a href=\"#\" data-headword=\"אֲוָנָא II\"><span dir=\"rtl\">אֲוָנָא</span> II</a>.</div>","alt":["אָכְבְּרָא"]},"1668":{"h":"אֵכְדֵן","r":"A01668","html":"<div class=\"sense\"> = <a href=\"#\" data-headword=\"אֵיכְדֵּין\">אֵיכְדֵין</a>.</div>","alt":[]},"1669":{"h":"אכדרוי","r":"A01669","html":"<div class=\"sense\">, <span class=\"citation\">Targ. Ps. CIV, 3</span> Ms., read <span dir=\"rtl\">אִינְדְּרוֹי</span> or <span dir=\"rtl\">אַכְסַדְרוֹי</span>; v. <a href=\"#\" data-headword=\"אִינְדְּרָא\">אִינְדְּרָא</a></div>","alt":[]},"1670":{"h":"אכוור","r":"A01670","html":"<div class=\"sense\"> <span class=\"citation\">Y. Succ. V, 55ᵇ</span> bot. read <a href=\"#\" data-headword=\"מִכְוַור\">מִכְוַור</a>.</div>","alt":[]},"1671":{"h":"אַכְוַורְנְקָא","r":"A01671","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַכְוַנְגַּר\">אַכְוַר׳</a></div>","alt":["אַכְוַורְנְקֵי"]},"1672":{"h":"*אָכוּז","r":"A01672","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כּוּז\">כוז</a>, v. <a href=\"#\" data-headword=\"כּוּז\">כּוּז</a>) [hollow, arched pitcher], euphem. for <i>buttocks</i> or <i>extremity</i> (<i>testicles</i> &amp;c.). <span class=\"citation\">Bekh. VI, 6</span> (<span class=\"citation\">40ᵃ</span>) <a href=\"#\" data-headword=\"ע׳\">ע׳</a>. <span class=\"citation\">Erub. 53ᵇ</span> (question as to spelling) <a href=\"#\" data-headword=\"א׳\">א׳</a> or <a href=\"#\" data-headword=\"ע\">ע</a>? (Ms. M. <a href=\"#\" data-headword=\"אבוד\">אבוד</a>, <a href=\"#\" data-headword=\"עבוד\">עבוד</a>, Rashi <a href=\"#\" data-headword=\"*אֵבוּז\">אבוז</a>, <a href=\"#\" data-headword=\"עָבוּז\">עבוז</a>; v. Rabb. D. S. a. l. note). V. P. Sm. s. v. <a href=\"#\" data-headword=\"כּוּז\">כוז</a> 1691 sq. V. <a href=\"#\" data-headword=\"*אֵבוּז\">אֵבוּז</a>, <a href=\"#\" data-headword=\"הַרְגֹּוז\">הַרְגִּיז</a>.</div>","alt":["עָכוּז"]},"1673":{"h":"אֲכוּזָא","r":"A01673","html":"<div class=\"sense\"> ch. (v. <a href=\"#\" data-headword=\"*אָכוּז\">preced.</a>) = <a href=\"#\" data-headword=\"כּוּזָא\">כּוּזָא</a>. <span class=\"citation\">Taan. 20ᵇ</span> Ms. M., ed. <a href=\"#\" data-headword=\"כּוּזָא\">כוזא</a>.</div>","alt":[]},"1674":{"h":"אִכּוּם","r":"A01674","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>K’far Iccum</i>. <span class=\"citation\">Y. Snh. X, 29ᶜ</span> (Bab. <span class=\"citation\">ib. 110ᵇ</span> <span dir=\"rtl\">כ׳ עַכֹּו</span>; Joseph. B. J. II, 20, 6 Καφαρεκχώ); Tanḥ. (ed. Bub.) <span class=\"citation\">B’resh. 25</span> <a href=\"#\" data-headword=\"עַכּוֹ\">עכו</a> (Var. <span dir=\"rtl\">איכוס</span>); <span class=\"citation\">Ḥull. 55ᵇ</span> <a href=\"#\" data-headword=\"עִיכּוּם\">עִיכּוּם</a>; Y. Sot. VII, 21ᶜ bot. <span dir=\"rtl\">אמוס</span> (corr. acc.; Bab. <span class=\"citation\">Sot. 37ᵇ</span> <a href=\"#\" data-headword=\"עַכּוֹ\">עכו</a>).</div>","alt":["כפר א׳"]},"1675":{"h":"אַכְוַנְגַּר","r":"A01675","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (Pers. Khʷangar, Khʷalgar, Fl.) <i>table-steward, seneschal</i>. <span class=\"citation\">Keth. 61ᵃ</span> כו׳ Ar. (ed. <a href=\"#\" data-headword=\"אטורנגא\">אטורנגא</a> read <span dir=\"rtl\">אַכְוַונְגְּרָא</span>; Var. in Ar. <a href=\"#\" data-headword=\"כונדקא\">כונדקא</a>, corr. acc.).—Pl. <span dir=\"rtl\">אַכְוַנְגְּרֵי</span>. <span class=\"citation\">M. Kat. 12ᵃ</span> (Ar. <span dir=\"rtl\">אכנ׳</span>, ed. <span dir=\"rtl\">אבו׳</span>, corr. acc., Ms. M. <span dir=\"rtl\">אכוורנ׳</span>, cmp. Rabb. D. S. a. l., a. vol. VIII, p. 75). [<span class=\"citation\">Pes. 40ᵇ</span> Ms. M. <a href=\"#\" data-headword=\"בורדיקי\">בורדיקאי</a>, ed. <a href=\"#\" data-headword=\"בורדיקי\">בורדיקי</a>, Ar. <a href=\"#\" data-headword=\"כוורדקי\">כוורדקי</a>, prob. corrupt. of our w.]</div>","alt":["אֲכַנְגַּר","כְּוַאנְגַּר","אַכְוַו׳"]},"1676":{"h":"אַכְוַרְנְקָא","r":"A01676","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"אַכְוַנְגַּר\">preced.</a>; Pers. <i>Khorengah</i>, Arab. <i>Khawarnak</i>, Fl.) <i>dining place, dining hall in the garden</i>. <span class=\"citation\">Targ. Y. Deut. XXXII, 50</span>, <span dir=\"rtl\">א׳ … קי דמלכיא</span> a royal banqueting hall (put up for the wedding). <span class=\"citation\">Taan. 14ᵇ</span>; <span class=\"citation\">Meg. 5ᵇ</span> (distinguishing between <a href=\"#\" data-headword=\"בִּנְיָן\">בנין</a>, erection of a building, and <a href=\"#\" data-headword=\"נְטִיעָה\">נטיעה</a>, putting up a temporary structure), what is meant by ‘putting up a tent of joy?’—זה הנוטע אכ׳ של מלכים Ms. M. (Ar. <a href=\"#\" data-headword=\"כ׳\">כ׳</a>; ed. <a href=\"#\" data-headword=\"אֵיבָרָא\">אב׳</a>, corr. acc.) it means one putting up a regal banqueting tent (for his son’s wedding). <span class=\"citation\">Erub. 25ᵇ</span> <span dir=\"rtl\">אכ׳ וכ׳</span> (ed. <a href=\"#\" data-headword=\"אֵיבָרָא\">אב׳</a>) the Resh Gelutha was to have a banquet (on a Sabbath) in his garden.</div>","alt":["אַכְוַורְנְקֵי","כְּוַורְנַק"]},"1677":{"h":"*אכזווייא","r":"A01677","html":"<div class=\"sense\"> <span class=\"citation\">Targ. I Chr. I, 7</span> ed. Rahm.; <span class=\"citation\">Targ. Y. Gen. X, 4</span> <span dir=\"rtl\">אכזיא</span>, v. <a href=\"#\" data-headword=\"אֲכָיָיא\">אֲכָיָיא</a></div>","alt":[]},"1678":{"h":"אַכְזִיב","r":"A01678","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"> (b. h.) <i>Achzib</i> (Ecdippa, Ecdippon), a sea-town in Northern Palestine. Y. Shebi. V, 36ᵇ bot. he who travels <span dir=\"rtl\">מעכו לא׳</span> (<span class=\"citation\">Git. 7ᵇ</span>; Tosef. Oh. XVIII, 14 <span dir=\"rtl\">מעכו לכְזִיב</span>) from Acco (Ptolemais) to Ach. (Chezib).</div>","alt":[]},"1679":{"h":"אַכְזָר","r":"A01679","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַכְזָרִי\">אַכְזָרִי</a>. Denom. <i>Nithpa</i>. <span dir=\"rtl\">נִתְאַכְזָר</span> <i>to show one’s self merciless</i>. <span class=\"citation\">Num. R. s. 8</span>.</div>","alt":[]},"1680":{"h":"אַכְזְרָא","r":"A01680","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (= b. h. <a href=\"#\" data-headword=\"אַכְזָר\">אַכְזָר</a>) <i>cruel</i>. <span class=\"citation\">Targ. Job XLI, 2</span> (<span class=\"citation\">1</span>); a. e.—Lam. R. introd. (R. Joh. <span dir=\"rtl\">קטילא א׳</span> merciless slaughter.—Pl. <span dir=\"rtl\">אַכְזְרָאִין</span>. <span class=\"citation\">Targ. Deut. XXXII, 33</span>. Targ. J. II ibid. <span dir=\"rtl\">אַכְזְרוֹאֵי</span>.</div>","alt":["אַכְזְרָאָה"]},"1681":{"h":"אַכְזָרִי","r":"A01681","html":"<p class=\"morphology\">m.</p><div class=\"sense\">, <a href=\"#\" data-headword=\"אַכְזָרִית\">אַכְזָרִית</a> f. (b. h., <i>cruel, merciless;</i> also <i>strictly just</i>. <span class=\"citation\">Koh. R. to VII, 16</span>; a. e. <span class=\"citation\">B. Bath. 16ᵃ</span> bot.—Pl. <span dir=\"rtl\">אַכְזְרִיִּים</span>, <a href=\"#\" data-headword=\"אַכְזָרִי\">אַכְזָרִים</a>; fem. <a href=\"#\" data-headword=\"אַכְזְרִיּוּת\">אַכְזְרִיֹּות</a>. <span class=\"citation\">Pesik. R. s. 44</span>. <span class=\"citation\">Num. R. s. 8</span>. [<span class=\"citation\">Num. R. s. 9</span> <span dir=\"rtl\">מדת אכזרית</span>, read <a href=\"#\" data-headword=\"אַכְזְרִיּוּת\">אַכְזְרִיּוּת</a>.]</div>","alt":[]},"1682":{"h":"אַכְזְרִיאֵל","r":"A01682","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַכְרְזִיאֵל\">אַכְרְזִיאֵל</a></div>","alt":[]},"1683":{"h":"אַכְזְרִיּוּת","r":"A01683","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (b. h.) <i>cruelty, severity; strict justice</i>. <span class=\"citation\">Succ. 14ᵃ</span>; <span class=\"citation\">Num. R. s. 10</span> (p. 239, ed. Amst.) <span dir=\"rtl\">מדת א׳</span> the divine justice. <span class=\"citation\">Num. R. s. 9</span>, v. <a href=\"#\" data-headword=\"אַכְזָרִי\">אַכְזָרִי</a>.—<span class=\"citation\">Esth. R. to I, 15</span> <span dir=\"rtl\">שלא כדת אלא בא׳</span> not according to law but with cruelty.</div>","alt":[]},"1684":{"h":"אַכְזָרִית","r":"A01684","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַכְזָרִי\">אַכְזָרִי</a></div>","alt":[]},"1685":{"h":"אכטא","r":"A01685","html":"<div class=\"sense\">, <span class=\"citation\">Ab. Zar. 34ᵇ</span> Ar., v. <a href=\"#\" data-headword=\"*אַבְטָא\">אַבְטָא</a></div>","alt":[]},"1686":{"h":"אָכְטָא","r":"A01686","html":"<div class=\"sense\"> (ὀκτώ) <i>eight</i>. <span class=\"citation\">Gen. R. s. 14</span> beg.; a. e.; v. <a href=\"#\" data-headword=\"אִיטָא\">אִיטָא</a>. Tanḥ. (ed. Bub.) B’midb. 21 <span dir=\"rtl\">אקטו</span>.</div>","alt":["אוֹכְטָא"]},"1687":{"h":"אֲכָיָיא","r":"A01687","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Achaia</i>, the Roman province including Peloponnesus and northern Greece, south of Thessaly. <span class=\"citation\">Targ. I Chr. I, 7</span> <a href=\"#\" data-headword=\"*אכזווייא\">אכזווייא</a> (Var. <span dir=\"rtl\">איטליון</span>); <span class=\"citation\">Targ. Y. Gen. X, 4</span> <span dir=\"rtl\">אכזיא</span>; Y. Meg. I, 71ᵇ bot. <a href=\"#\" data-headword=\"אביא\">אביא</a> (<span class=\"citation\">Gen. R. s. 37</span> <a href=\"#\" data-headword=\"אִיטַלְיָא\">איטליא</a>), (for b. h. <a href=\"#\" data-headword=\"כִּיתּוֹת\">כִּתִּים</a>). [<span class=\"citation\">Sifré Num. 131</span> <a href=\"#\" data-headword=\"אביא\">אביא</a>, v. <a href=\"#\" data-headword=\"אסיא\">אסיא</a>.]</div>","alt":["אֲכָיָה"]},"1688":{"h":"אֲכִילָה","r":"A01688","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>eating, food, meal, dish</i>. <span class=\"citation\">Y. Sabb. I, 4ᵃ</span> top, a. e. <span dir=\"rtl\">אֲכִילַת בן דרוסא</span> (<span dir=\"rtl\">דרוסאי</span>, <a href=\"#\" data-headword=\"דַּרְדְּסָא\">דור׳</a>) the food Ben D’rosa used to eat, i.e. <i>third done</i>. <span class=\"citation\">Yoma 80ᵇ</span> <span dir=\"rtl\">א׳ גסה</span> excessive meal. <span class=\"citation\">Ib. 81ᵃ</span>, a. fr. <span dir=\"rtl\">א׳ בכזית</span> wherever <a href=\"#\" data-headword=\"אֲכַל\">אכל</a> (to eat) is mentioned in the Bible text, the size of an olive is meant. <span class=\"citation\">Y. Sot. III, 19ᵇ</span> top <span dir=\"rtl\">אכילת מזבח</span> the consumption (of sacrifices) on the altar. <span class=\"citation\">Zeb. 31ᵇ</span>; a. fr. <span dir=\"rtl\">א׳ פרס</span>, v. <a href=\"#\" data-headword=\"פְּרָס\">פְּרָס</a>. <span class=\"citation\">Kil. II, 10</span>, v. <a href=\"#\" data-headword=\"אָכְלָה II\"><span dir=\"rtl\">אָכְלָה</span> II</a>.—Pl. <span dir=\"rtl\">אֲכִילוֹת</span>. <span class=\"citation\">Pes. 78ᵃ</span>. <span class=\"citation\">Gen. R. s. 86</span>, beg. (play on <span dir=\"rtl\">אוכיל</span> <span class=\"citation\">Hos. XI, 4</span>) <span dir=\"rtl\">א׳ הרבה</span> (some ed. <span dir=\"rtl\">אוביל</span>—<a href=\"#\" data-headword=\"אֲבֵילוּת\">אבילות</a> corr. acc.) <i>purveyances</i></div>","alt":[]},"1689":{"h":"אֲכִילְתָּא","r":"A01689","html":"<div class=\"sense\"><span class=\"citation\">Targ. I Kings XIX, 8</span> (ed. Vien. <a href=\"#\" data-headword=\"אֲכִילְתָּא\">אֲכִילָתָא</a>).</div>","alt":[]},"1690":{"h":"*אָכִים","r":"A01690","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אָכַם\">אכם</a>) <i>black</i> (<i>wine</i>). <span class=\"citation\">Y. Gitt. VII, beg. 48ᶜ</span> <span dir=\"rtl\">א׳ גו סמיק</span>, v. <span dir=\"rtl\">סמיק</span>; (<span class=\"citation\">Y. Ter. I, 40ᵇ</span> <a href=\"#\" data-headword=\"אֵבוּס\">אבוס</a> read our w. or <a href=\"#\" data-headword=\"אִכּוּם\">אִכּוּם</a> = <a href=\"#\" data-headword=\"אִיכּוּמָא\">אִיכּוּמָא</a>); cmp. <span class=\"citation\">Gitt. 67ᵇ</span></div>","alt":[]},"1691":{"h":"אָכֵין","r":"A01691","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"כֵּן\">כֵּן</a>) <i>thus, in this manner</i>. <span class=\"citation\">Y. Ber. III, 6ᵃ</span> <span dir=\"rtl\">א׳ בר נש וכ׳</span> is it thus man deals with his neighbor? <span class=\"citation\">Y. Keth. II, 26ᶜ</span> bot. <span dir=\"rtl\">אתמול אמרת א׳ וכ׳</span> yesterday thou saidst so, and to-day thou sayest <i>otherwise;</i> a. fr. V. <a href=\"#\" data-headword=\"הָכֵן\">הָכֵין</a>.</div>","alt":["אָכֵן"]},"1692":{"h":"אכיס","r":"A01692","html":"<div class=\"sense\"> Af. of <span dir=\"rtl\">כסס</span>.</div>","alt":[]},"1693":{"h":"אכיסן","r":"A01693","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*לָאכִיסִין\">לָאכִיסִין</a></div>","alt":[]},"1694":{"h":"*אַכָּכָא","r":"A01694","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">אכך</span>, cmp. <a href=\"#\" data-headword=\"כַּכָּא\">כַּכָּא</a>) <i>ground</i> or <i>pounded drug, poultice</i>. <span class=\"citation\">Targ. Job XXX, 24</span>, Var. for <a href=\"#\" data-headword=\"אִסְפְּלָנִיתָא\">אספלניתא</a>.</div>","alt":[]},"1695":{"h":"אככמה","r":"A01695","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Prov. VII, 10</span>, read <a href=\"#\" data-headword=\"אַסְכְּמָא\">אַסְכְּמָא</a>.</div>","alt":[]},"1696":{"h":"אָכַל","r":"A01696","html":"<div class=\"sense\"> √אך <i>to rub</i>, </div><div class=\"sense\"><b>1)</b> <i>to gnaw, eat, consume</i>. Inf. in Y. freq. <span dir=\"rtl\">לוֹכַל</span> = <span dir=\"rtl\">לֶאֱכוֹל</span>. <span class=\"citation\">Ber. I, 1</span>; a. v. fr.</div><div class=\"sense\"><b>—2)</b>  trnsf. <i>to absorb, occupy, take away</i>. <span class=\"citation\">Y. Shebu. VII, 38ᵃ</span> <span dir=\"rtl\">בשרבית אוֹכֶלֶת בו</span> when interests gnaw on (absorb) the property. <span class=\"citation\">Y. Erub. IV, 21ᵈ</span> bot. <span dir=\"rtl\">ד׳ אמות אוֹכְלוֹת וכ׳</span> four cubits entering into the area of Tiberias. <span class=\"citation\">Num. R. s. 4</span> <span dir=\"rtl\">כמה לוחות אוֹכְלוֹת</span> how much space did the tablets occupy &amp;c.? <span class=\"citation\">B. Bath. 14ᵃ</span> (interchanging with <span dir=\"rtl\">איגרות</span>, Var. <span dir=\"rtl\">אוגדות</span>, v. Rabb. D. S. a. l. note 5, 6).</div><div class=\"sense\"><b>—3)</b>  (euphem.) <i>to sleep with</i>. <span class=\"citation\">Keth. V, 9</span>, differ. of opin. <span class=\"citation\">ib. 65ᵇ</span>; Y. ib. 30ᵇ top a. bot.</div><div class=\"sense\"><b>Nif. נֶאֱכַל</b> <div class=\"sense\"><i>to be eaten</i> &amp;c. <span class=\"citation\">Zeb. I, 3</span>; <span class=\"citation\">Ber. I, 1</span>; a. fr.</div></div><div class=\"sense\"><b>Pi. אִיכֵּל</b> <div class=\"sense\"><i>to consume, burn</i>. <span class=\"citation\">Tam. I, 4</span> <span dir=\"rtl\">המְאוּכָּלוֹת הפנימיות</span> (Talm. ed. <span dir=\"rtl\">המעו׳</span>) the thoroughly lighted coals in the centre; Y. Yoma II, 39ᶜ</div></div><div class=\"sense\"><b>Hif. הֶאֱכִיל</b> <div class=\"sense\"><i>to give to eat, cause to eat</i>. <span class=\"citation\">Keth. V, 3</span> <span dir=\"rtl\">היבם אינו מַאֵכִיל וכ׳</span> the Yabam does not transfer the privilege of eating T’rumah to his sister-in-law. <span class=\"citation\">Kidd. 31ᵃ</span> <span dir=\"rtl\">יש מאכיל וכ׳</span> one may feed his father on pheasants &amp;c.; a. fr.</div></div><div class=\"sense\"><b>Hithpa. a. Nithpa. הִתְאַכֵּל  נִתְאַכֵּל</b> <div class=\"sense\"><b>1)</b> <i>to be consumed, burnt up, digested</i>. <span class=\"citation\">Ber. VIII, 7</span> עד כדי שיִתְאַכֵּל וכ׳ Ar. (ed. <span dir=\"rtl\">שיתע׳</span>) until the food is digested (or absorbed) in his bowels. <span class=\"citation\">Tam. II, 1</span>; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to be worn off, spent</i>. <span class=\"citation\">Snh. VI, 12</span> Y. ed. <span dir=\"rtl\">נתא׳ הבשר</span> (Mish. ib. VI, 6 <span dir=\"rtl\">נתע׳</span>) when the flesh of the corpse was gone. <span class=\"citation\">Cant. R. to IV, 4</span> <span dir=\"rtl\">שלא נתא׳ אחת מהן</span> none of them was worn off. <span class=\"citation\">Kidd. 59ᵃ</span> <span dir=\"rtl\">נתא׳ המעות</span> the money was spent; a. e.</div></div>","alt":[]},"1697":{"h":"אֲכַל","r":"A01697","html":"<div class=\"sense\"></div><div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"אָכַל\">same</a>.—Inf. <a href=\"#\" data-headword=\"מֵיכַל\">מֵיכַל</a>, <span dir=\"rtl\">מֵיכוּל</span>. <span class=\"citation\">Targ. Gen. II, 16</span>; a. fr.—<span class=\"citation\">Y. Ter. VIII, 46ᵃ</span> <span dir=\"rtl\">כד אתון יֵיכלון</span> when they came and were about eating; <span class=\"citation\">ib.</span> (more corr.) <span dir=\"rtl\">אתון מיכל</span>; a. fr.</div><div class=\"sense\"><b>—2)</b>  with <span dir=\"rtl\">קרצי</span> prop. <i>to eat</i> (<i>the bread of</i>) <i>destruction, eat the informer’s bread</i>, hence <i>to inform against.</i> <span class=\"citation\">Dan. III, 8</span>; <span class=\"citation\">VI, 25</span>.—<span class=\"citation\">Targ. Ps. XV, 3</span>; a. fr.—<span class=\"citation\">Gitt. 56ᵃ</span> <span dir=\"rtl\">איכול בהו קו׳</span>; <span class=\"citation\">Lam. R. to IV, 2</span> איכול קרצהון I will inform against them.</div><div class=\"sense\"><b>Af. אוֹכַל  אַיְיכַל</b> <div class=\"sense\"><i>to give to eat, to support</i>. Y. Ter. X, 47ᵇ bot. <span dir=\"rtl\">אוכלה ליה</span> he gave it to him to eat. <span class=\"citation\">Gen. R. s. 48</span>, end (read:) <span dir=\"rtl\">אוכלית אשקית לוי</span> hast thou given (thy guest) to eat? to drink? do escort him, i.e. perform thy duties fully. Y. Kidd. I, 61ᵇ <span dir=\"rtl\">הוה מייכל לאבוי וכ׳</span> fed his father on &amp;c.; a. fr.</div></div><div class=\"sense\"><b>Ithpe. אִתְאֲכַל  אִתְאֲכִיל</b> <div class=\"sense\">, <a href=\"#\" data-headword=\"אֲכַל\">אִתְאָכִיל</a> <i>to be eaten, consumed</i>. <span class=\"citation\">Targ. Ps. LXVIII, 23</span>; a. fr. Tanḥ. Emor, 6 <span dir=\"rtl\">ומה דהבא מִתְאֲכִיל וכ׳</span>; <span class=\"citation\">Lev. R. s. 27</span> <span dir=\"rtl\">ומה זה וכ׳</span> what is this? do they eat gold &amp;c.? <span class=\"citation\">Kidd. 59ᵃ</span> <span dir=\"rtl\">קא מתאכלי</span> were eaten up (spent). [אכלי Af. of <a href=\"#\" data-headword=\"כלי\">כלי</a> <i>to cry</i>, v. <a href=\"#\" data-headword=\"כלי\">כלי</a>.]</div></div>","alt":["אָכַל I"]},"1698":{"h":"אֲכַל II","r":"A01698","html":"<div class=\"sense\"> (sec. r. of <span dir=\"rtl\">כול</span>) <i>to measure</i>. <span class=\"citation\">Ned. 51ᵃ</span> <span dir=\"rtl\">ליכיל לי מר</span> please measure for me. Ruth R. introd. 2. <span dir=\"rtl\">הא … סאה תקום אכול</span> (read <span dir=\"rtl\">סאתה קום</span>) here is the bag and here the measure, get up and fill it; v. <a href=\"#\" data-headword=\"כּוּל\">כּוּל</a>.</div>","alt":[]},"1699":{"h":"אֹכֶל","r":"A01699","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אוֹכֶל\">אוֹכֶל</a></div>","alt":[]},"1700":{"h":"אַכָּלָא","r":"A01700","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אֲכַל\">אכל</a>) <i>eater</i>. <span class=\"citation\">Targ. Jud. XIV, 14</span>.</div>","alt":[]},"1701":{"h":"אַכְלָאִין","r":"A01701","html":"<div class=\"sense\">, <span class=\"citation\">Targ. Ps. CIV, 21</span> Ms., ed. <span dir=\"rtl\">אכלין</span>, v. <a href=\"#\" data-headword=\"כְּלִי\">כְּלִי</a><i>to cry</i>.</div>","alt":[]},"1702":{"h":"אַכְלְבָא","r":"A01702","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">כלב</span>; v. Ges. H. Dict. s. v.; cmp. <a href=\"#\" data-headword=\"כְּלוּב\">כְּלוּב</a>, <a href=\"#\" data-headword=\"כְּלִיבָה\">כְּלִיבָה</a>; Var. lect. <a href=\"#\" data-headword=\"אַכְלְבָא\">אַכְלְכָא</a>, v. infra) <i>shed, store-room</i>. <span class=\"citation\">B. Mets. 63ᵇ</span> <span dir=\"rtl\">חיטי … באַכְלְבָאִי</span> (v. Var. lect. in Rabb. D. S. a. l.; Mss. a. Ar. <span dir=\"rtl\">אכלכא</span>) would my wheat have gone to ruin in my granary? <span class=\"citation\">Taan. 24ᵃ</span> (v. Rabb. D. S. a. l.).—Pl. <span dir=\"rtl\">אַכְלְבֵי</span>. <span class=\"citation\">Gitt. 56ᵃ</span> <span dir=\"rtl\">אכלבא … שתין א׳ וכ׳</span> one shed of wheat requires sixty sheds of wood (for baking). <span class=\"citation\">B. Mets. 72ᵇ</span> <span dir=\"rtl\">חיטי דא׳</span> (Ms. M. <span dir=\"rtl\">באכלכי</span></div>","alt":[]},"1703":{"h":"אָכְלָה I","r":"A01703","html":"<p class=\"morphology\">f.</p><div class=\"sense\">, (<a href=\"#\" data-headword=\"אֲכַל\">אכל</a>) <span dir=\"rtl\">א׳ טִינָא</span> <i>mud-eater</i>, name of a parasitic worm in fishes. <span class=\"citation\">B. Bath. 73ᵇ</span> (Ms. M. <span dir=\"rtl\">אבל׳ טינא</span>; oth. var., v. Rabb. D. S. a. l. note).</div>","alt":[]},"1704":{"h":"אָכְלָה II","r":"A01704","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (אָכֵל 2) <i>occupied space.</i> <span class=\"citation\">Kil. II, 10</span> Y. ed. <span dir=\"rtl\">אָכְלַת הגפן</span> (Mish. ed. <a href=\"#\" data-headword=\"אֲכִילָה\">אֲכִילַת</a>; Y. Ib. 28ᵃ <a href=\"#\" data-headword=\"אוֹכְלָה\">אוֹכְלַת</a>) the soil occupied by the vine roots, <span dir=\"rtl\">א׳ הקבר</span> the ground needed for the formation of the cave, i.e. as far as the roots &amp;c. extend.</div>","alt":["אוֹכְלָה"]},"1705":{"h":"אָכְלוֹזָא","r":"A01705","html":"<div class=\"sense\">, v. <span dir=\"rtl\">אוֹכְלוֹסָא</span></div>","alt":[]},"1706":{"h":"אַכְלוֹנָס","r":"A01706","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כְּלוֹנָס\">כְּלוֹנָס</a></div>","alt":[]},"1707":{"h":"*אָכְלוֹשֵׂי","r":"A01707","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (v. <span dir=\"rtl\">אוֹכְלוֹסָא</span>) <i>public laborers, working men</i>. <span class=\"citation\">B. Mets. 77ᵃ</span>; v., however, <a href=\"#\" data-headword=\"*אַבְלוֹשֵׁי\">אַבְלוֹשֵׁי</a>.</div>","alt":[]},"1708":{"h":"אַכְלִי","r":"A01708","html":"<div class=\"sense\"><i>to cry</i>, Af. of <a href=\"#\" data-headword=\"כְּלִי\">כְּלִי</a>. <span class=\"citation\">Targ. Ps. CIV, 24</span> <span dir=\"rtl\">אָכְלִין</span>, some ed., read <a href=\"#\" data-headword=\"אַכְלִי\">אַכְלִין</a>.</div>","alt":[]},"1709":{"h":"אַכְלָיוּתָא","r":"A01709","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"אַכְלִי\">preced.</a>) <i>noise, cry</i>. <span class=\"citation\">Targ. Job IV, 10</span>; a. e.</div>","alt":[]},"1710":{"h":"אכלים","r":"A01710","html":"<div class=\"sense\"> <span class=\"citation\">Y. Ab. Zar. IV, 43ᵈ</span>, v. <a href=\"#\" data-headword=\"אוֹכֶל\">אוֹכֶל</a></div>","alt":[]},"1711":{"h":"אַכְלָן","r":"A01711","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אָכַל\">אָכַל</a>) <i>a greedy eater</i>. <span class=\"citation\">Y. Maasr. III, 50ᵈ</span> bot.</div>","alt":[]},"1712":{"h":"אכלסין","r":"A01712","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֲלַכְסִין\">אֲלַכְסִין</a></div>","alt":[]},"1713":{"h":"אָכַם","r":"A01713","html":"<div class=\"sense\"> (√<span dir=\"rtl\">כם</span>; cmp. <a href=\"#\" data-headword=\"חַם\">חם</a>) <i>to be sun-burnt, black, dark-colored.</i> <i> Nithpa. to be blackened</i>. <a href=\"#\" data-headword=\"אָכַל\">נִתְאַכֵּם</a>. <span class=\"citation\">Sot. 15ᵇ</span> <span dir=\"rtl\">נִתְאַכְּמוּ פניו</span> the outside of the pot grew black (Var. <span dir=\"rtl\">נתפחמו</span>).</div>","alt":[]},"1714":{"h":"*אִכְמַר","r":"A01714","html":"<div class=\"sense\"> (= <span dir=\"rtl\">חכ׳</span>, onomatop.; cmp. <a href=\"#\" data-headword=\"חָכַךְ I\">חכך</a> <i>Pi.</i>) <i>to cough</i>. <span class=\"citation\">Kidd. 81ᵇ</span> top. <span dir=\"rtl\">א׳ שדא ביה כיחו</span> he coughed, and threw his phlegm into the cup. [Perh. <span dir=\"rtl\">כסא אַ׳</span> a <i>black, dirty</i> cup?]</div>","alt":[]},"1715":{"h":"אָכֵן","r":"A01715","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אָכֵין\">אָכֵין</a></div>","alt":[]},"1716":{"h":"אֲכַנְגַּר","r":"A01716","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַכְוַנְגַּר\">אַכְוַנְגַּר</a></div>","alt":[]},"1717":{"h":"אכנס","r":"A01717","html":"<div class=\"sense\"> <span class=\"citation\">Tosef. Ḥull. III</span> (<span class=\"citation\">IV), 27</span>, v. <a href=\"#\" data-headword=\"*אכספטיאס\">אכספטיאס</a></div>","alt":[]},"1718":{"h":"*אַכְסָא","r":"A01718","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>mad.</i> (?) <span class=\"citation\">Gitt. 69ᵃ</span> (a word in a charm formula). Cmp. <a href=\"#\" data-headword=\"*אַכְתָּנָא\">אַכְתָּנָא</a>.</div>","alt":[]},"1719":{"h":"אכסגרון","r":"A01719","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אָכְסִיגָרוֹן\">אָכְסִיגָרוֹן</a></div>","alt":[]},"1720":{"h":"אַכְסַדְרָא","r":"A01720","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (ἐξέδρα, exedra) (Greek) <i>a covered place in front of the house;</i> (Roman) <i>recess, parlor, hall for conversations and discussions</i>. <span class=\"citation\">Targ. Jud. III, 23</span>. [Pl. <span class=\"citation\">Targ. Ps. CIV, 3</span>, v. <a href=\"#\" data-headword=\"אִינְדְּרָא\">אִינְדְּרָא</a>.] <span class=\"citation\">B. Bath. 11ᵇ</span> <span dir=\"rtl\">א׳ דבי רב</span> the hall of the school house (philosophers’ exedra, v. Sm. Ant. s. v.), contrad. to <span dir=\"rtl\">א׳ רומייתא</span> (Ms. Oxf. <span dir=\"rtl\">דרומיתא</span>, v. Rabb. D. S. a. l. note 10) Roman exedra (open but surrounded by a railing). <span class=\"citation\">Ib. 25ᵃ</span>; <span class=\"citation\">25ᵇ</span> <span dir=\"rtl\">עולם לא׳ וכ׳</span> the world resembles an exedra the northernmost side of which is not covered (מסוככת Ms. M., ed. <span dir=\"rtl\">מסובבת</span> not surrounded); a. fr.—Pl. <span dir=\"rtl\">אַכְסַדְרָאוֹת</span>. <span class=\"citation\">Tam. 28ᵇ</span> <span dir=\"rtl\">א׳ של בנין</span> exedras forming, or belonging to, a structure (opp. to open exedra with plants).</div>","alt":["אַכְסִדְרָא","אַכְסִדְרָה"]},"1721":{"h":"אֶכְסוֹרִיָּה","r":"A01721","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (ἐξορία) <i>exile, banishment</i>. <span class=\"citation\">Lev. R. s. 18</span> <span dir=\"rtl\">אכסי׳</span> (Ar. <a href=\"#\" data-headword=\"כסוריא\">כסוריא</a>) (corr. acc.).</div>","alt":[]},"1722":{"h":"אכסי","r":"A01722","html":"<div class=\"sense\"> <span class=\"citation\">Tosef. Kel. B. Kam. VII, 4</span> <span dir=\"rtl\">א׳ קמטרא</span>, read with R. S. to <span class=\"citation\">Kel. X, 1</span> <span dir=\"rtl\">עף</span> [<a href=\"#\" data-headword=\"אַף I\">אף</a>] <span dir=\"rtl\">כסוי קמטרא</span> also the lid of a chest.</div>","alt":[]},"1723":{"h":"אָכְסִיגָרוֹן","r":"A01723","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (ὀξύγαρον, oxygarum) <i>a sauce of vinegar and garum;</i> in gen. <i>a sauce of all kinds of vegetables.</i> <span class=\"citation\">Ber. 35ᵇ</span> bot. Ms. M. (ed. <span dir=\"rtl\">אנס׳</span>); <span class=\"citation\">Yoma 76ᵃ</span>; <span class=\"citation\">Shebu. 23ᵃ</span>. <span class=\"citation\">Tosef. Bets. II, 16</span>. Y. Shebi. VIII, 38ᵃ top <span dir=\"rtl\">אָקְסִי׳</span>; <span class=\"citation\">Tosef. Ter. IX, 10</span>; ib. <span class=\"citation\">Shebi. VI, 3</span> <a href=\"#\" data-headword=\"סְנִיגְרוֹן\">סְנִיגְרוֹן</a>.—Pl. <span dir=\"rtl\">אָכְסִיגָרִיֹּות</span>, abbrev. <a href=\"#\" data-headword=\"סִגָּרִיוֹת\">סִגָּרִיֹּות</a> <i>vegetable sauces, vegetables used for oxygarum.</i> <span class=\"citation\">Shebi. IX, 5</span> ed. (Var. <a href=\"#\" data-headword=\"סנריות\">סנריות</a>, <a href=\"#\" data-headword=\"סנדיות\">סנדיות</a>, <a href=\"#\" data-headword=\"סגדיות\">סגדיות</a>, Ms. M. <span dir=\"rtl\">הנידיות</span>); <span class=\"citation\">Tosef. ib. VII, 13</span> <a href=\"#\" data-headword=\"אגוטרי\">אגוטרי</a> read <span dir=\"rtl\">אָגְזוּגָרִין</span>; Sifra B’har <span class=\"citation\">Par. II</span> ch. 3 <a href=\"#\" data-headword=\"סַנְדְּרֵי\">סנדריות</a> (Rabad <a href=\"#\" data-headword=\"סנדיות\">סנדיות</a>; corr. acc.). [<span class=\"citation\">Koh. R. to XI, 9</span> <a href=\"#\" data-headword=\"*ארגסטירין\">ארגסטירין</a> read <span dir=\"rtl\">אוֹגְסִיגָרִין</span>.]</div>","alt":[]},"1724":{"h":"אַכְסְיוֹמָא","r":"A01724","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (ἀξίωμα) <i>request, petition</i>. <span class=\"citation\">Midr. Till. to Ps. VI</span>, end <span dir=\"rtl\">אחרים מקבלים אנ׳ וכ׳</span> (corr. <span dir=\"rtl\">אכ׳</span>) others receive the petition presented to him <span dir=\"rtl\">אני איני מבקש אלא אנסיומין שלי</span> (corr. acc., insert <span dir=\"rtl\">שאתה תקבל</span>) I only ask that thou mayest receive my petition thyself. <span class=\"citation\">Midr. Till. to Ps. CII</span> <span dir=\"rtl\">אל תתן א׳ שלי בתוכה</span> (read <span dir=\"rtl\">שלו</span>); [the entire passage is obscure and seems out of place].</div>","alt":[]},"1725":{"h":"אכסיוט","r":"A01725","html":"<div class=\"sense\"> <span class=\"citation\">Gen. R. s. 46</span>, v. <a href=\"#\" data-headword=\"אַקְסְיוֹס\">אַקְסְיוֹס</a></div>","alt":["אכסיוס"]},"1726":{"h":"אכסיטורין","r":"A01726","html":"<div class=\"sense\">, read <a href=\"#\" data-headword=\"אֶגְסִיטֵרִין\">אֶכְסִיטֵירִין</a>, v. <a href=\"#\" data-headword=\"אֶגְסִיטֵרִין\">אֶגְסִיטֵרִין</a></div>","alt":[]},"1727":{"h":"אכסילין","r":"A01727","html":"<div class=\"sense\"> <span class=\"citation\">Tosef. Kil. V, 26</span>, Var. of <span dir=\"rtl\">כליסים</span>, v. <a href=\"#\" data-headword=\"*אכסלי\">אכסלי</a></div>","alt":[]},"1728":{"h":"אכסיריה","r":"A01728","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֶכְסוֹרִיָּה\">אֶכְסוֹרִיָּה</a></div>","alt":[]},"1729":{"h":"*אַכְסִילְגֹּוס","r":"A01729","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (ξύληγος) <i>wood-carrier, forester</i>. <span class=\"citation\">Men. 97ᵃ</span> <span dir=\"rtl\">כליא׳</span> common wooden vessels; <span class=\"citation\">Ḥag. 26ᵇ</span> כלי אכסלגס Ar. (ed. <a href=\"#\" data-headword=\"אכסלגים\">אכסלגים</a> Ms. M. <span dir=\"rtl\">אבלוגסין</span> corr. acc.).—<span class=\"citation\">Zeb. 94ᵃ</span> <span dir=\"rtl\">כלי אַכְסִלְגְּיָא</span> (Ms. M. <span dir=\"rtl\">אכסלמוס</span>) forester’s apparel (leather covers &amp;c.); v. <a href=\"#\" data-headword=\"*אַבְלוּסְמוֹס\">אַבְלוּסְמוֹס</a>.</div>","alt":["אַכְסִלְגָּס"]},"1730":{"h":"אַכְסִלְגְּיָא","r":"A01730","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (ξυληγία) <i>foresting;</i> v. <a href=\"#\" data-headword=\"*אַכְסִילְגֹּוס\">preced.</a></div>","alt":[]},"1731":{"h":"אכסלגים","r":"A01731","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*אַכְסִילְגֹּוס\">אַכְסִילְגֹּוס</a></div>","alt":["אַכְסִלְגָּס"]},"1732":{"h":"*אכסלי","r":"A01732","html":"<div class=\"sense\">, <span class=\"citation\">Tosef. Kil. V, 26</span> (ed. Zuck. <span dir=\"rtl\">כליסים הגרגים</span>, Var. <span dir=\"rtl\">כליסיס</span>, <a href=\"#\" data-headword=\"אכסילין\">אכסילין</a>) prob. <span dir=\"rtl\">כלים אַכְסִילִינִין</span> (ξύλινος) <i>cotton clothes</i>.</div>","alt":["אכסלית"]},"1733":{"h":"*אִכְסֵן","r":"A01733","html":"<div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"*אַכְסָן II\"><span dir=\"rtl\">אַכְסָן</span> II</a>) <i>to harbor a guest.</i> <i> Nithpa.</i> נִתְאַכְסֵן <i>to be received; to lodge with</i>. <span class=\"citation\">Midr. Till. to Ps. CXVI</span>.</div>","alt":[]},"1734":{"h":"אַכְסָן","r":"A01734","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (transpos. of <span dir=\"rtl\">אסכנא</span>, v. <a href=\"#\" data-headword=\"סִכָּא\">סִכָּא</a>; h. <i>weaver’s pin</i>. <span class=\"citation\">Targ. Jud. XVI, 13</span>; <span class=\"citation\">14</span>; a. fr.—*<span class=\"citation\">Sabb. 151ᵇ</span> אפי׳ מליא כא׳ דגרדאי Ms. Oxf. a. Ar. (ed. <span dir=\"rtl\">כאביסנא</span>; Ms. M. <span dir=\"rtl\">מלי אכסניא וגרדאי</span>) even if the painting stick is as thick (with paint) as a weaver’s pin.</div>","alt":["אַכְסְנָא I"]},"1735":{"h":"*אַכְסָן II","r":"A01735","html":"<div class=\"sense\"> pl. <span dir=\"rtl\">אַכְסָנִים</span>, v. <a href=\"#\" data-headword=\"אַכְסְנָא II\">next art.</a></div>","alt":[]},"1736":{"h":"אַכְסְנָא II","r":"A01736","html":"<div class=\"sense\">, read:</div>","alt":[]},"1737":{"h":"אַכְסְנָאִי","r":"A01737","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (deriv. of <a href=\"#\" data-headword=\"אַכְסַנְיָא\">אַכְסַנְיָא</a>) <i>stranger, guest, lodger;</i> also (ξένος) <i>hired soldier</i>. <span class=\"citation\">Y. Erub. II, end 20ᵇ</span> <span dir=\"rtl\">יֵעָשֶׂה כא׳</span> let him be considered as a stranger (transient lodger). <span class=\"citation\">Tosef. Shebi. V, 21</span> <a href=\"#\" data-headword=\"אַכְסָן\">אכסנא</a> some ed. (ed. Zuck. <span dir=\"rtl\">אַכְסְנָיִין</span> pl.) <i>soldier</i>, v. <a href=\"#\" data-headword=\"אַכְסַנְיָא\">אַכְסַנְיָא</a> 3).—<span class=\"citation\">Arakh. 16ᵇ</span> <span dir=\"rtl\">א׳ דאקראי</span> an occasional guest. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">א׳ פוגם ונפגם</span> a traveller (constantly changing his lodging place) discredits others a. himself; a. fr.—Pl. <span dir=\"rtl\">אַכְסְנָיִין</span> (v. supra), <span dir=\"rtl\">אַכְסְנִין</span> <span class=\"citation\">Lev. R. s. 27</span>.—<a href=\"#\" data-headword=\"אַכְסְנָאִי\">אַכְסְנֵי</a>, <a href=\"#\" data-headword=\"אַכְסַנְיָא\">אַכְסְנַיָּא</a>, <a href=\"#\" data-headword=\"אַכְסְנָאִי\">אַכְסְנָאֵי</a>. <span class=\"citation\">Targ. Y. II, Gen. XLVII, 21</span> <span dir=\"rtl\">א׳ גילולאי</span> exiled strangers. <span class=\"citation\">Gen. R. s. 50</span> <span dir=\"rtl\">הב לאילין א׳</span> give these travellers &amp;c.—*<span dir=\"rtl\">אַכְסָנִים</span>. <span class=\"citation\">Num. R. s. 10</span> (p. 239ᶜ ed. Amst.) <span dir=\"rtl\">מנהג הא׳</span> custom of hospitality [prob. <a href=\"#\" data-headword=\"אַכְסַנְיָא\">אכסניא</a>].</div>","alt":["אַכְסְנַאי","אַכְסְנַי"]},"1738":{"h":"*אַכְסַנְדַּרְיָא","r":"A01738","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"אֲלֶכְסַנְדְּרִית\">אלכסנדרית</a>) <i>an Alexandrian merchantman</i> (Alexandria navis); trnsf. <i>a high mast</i> (satyrically for <i>cross, gallows</i>). Targ. II, <span class=\"citation\">Esth. VII, 10</span> the son of Hamdatha wants to ascend <span dir=\"rtl\">לא׳ דבר פנדירא</span> (Ms. <span dir=\"rtl\">לאַלַכְסַ׳</span>) the mast of the son of Pandira (is to be hanged). <span class=\"citation\">Neg. XII, 1</span> <span dir=\"rtl\">באכסנדריא</span> (marginal vers. in Mishn. edit., text <a href=\"#\" data-headword=\"אִסְקַרְיָא\">אסקריא</a>, Var. <a href=\"#\" data-headword=\"אַסְדָּא\">אסדא</a>, <span dir=\"rtl\">אכסדיא</span>, <a href=\"#\" data-headword=\"*אִסְכַּדְיָא\">אסכדיא</a> q. v.) in the <i>rigging</i></div>","alt":["אַכְסַנְדַרְיָה"]},"1739":{"h":"אַכְסַנְיָא","r":"A01739","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (ξενία) </div><div class=\"sense\"><b>1)</b> <i>hospitality, lodging</i>. <span class=\"citation\">Ex. R. s. 35</span> <span dir=\"rtl\">א׳ נעשו וכ׳</span> (<span class=\"citation\">Pes. 118ᵇ</span>, corr. acc) they were a lodging place to my children in Egypt (they offered hospitality to &amp;c.).—בעל א׳ <i>host</i>. <span class=\"citation\">Pesik. R. s. 11</span>; cmp. <a href=\"#\" data-headword=\"אוּשְׁפִּיזְכָן\">אוּשְׁפִּיזְכָן</a>.—<span class=\"citation\">B. Mets. 85ᵃ</span> <span dir=\"rtl\">תורה מחזרת על א׳ שלה</span> scholarship likes to come around to its inn again (to be hereditary in the family); a. fr.</div><div class=\"sense\"><b>—2)</b>  (= <span dir=\"rtl\">בעלת א׳</span>) <i>hostess</i>. <span class=\"citation\">B. Mets. 87ᵃ</span> one must inquire <span dir=\"rtl\">בא׳ שלו</span> after the health of his hostess.</div><div class=\"sense\"><b>—3)</b> <i>quarter given to troops on march</i> or <i>to transient poor men;</i> also <i>the passing troop</i>, or <i>the passing poor;</i> (individ.) <i>beggar</i>. <span class=\"citation\">Targ. Job XXXI, 32</span>; a. e.—<span class=\"citation\">B. Bath. 11ᵇ</span> <span dir=\"rtl\">א׳ לפי בני אדם</span> the quartering (of soldiers takes place) in proportion to the number of inmates (of each house). <span class=\"citation\">Dem. III, 1</span>; v. Y. ib. 23ᵇ top. <span class=\"citation\">Tosef. Shebi. V, 21</span> <span dir=\"rtl\">אין מאכילין אכסניין וכ׳</span> ed. Zuck. (Var. <span dir=\"rtl\">את אכסניא</span>) you are not allowed to give … to soldiers quartered with you. <span class=\"citation\">Y. Ber. IX, 13ᵇ</span> <span dir=\"rtl\">ההן א׳ עלובתא</span> this poor beggar. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">א׳ עלו׳</span> poor beggars. <span class=\"citation\">Lev. R. s. 34</span>. <span class=\"citation\">Lam. R. to I, 1</span> <span dir=\"rtl\">(<span dir=\"rtl\">חד מירו׳</span>) <span dir=\"rtl\">בר נש א׳</span></span> a poor man.</div><div class=\"sense\"><b>—4)</b> <i>a gathering of scholars entertained by the hospitable of the place</i>. <span class=\"citation\">Y. Ber. IV, 8ᵇ</span> top <span dir=\"rtl\">נפיק לא׳</span> leaving for the scholars’ meeting. Bab. <span class=\"citation\">Ber. 63ᵇ</span> <span dir=\"rtl\">פתח בכבוד א׳</span> opened his speech in honor of hospitality to scholars.</div>","alt":[]},"1740":{"h":"אַכְסַנְיָאוּת","r":"A01740","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"אַכְסַנְיָא\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>stranger’s condition, exile</i>. <span class=\"citation\">Sot. 36ᵇ</span></div><div class=\"sense\"><b>—2)</b> <i>soldier’s pay</i>. Mekh. B’shall. Shirah 4; <span class=\"citation\">Yalk. Ex. 246</span>; a. e. (interchanging with <a href=\"#\" data-headword=\"אָפְסַנְיָא\">אפסניא</a> q. v.).</div>","alt":["אַכְסַנְיוּת"]},"1741":{"h":"*אכסניי","r":"A01741","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (read <span dir=\"rtl\">אכסנופרוכא</span> Xenoparochus) <i>one who provides for strangers</i> or <i>soldiers, quartermaster</i>. <span class=\"citation\">Y. B. Kam. III, 3ᶜ</span> top <span dir=\"rtl\">ההן א׳ פ׳ … שרי למיחשדוניה וכ׳</span> (read <span dir=\"rtl\">למישחדוניה</span>) it is permissible to bribe the quartermaster (to let you off) before the Romans enter (the place), but not after that (when one man’s release from quartering duty is a direct injury to the other inhabitants).</div>","alt":["א׳ פרכא"]},"1742":{"h":"*אכספטיאס","r":"A01742","html":"<div class=\"sense\">, <span class=\"citation\">Ḥull. 66ᵇ</span>, <span class=\"citation\">Ab. Zar. 39ᵃ</span> <span dir=\"rtl\">אקונס ואפונס … וא׳</span> (v. Var. lect. Rabb. D. S. a. l.), <span class=\"citation\">Tosef. Ḥull. III</span> (<span class=\"citation\">IV), 27</span> <span dir=\"rtl\">קולייס ופולמוס כספתיאס אכנס וכ׳</span>, restore (<a href=\"#\" data-headword=\"א\">א</a>)<span dir=\"rtl\">קולייס ופילמוס</span> (<a href=\"#\" data-headword=\"א\">א</a>)<span dir=\"rtl\">כסיפיאס</span> (<span dir=\"rtl\">כסיפייס</span>) <span dir=\"rtl\">ואתניאס</span> (<span dir=\"rtl\">ואתנייס</span>) <span dir=\"rtl\">וכ׳</span> κολίας, πήλαμυς, ξίφιας, ἀθνίας, names of fishes (v. Greek Dict.) <i>Colias, Pelamys, Xiphias, Athnias</i> and <i>Thunny</i>; v. <a href=\"#\" data-headword=\"אֲטוּנָס\">אֲטוּנָס</a>.</div>","alt":["אכספטייס"]},"1743":{"h":"אכסרא","r":"A01743","html":"<div class=\"sense\"> <span class=\"citation\">Tosef. Ohol. XVIII, 5</span>, v. <a href=\"#\" data-headword=\"*אִסְכַּדְיָא\">אסכדיא</a> a. <a href=\"#\" data-headword=\"*אַכְסַנְדַּרְיָא\"><a href=\"#\" data-headword=\"*אַכְסַנְדַּרְיָא\">אכסנדריא</a>.</a>—[V. also next w.]</div>","alt":[]},"1744":{"h":"אַכְסָרָה","r":"A01744","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (used as adverb; a comp. of <a href=\"#\" data-headword=\"אַךְ I\">אך</a> a. <a href=\"#\" data-headword=\"סָרַח I\">סרח</a> <i>less or more</i>, v. <a href=\"#\" data-headword=\"נכי\">נכי</a>) <i>in a lump, on measuring by sight.</i> <span class=\"citation\">Dem. II, 5</span> (Ms. M. <a href=\"#\" data-headword=\"אַסְכְּרָא\">אסכרא</a>); Y. ib. III, 23ᶜ <span dir=\"rtl\">מוכרן א׳</span> he sells them in a lump (as many as there may be). <span class=\"citation\">Maas. Sh. IV, 2</span>. Sifra B’ḥukk. Par. 4, ch. X; a. e.</div>","alt":[]},"1745":{"h":"אָכַף","r":"A01745","html":"<div class=\"sense\">(b. h. <a href=\"#\" data-headword=\"אָכַף\">אָכַף</a>, √<span dir=\"rtl\">כף</span>, v. <span dir=\"rtl\">כפף</span>), denomin. of <a href=\"#\" data-headword=\"אוּכָּף\">אוכָּף</a>, <i>to ride on a saddled ass</i>. <span class=\"citation\">Nidd. 14ᵃ</span> הא דמֵיכַף וכ׳ Ar. (ed. <span dir=\"rtl\">דמַכַּף</span> = <span dir=\"rtl\">מְאַכַּף</span> Pa.) in the one case it means that he rides on a saddled ass. [מיכף <span class=\"citation\">Snh. 36ᵃ</span>, v. <a href=\"#\" data-headword=\"כּוּף\">כּוּף</a>.]</div>","alt":["אֲכַף"]},"1746":{"h":"אַכְפָּא","r":"A01746","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"אָכַף\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>load, weight</i>. <span class=\"citation\">B. Bath. 69ᵃ</span> <span dir=\"rtl\">אבני דא׳</span> stones to weight the sheaves down to protect them from the wind.</div><div class=\"sense\"><b>—2)</b> <i>a contrivance to carry loads</i>, as a <i>hand-barrow</i> or <i>hand-basket</i>. <span class=\"citation\">Sabb. 66ᵇ</span> <span dir=\"rtl\">חמרא דא׳</span>, v. <a href=\"#\" data-headword=\"*אָנְקִטְמִין\">אָנְקִטְמִין</a>. <span class=\"citation\">Bets. 30ᵃ</span> (var. <span dir=\"rtl\">אכיתפא</span> <i>on the shoulder</i>, v. Rabb. D. S. a. l.).</div>","alt":[]},"1747":{"h":"אִכְפָּה","r":"A01747","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִכְפַּת\">next w.</a></div>","alt":[]},"1748":{"h":"אִכְפַּת","r":"A01748","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אָכַף\">אכף</a>; cmp. b. h. <a href=\"#\" data-headword=\"אָכַף\">אֶכֶף</a>) <i>burden, care, solicitude</i>, followed by <span dir=\"rtl\">ל־</span> of the person concerned. <span class=\"citation\">Targ. I Chr. XXI, 13</span> <a href=\"#\" data-headword=\"אִכְפַּת\">אִיכַּפַת</a>.—<span class=\"citation\">Y. Sot. V, 20ᵇ</span> top <span dir=\"rtl\">וביתא מאי אכפה ליה</span> what concern is the Temple to him? <span class=\"citation\">Taan. 25ᵃ</span> <span dir=\"rtl\">מאי אי׳ לך</span> why should that trouble thee? <span class=\"citation\">B. Mets. 40ᵃ</span> <span dir=\"rtl\">וכי מאי א׳ וכ׳</span> what do the mice care whether &amp;c. <span class=\"citation\">Koh. R. to IV, 1</span> <span dir=\"rtl\">זה מה אי׳ ליה</span> what concern is it to this one (if the other sinned), i.e. why should he suffer for it?; a. fr. <span class=\"citation\">Pesik. R. s. 10</span>, beg. <span dir=\"rtl\">אי׳ להם</span> will people care for them (miss them)? <span class=\"citation\">Git. 62ᵃ</span> <span dir=\"rtl\">מכפת לא אכפת ליה</span> should he not care for it? Cmp. <span dir=\"rtl\">כפת</span>.</div>","alt":["אִיכְפַּת","(אִיכַּפַת)"]},"1749":{"h":"אִכָּר","r":"A01749","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*אִכְרוּם\">אִי׳</a></div>","alt":["אִכָּרָא"]},"1750":{"h":"אֲכַרְגָּא","r":"A01750","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כַּרְגָּא\">כַּרְגָּא</a></div>","alt":[]},"1751":{"h":"אַכְרוּב","r":"A01751","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (= <a href=\"#\" data-headword=\"כְּרוּב I\">כְּרוּב</a> q. v.) <i>cabbage</i>. <span class=\"citation\">Y. Sabb. III, 5ᵈ</span> top. <span class=\"citation\">Num. R. s. 7</span>.—<span class=\"citation\">Y. Bets. V, 63ᵃ</span> <span dir=\"rtl\">קולסי א׳</span> cabbage heads.</div>","alt":[]},"1752":{"h":"*אִכְרוּם","r":"A01752","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">כרם</span> = <span dir=\"rtl\">קרם</span>; √<a href=\"#\" data-headword=\"כַּר\">כר</a>) <i>covering, coating</i>. <span dir=\"rtl\">א׳ אוכמין כקדרא</span> a coating of blackness like a pot. <span class=\"citation\">Targ. Jer. VIII, 21</span> (h. text <a href=\"#\" data-headword=\"קָדַר I\">קדר</a>). <span class=\"citation\">Targ. Joel II, 6</span>; <span class=\"citation\">Nah. II, 11</span> (h. text <a href=\"#\" data-headword=\"*פָּארוּר\">פארור</a>). Cmp. <a href=\"#\" data-headword=\"קְרוּם\">קְרוּם</a>.</div>","alt":["אִי׳","אִכְּרוּם","אֶכְּ׳"]},"1753":{"h":"*אכרוע","r":"A01753","html":"<div class=\"sense\"> <span class=\"citation\">Y. Maasr. I, 48ᵈ</span> top, read <a href=\"#\" data-headword=\"אַכְרוּב\">אַכְרוּב</a>; cmp. <a href=\"#\" data-headword=\"קֶלַח\">קֶלַח</a>.</div>","alt":[]},"1754":{"h":"אַכְרָזָה","r":"A01754","html":"<div class=\"sense\"> f. h. = ch. <a href=\"#\" data-headword=\"אַכְרַזְתָּא\">אַכְרַזְתָּא</a>. <span class=\"citation\">Y. Meg. IV, 75ᵇ</span> top, expl. <span dir=\"rtl\">אגרת בקורת</span>, v. <a href=\"#\" data-headword=\"אִגֶּרֶת\">אִגֶּרֶת</a>; <span class=\"citation\">Y. Keth. XI, 34ᶜ</span>; <span class=\"citation\">Y. Snh. I, 19ᵇ</span> top.</div>","alt":[]},"1755":{"h":"אַכְרְזִיאֵל","r":"A01755","html":"<p class=\"morphology\">pr. n.</p><div class=\"sense\"> [<i>the herald of God</i>], <i>Akhr’ziel</i>, an angel. <span class=\"citation\">Yalk. Deut. 940</span>. <span class=\"citation\">Deut. R. s. 11</span> <span dir=\"rtl\">אכזרי׳</span> (corr. acc.)</div>","alt":[]},"1756":{"h":"אַכְרַזְתָּא","r":"A01756","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (= h. <a href=\"#\" data-headword=\"הַכְרָזָה\">הַכְרָזָה</a>; <span dir=\"rtl\">כרּז</span>) <i>proclamation announcing public sale</i>, whence, <i>auction</i>, cmp. <a href=\"#\" data-headword=\"אִגֶּרֶת\">אִגֶּרֶת</a>.—<span class=\"citation\">B. Mets. 35ᵇ</span> <span dir=\"rtl\">ימי א׳</span> time appointed for public sale. <span class=\"citation\">Keth. 100ᵇ</span> <span dir=\"rtl\">נכסי דא׳</span> property sold at auction. Ib. for capitation-tax &amp;c. we sell <span dir=\"rtl\">בלא א׳</span> without previous announcement; a. fr.</div>","alt":[]},"1757":{"h":"אכרמוניא","r":"A01757","html":"<div class=\"sense\"> <span class=\"citation\">Midr. Till. to Ps. XIX, 5</span>, <span class=\"citation\">Yalk. ib.</span> <a href=\"#\" data-headword=\"בְּרִטַנְיָא\">ברטניא</a> pr. n., prob. a corrupt. of <span dir=\"rtl\">איי בריטניא</span> <i>Britannic Isles</i></div>","alt":[]},"1758":{"h":"אַכְרַעְתָּא","r":"A01758","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">כרע</span>) prop. <i>balancing</i>, hence <i>balances, scales, weighing</i>. Pesik. B’shall. p. 82ᵃ <span dir=\"rtl\">בא׳ דאכרעון וכ׳</span> in the way they weighed, they were weighed. [Cmp. Buber l. c. note 43.]</div>","alt":[]},"1759":{"h":"אַכְשָׁרוּתָא","r":"A01759","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כְּשַׁר\">כְּשַׁר</a>) <i>propriety, proper use</i>. <span class=\"citation\">Targ. Koh. X, 10</span>.</div>","alt":[]},"1760":{"h":"אַכַּתִּי","r":"A01760","html":"<div class=\"sense\"> (contr. of <span dir=\"rtl\">אַד כְּעַנְתָא הִי</span>) a scholastic term in Talm. Bab., <i>still, even now, yet</i>. <span class=\"citation\">Meg. 2ᵃ</span> <span dir=\"rtl\">וא׳ מבעי ליה וכ׳</span> and still the plural form is needed. <span class=\"citation\">Yoma 27ᵃ</span>; a. fr.—מִדְּאַכַּתִּי <i>since</i>, up to that time. <span class=\"citation\">R. Hash. 10ᵇ</span></div>","alt":[]},"1761":{"h":"*אַכְתָּנָא","r":"A01761","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">אכת</span>, v. P. Sm. 191; cmp. <a href=\"#\" data-headword=\"*אַכְסָא\">אכסא</a>, <a href=\"#\" data-headword=\"עֶכֶס\">עכס</a>, <a href=\"#\" data-headword=\"עַכְסָה\">עכסה</a>, <span dir=\"rtl\">עכן</span>) <i>venomous, vindictive</i>. <span class=\"citation\">Targ. Prov. XII, 28</span> Ms. Luzz. (v. Pesh., a. LXX b. c.); [some ed. <span dir=\"rtl\">אבהתנא</span>, v. <a href=\"#\" data-headword=\"בְּהַת\">בְּהֵת</a>; <span dir=\"rtl\">עַוְתָנָא</span>; h. text <span dir=\"rtl\">נתיבה אַל וכ׳</span>!]</div>","alt":[]},"1762":{"h":"*אַכְתַּר","r":"A01762","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"*אַכְתָּנָא\">preced.</a>; <a href=\"#\" data-headword=\"ר\">ר</a> format., cmp. <span dir=\"rtl\">סמוקר</span>) <i>greenish, blighted</i>. Y. Dem. II, beg. 22ᵇ is there no rice in Hulta? <span dir=\"rtl\">א׳ הוא</span> it is greenish.</div>","alt":[]},"1763":{"h":"*אַכְתְּרִיאֵל","r":"A01763","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">כתר</span>) [divine crown], pr. n. <i>Akhtriel</i>, a divine surname (attribute). <span class=\"citation\">Ber. 7ᵃ</span></div>","alt":[]},"1764":{"h":"א\"ל","r":"A01764","html":"<div class=\"sense\"><i>Albam</i>, a formula of permutation of letters wherein the first interchanges with the twelfth, the second with the thirteenth, &amp;c. <span class=\"citation\">Num. R. s. 18</span> טבאל באלב&quot;ם רמלא <i>Tabel</i> in <i>Albam</i> reads <i>Ramla</i>. <span class=\"citation\">Sabb. 104ᵃ</span></div>","alt":["אלב\"ם"]},"1765":{"h":"אַל־","r":"A01765","html":"<div class=\"sense\"> a prefix, = <a href=\"#\" data-headword=\"עַל\">עַל</a>; e.g. <a href=\"#\" data-headword=\"אַלְתּוּסְבְּרָאוֹת\">אַלְתּוּסְבְּרָאוֹת</a> (= <span dir=\"rtl\">על האוצרות</span>) <i>appointed over treasures</i>, v. <a href=\"#\" data-headword=\"אַ־\">אַ־</a>.</div>","alt":[]},"1766":{"h":"אַל","r":"A01766","html":"<div class=\"sense\"> (b. h.) <i>not, no</i> (according to Talmud a milder form of prohibition than <a href=\"#\" data-headword=\"לֹא\">לֹא</a>; v. <span class=\"citation\">Y. Pes. VI, 33ᵇ</span>). <span class=\"citation\">Aboth I, 3</span>.—<span dir=\"rtl\">אל תקרי</span> (abbr. <a href=\"#\" data-headword=\"א\">א&quot;ת</a>), v. <a href=\"#\" data-headword=\"אֶלָּא\">אֶלָּא</a>. <span class=\"citation\">Taan. 11ᵃ</span> <span dir=\"rtl\">א׳ יראה וכ׳</span> shall not live to see &amp;c.; a. v. fr.</div>","alt":[]},"1767":{"h":"אֶל","r":"A01767","html":"<div class=\"sense\"> אול <i>to turn</i>) prep. <i>to, toward.</i> <i>—</i> Pl., with prefix <a href=\"#\" data-headword=\"מ\">מ</a> a. suffix of pers. pron., <i>of itself, of my</i> (<i>his &amp;c.</i>) <i>own accord, on my</i> (<i>his &amp;c.</i>) <i>authority</i>. <span class=\"citation\">Yoma 5ᵇ</span> <span dir=\"rtl\">לא מֵאֵלַי</span> not on my own authority. Orlah I, 2 <span dir=\"rtl\">העולה מֵאֵלָיו</span> growing spontaneously.—<span class=\"citation\">Y. Peah VII, 20ᵇ</span> bot. its sacred character <span dir=\"rtl\">מֵאֵלָיו למדו</span> they did derive from itself (i.e. from the wording of the law itself).—Hence <span dir=\"rtl\">מִמֵּילָא</span>, v. <a href=\"#\" data-headword=\"מֵילָא I\">מֵילָא</a>.</div>","alt":[]},"1768":{"h":"אֵל","r":"A01768","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> v. <span dir=\"rtl\">אלל</span>) <i>God</i>. <span class=\"citation\">Shebu. 35ᵃ</span> divine names which dare not be erased are <i>El</i> &amp;c. <span class=\"citation\">Taan. 6ᵇ</span> bot.; a. fr.</div>","alt":[]},"1769":{"h":"אֵלָא","r":"A01769","html":"<div class=\"sense\"><i>buttress</i>, v. <a href=\"#\" data-headword=\"אֵילָא\">אֵילָא</a>.</div>","alt":[]},"1770":{"h":"אֲלָא I","r":"A01770","html":"<div class=\"sense\"><i>to lament</i>, v. <a href=\"#\" data-headword=\"אלי I\">אלי</a>.</div>","alt":[]},"1771":{"h":"אֲלָא II","r":"A01771","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>club, bat.</i> <span class=\"citation\">Targ. Cant. VIII, 5</span>; v. <a href=\"#\" data-headword=\"אַלָּתָא\">אַלָּתָא</a>.</div>","alt":[]},"1772":{"h":"אֶלָּא","r":"A01772","html":"<div class=\"sense\"> (contr. of <span dir=\"rtl\">אִן לָא</span> = <span dir=\"rtl\">אִם לֹא</span>) </div><div class=\"sense\"><b>1)</b> <i>if not, except, but, only</i>. <span class=\"citation\">Targ. O. Ex. XV, 11</span> <span dir=\"rtl\">לית אִ׳ את</span> none but thou, none besides thee; a. e.—<span class=\"citation\">Ber. V, 1</span> <span dir=\"rtl\">אין עומדין … א׳ וכ׳</span> one must stand up for prayer in no other disposition but that of humility.—<span class=\"citation\">Snh. 4ᵃ</span> <span dir=\"rtl\">לא נתן א׳ שלשה</span> he did only three times. <span class=\"citation\">Ber. I, 1</span> <span dir=\"rtl\"><span dir=\"rtl\">ולא זו בלבד</span> (<span dir=\"rtl\">אמרו</span>) <span dir=\"rtl\">א׳ וכ׳</span></span> and not only in this case they said so, but wherever &amp;c. <span class=\"citation\">Ib. 5ᵃ</span> <span dir=\"rtl\">אל תקרי תְלַמְּדֶנּוּ א׳ תְלַמְּדֵנוּ</span> read not <i>th’lamm’dennu</i> (thou instructest him) but <i>th’lamm’dēnu</i> (thou teachest us); a. v. fr.</div><div class=\"sense\"><b>—2)</b>  (ellipt.) (you cannot say anything except …) <i>but</i>, a logical inference excluding all other explanations &amp;c. Ib. 30ᵇ <span dir=\"rtl\">א׳ לא שנא</span> but (the conclusion is proven) there is no difference. Ib. <span dir=\"rtl\">א׳ אמר ר׳</span> but, said R. … we may derive it &amp;c.; a. fr.</div>","alt":["(אִלָּא)"]},"1773":{"h":"אלאופטרא","r":"A01773","html":"<div class=\"sense\">, read <span dir=\"rtl\">קְלִאוֹ׳</span>, v. <span dir=\"rtl\">קלפטרא</span></div>","alt":[]},"1774":{"h":"אַלְבִּינָא","r":"A01774","html":"<div class=\"sense\"> (אלב <i>to cut;</i> cmp. <span dir=\"rtl\">חלף</span>, <a href=\"#\" data-headword=\"חֵילֶף\">חֵילֶף</a>, <a href=\"#\" data-headword=\"חִילְפָא I\">חִילְפָא</a> &amp;c.) <i>a bundle of shoots, broom</i>. <span class=\"citation\">Y. Meg. II, 73ᵃ</span> (for b. h. <a href=\"#\" data-headword=\"מַטְאֲטֵא\">מְטַאְטֵא</a>).</div>","alt":["אַלְבִּינָה"]},"1775":{"h":"אִלְבָּנָא","r":"A01775","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"אַלְבִּינָא\">preced.</a>) <i>young shoot of the palm-tree, thin pointed branch.</i> Pl. <span dir=\"rtl\">אִלְבָּנִין</span>, <span dir=\"rtl\">אִלְבָּנַיָּיא</span>. <span class=\"citation\">Cant. R. to VII, 9</span> the palm … has no less <span dir=\"rtl\">מן תלת אילנין אלבנין</span> (strike out <span dir=\"rtl\">אילנין</span>) than three new (cutting) shoots. Ib. in our place they call <span dir=\"rtl\">לאלבנייא סנסנייה</span> the young shoots <i>sans’naya</i> (h. <span dir=\"rtl\">סנסנים</span>). [<span class=\"citation\">Num. R. s. 3</span>, beg., in Hebr. diction, <a href=\"#\" data-headword=\"אִנְבֹּונִין\">אִנְבּוֹנִין</a>, fr. <span dir=\"rtl\">אנב</span>, cmp. <a href=\"#\" data-headword=\"אֵב\">אֵב</a>; prob. to be read <span dir=\"rtl\">אִלְבּוֹנִין</span>.]</div>","alt":[]},"1776":{"h":"אֶלְגָּבִישׁ","r":"A01776","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <span class=\"citation\">Job XXVIII, 18</span>, a. Targ. a. l.) <i>hail, hailstone</i> (crystal). <span class=\"citation\">Ber. 54ᵇ</span> (playful etymol. <span dir=\"rtl\">על גב איש</span>).</div>","alt":[]},"1777":{"h":"אַלְגּוּמַּיָּא","r":"A01777","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (= b. h. <span dir=\"rtl\">אַלְגּוּמִּים</span>) name of <i>a tree</i>. Targ. II. Chr. II, 7 (8). [Ib. IX, 10; 11 <span dir=\"rtl\">אלמוגייא</span>, reading the h. text as in <span class=\"citation\">I Kings X, 11</span>.] V. <a href=\"#\" data-headword=\"אַלְמוּג\">אַלְמוּג</a>.</div>","alt":[]},"1778":{"h":"אלגוסין","r":"A01778","html":"<div class=\"sense\"> <span class=\"citation\">Tosef. Maasr. III, 14</span> Var. ed. Zuck., v. <a href=\"#\" data-headword=\"גָּרִיס\">גָּרִיס</a></div>","alt":[]},"1779":{"h":"אלדי","r":"A01779","html":"<div class=\"sense\"> = <a href=\"#\" data-headword=\"לְהִי\">אלהי</a>, <a href=\"#\" data-headword=\"אֱלֹהִים\">אלהים</a>, v. <a href=\"#\" data-headword=\"אֱלוֹהַּ\">אֱלוֹהַּ</a></div>","alt":["אלדים"]},"1780":{"h":"אָלָה","r":"A01780","html":"<div class=\"sense\"><i>to curse</i>, v. <a href=\"#\" data-headword=\"אלי I\">אלי</a>.</div>","alt":[]},"1781":{"h":"אָלָה ²","r":"A01781","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>imprecation, curse</i>. <span class=\"citation\">Sot. II, 5</span> (<span class=\"citation\">17ᵃ</span>); a. fr.—Pl. <a href=\"#\" data-headword=\"אלות\">אָלוֹת</a>. Ib. a. e.</div>","alt":[]},"1782":{"h":"אֵלֶּה","r":"A01782","html":"<div class=\"sense\"> c. pl. (b. h.; v. <a href=\"#\" data-headword=\"אָלָה ²\">preced.</a>) <i>these, those</i> (cmp. <a href=\"#\" data-headword=\"הֲרֵי I\">הרי</a>). <span class=\"citation\">Ex. R. s. 30</span> <i>v’elleh</i> (and this) adds to the preceding (continues), <i>elleh</i> (these) restricts. V. <a href=\"#\" data-headword=\"אֵלּוּ\">אֵלּוּ</a>.</div>","alt":[]},"1783":{"h":"אֵלָה","r":"A01783","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> v. <a href=\"#\" data-headword=\"אֵלֶּה\">preced. ws.</a>) <i>terebinth.</i> <span class=\"citation\">Shebi. VII, 5</span>.</div>","alt":[]},"1784":{"h":"אלה","r":"A01784","html":"<div class=\"sense\"> <span class=\"citation\">Sabb. 90ᵃ</span> Ar., v. <a href=\"#\" data-headword=\"אֵילָא\">אֵילָא</a> 3.</div>","alt":[]},"1785":{"h":"אַלָּה","r":"A01785","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <span class=\"citation\">Josh. XXIV, 26</span>; v. <a href=\"#\" data-headword=\"אַלָּתָא\">אַלָּתָא</a>) [pointed, prominent] </div><div class=\"sense\"><b>1)</b> <i>lance, fork.</i> <span class=\"citation\">Kel. XVI, 8</span> <span dir=\"rtl\">חפוי הא׳</span>, v. <a href=\"#\" data-headword=\"חִפּוּי\">חִפּוּי</a>. <span class=\"citation\">Pes. 57ᵃ</span> <span dir=\"rtl\">אוי לי מֵאַלָּתָן</span> woe to me (I am afraid) of their fork (weapon). <span class=\"citation\">Sabb. VI, 3</span> (<span class=\"citation\">63ᵃ</span>) ed. (Ms. <a href=\"#\" data-headword=\"אֲלָא I\">אלא</a>); Y. ibid. 8ᵇ (expl. <span dir=\"rtl\">דייקרן</span>).</div><div class=\"sense\"><b>—2)</b> <i>sign-pole</i>, used in the barn as a mark. Ib.; <span class=\"citation\">Y. Maasr. I, 49ᵃ</span> bot.; <span class=\"citation\">Tosef. Ter. III, 11</span> <span dir=\"rtl\">משתיעקר הא׳</span> (ed. Zuck. <span dir=\"rtl\">משיתעשר</span>, corr. acc.) as soon as the sign-pole (fork) is removed (indicating that the grain is ready for use and priestly gifts).</div>","alt":[]},"1786":{"h":"אֱלָהּ","r":"A01786","html":"<p class=\"morphology\">m.</p><div class=\"sense\">(= h. <a href=\"#\" data-headword=\"אֱלוֹהַּ\">אֱלוֹהַּ</a>) <i>God.</i> <span class=\"citation\">Dan. III, 28</span>; a. fr.—<span class=\"citation\">Targ. O. Deut. XXXIII, 26</span>; a. fr.—<span class=\"citation\">Lev. R. s. 5</span>, end <span dir=\"rtl\">את אלה רב</span> Ar. (ed. <span dir=\"rtl\">אלוה</span>). <span class=\"citation\">Y. B. Mets. II, 8ᶜ</span> <span dir=\"rtl\">אלההון דיהודאי</span> the God of the Jews. <span class=\"citation\">Y. Snh. X, 28ᵇ</span>.—<i>Pl.</i> (also plur. majest.) <a href=\"#\" data-headword=\"אִלָּהֵין\">אֱלָהִין</a>. <span class=\"citation\">Dan. II, 11</span>; a. e.—<span dir=\"rtl\">אֱלָהַיָּא</span>. <span class=\"citation\">Jer. X, 11</span>. <span class=\"citation\">Targ. Ps. CXXXVI, 2</span> <span dir=\"rtl\">אלהי אלהיא</span> the God of gods. [<span class=\"citation\">Gen. R. s. 26</span> <span dir=\"rtl\">כומריא גנבו א׳ וכ׳</span> (read <span dir=\"rtl\">אלהון</span>) when priests rob—who would swear by their god?] <span class=\"citation\">Ib.</span> (ref. to <span class=\"citation\">Gen. VI, 2</span>).—<span class=\"citation\">Lev. R. s. 33</span> <span dir=\"rtl\">תמן קריין … אֱלָהַיָּיא</span> there (in Rome) they call their kings <i>gods.</i></div>","alt":["אֱלָהָא","אֵילַהּ"]},"1787":{"h":"אֱלָהוּת","r":"A01787","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"אֱלָהּ\">preced.</a>) <i>Deity, divinity</i>. <span class=\"citation\">Gen. R. s. 46</span> <span dir=\"rtl\">כדי לאלוהותו</span>—<span dir=\"rtl\">שאין העולם</span> the universe and what it contains, are but inadequate manifestations of his divinity; a. e. <span class=\"citation\">Gen. R. s. 66</span> <span dir=\"rtl\">ויתן לך אלוהותו</span> (some ed.) may he impart to thee his divine power; v. next w.—<a href=\"#\" data-headword=\"אֱלוֹהוֹת\">אֱלוֹהוֹת</a>, v. <a href=\"#\" data-headword=\"אֱלוֹהַּ\">אֱלוֹהַ</a>.</div>","alt":["אֱלוֹהוּת"]},"1788":{"h":"אֱלָהוּתָא","r":"A01788","html":"<div class=\"sense\"><span class=\"citation\">Targ. Cant. VIII, 1</span>; a. e. <span class=\"citation\">Gen. R. s. 66</span> Ar. (v. <a href=\"#\" data-headword=\"אֱלָהוּת\">preced.</a>).</div>","alt":[]},"1789":{"h":"אֱלֹהִים","r":"A01789","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֱלוֹהַּ\">אֱלוֹהַּ</a></div>","alt":[]},"1790":{"h":"אִלָּהֵין","r":"A01790","html":"<div class=\"sense\"> (= <span dir=\"rtl\">אלא הן</span>) <i>but that, unless, except, only</i>. <span class=\"citation\">Targ. Gen. XXXII, 27</span>; a. fr.—אף א׳ <i>even only</i>, i.e. <i>so much the more</i> (or <i>less</i>), <i>not to say</i>. <span class=\"citation\">Targ. I Kings VIII, 27</span>; <span class=\"citation\">II Kings V, 13</span>.  v. <a href=\"#\" data-headword=\"לָהֵן\">לָהֵן</a>; cmp. <a href=\"#\" data-headword=\"אֶלָּא\">אֶלָּא</a>.</div>","alt":["אִילָּהֵין"]},"1791":{"h":"אֵלּוּ","r":"A01791","html":"<div class=\"sense\"> c. pl. (b. h. , q. v.) </div><div class=\"sense\"><b>1)</b> <i>these, the following</i>. <span class=\"citation\">B. Mets. II, 1</span>; a. v. fr.—א׳ וא׳ <i>both</i>. <span class=\"citation\">Zeb. V, 2</span>; a. v. fr. *[</div><div class=\"sense\"><b>2)</b>  (interrog.) <i>which?</i> <span class=\"citation\">Pesik. R. s. 29</span> (—30, ed. Friedm. p. 138ᵇ) <span dir=\"rtl\">לאילו נאמין</span> in which of them shall we trust? Pesik. Naḥămu p. 127ᵇ sq.; <span class=\"citation\">Yalk. Is. 307</span> <span dir=\"rtl\">לאי זה</span>, <span dir=\"rtl\">לאיזו</span>.]</div>","alt":["אֵילּוּ"]},"1792":{"h":"אִלּוּ","r":"A01792","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִילּוּ\">אִילּוּ</a></div>","alt":[]},"1793":{"h":"אֲלוּ","r":"A01793","html":"<div class=\"sense\"> (= <a href=\"#\" data-headword=\"אֲרוּ\">אֲרוּ</a>, v. <a href=\"#\" data-headword=\"אָלָה\">אָלָה</a>) <i>behold.</i> <span class=\"citation\">Dan. II, 31</span>; a. e.</div>","alt":[]},"1794":{"h":"אַלְוָא","r":"A01794","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (ἀλόη, prob. of Semit. orig.) <i>the impissated juice of aloes</i>, used as a purgative. <span class=\"citation\">Git. 69ᵇ</span> Ar. (ed. <a href=\"#\" data-headword=\"אילווא\">אילווא</a>).</div>","alt":[]},"1795":{"h":"אָלוּאוֹן","r":"A01795","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*אַקְסִילָאלִיאָיָין\">אקסילאליאיין</a></div>","alt":[]},"1796":{"h":"אַלְוַאי","r":"A01796","html":"<div class=\"sense\"><i>oh that!</i> <span class=\"citation\">Targ. Y. II, Num. XXIII, 10</span>; a. e. <span class=\"citation\">Targ. Ex. XVI, 3</span>, a. fr. <a href=\"#\" data-headword=\"לוי\">(לוי</a>).—<span class=\"citation\">Targ. Y. ib. XXXII, 30</span> (h. text <span dir=\"rtl\">אולי</span>)—<span class=\"citation\">Num. R. s. 2</span>. <span class=\"citation\">Gen. R. s. 9</span>; a. fr. *[<span class=\"citation\">Targ. Y. II, Num. XXIV, 23</span> <a href=\"#\" data-headword=\"אַלְוַאי\">אַלְוַוי</a>, Y. I <a href=\"#\" data-headword=\"וַי\">וַי</a>, <i>woe!</i>]</div>","alt":["אַלְוַוי","לְוַאי","הַלְוַאי","הַלְוַו׳"]},"1797":{"h":"אַלְוָה","r":"A01797","html":"<p class=\"morphology\">m.</p><div class=\"sense\">, pl. <a href=\"#\" data-headword=\"אַלְוִוים\">אַלְוִים</a> (v. <a href=\"#\" data-headword=\"אַלְוָא\">אַלְוָא</a>) <i>aloe-wood</i>. <span class=\"citation\">Y. Keth. VII, end, 31ᵈ</span>; <span class=\"citation\">Gen. R. s. 15</span>, v. <a href=\"#\" data-headword=\"אַלְמוּג\">אַלְמוּג</a>. V. also <a href=\"#\" data-headword=\"אַלְוִוין\">אַלְוִוין</a>.</div>","alt":[]},"1798":{"h":"אֱלוֹהַּ","r":"A01798","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> v. <a href=\"#\" data-headword=\"אֵל\">אֵל</a>) <i>God.</i> <i> Pl. majest.</i> <a href=\"#\" data-headword=\"אֱלֹהִים\">אֱלֹהִים</a>, cmp. <a href=\"#\" data-headword=\"אֵל\">אֵל</a>.—<span dir=\"rtl\">האלהים</span> by God! <span class=\"citation\">Sabb. 145ᵃ</span>; a. fr. [<a href=\"#\" data-headword=\"ד\">ד</a> is freq. substituted for <a href=\"#\" data-headword=\"ה\">ה</a> as <a href=\"#\" data-headword=\"אלדי\">אלדים</a>, <a href=\"#\" data-headword=\"אלדי\">אלדי</a>, <span dir=\"rtl\">ידוד</span> esp. in Targ. Y. ed. Sab.] <a href=\"#\" data-headword=\"אלקים\">אלקים</a>, ch. <a href=\"#\" data-headword=\"אֱלָקָא\">אלקא</a>, adopted in order to avoid uttering the divine name. <span class=\"citation\">B. Kam. 106ᵃ</span>; cmp. <span dir=\"rtl\">אלעיקי</span>, <a href=\"#\" data-headword=\"*אֱיפוֹפֵי\">איפופי</a> &amp;c.—Pl. <a href=\"#\" data-headword=\"אֱלוֹהוֹת\">אֱלוֹהוֹת</a></div><div class=\"sense\"><b>1)</b> <i>deities, powers</i>. <span class=\"citation\">Y. Ber. IX, beg. 12ᵈ</span>. <span class=\"citation\">Lev. R. s. 4</span>.</div><div class=\"sense\"><b>—2)</b> <i>biblical verses containing the word El, Elohim</i> &amp;c. <span class=\"citation\">Y. R. Hash. IV, 59ᶜ</span>.</div>","alt":[]},"1799":{"h":"אֱלוֹהוּת","r":"A01799","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֱלָהוּת\">אֱלָהוּת</a></div>","alt":[]},"1800":{"h":"אֱלוֹהוֹת","r":"A01800","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֱלוֹהַּ\">אֱלוֹהַּ</a></div>","alt":[]},"1801":{"h":"אַלְוָוא","r":"A01801","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַלְוָא\">אַלְוָא</a>, <a href=\"#\" data-headword=\"אַלְוָה\"><a href=\"#\" data-headword=\"אַלְוָה\">אַלְוָה</a>.</a></div>","alt":["אַלְוָוה"]},"1802":{"h":"אַלְוַואי","r":"A01802","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַלְוַאי\">אַלְוַאי</a></div>","alt":[]},"1803":{"h":"אַלְוִוים","r":"A01803","html":"<div class=\"sense\"> (אלווס Ar.), v. <a href=\"#\" data-headword=\"אַלְוָה\">אַלְוָה</a></div>","alt":[]},"1804":{"h":"אַלְוִוין","r":"A01804","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"אַלְוָא\">אַלְוָא</a>) <i>the herbaceous plant aloe</i>, a kind of cress. <span class=\"citation\">Y. Shebi. IV, 35ᵇ</span> bot.; <span class=\"citation\">Tosef. ib. I</span>, end (ed. Zuck. <span dir=\"rtl\">עלוא׳</span>, oth. ed. <span dir=\"rtl\">עלויין</span>, <span dir=\"rtl\">עלווין</span>) <span dir=\"rtl\">ומקיימין את הא׳ וכ׳</span> you may (in the Sabbath year) let the aloe grow on the top of the roof, but you must not water it.</div>","alt":["(עַלְוִיִּים","עַלְוָאִין)"]},"1805":{"h":"אַלְוַוְיתָא","r":"A01805","html":"<p class=\"morphology\">f.</p><div class=\"sense\">(= h. <a href=\"#\" data-headword=\"לְוָיָה\">לְוָיָה</a>) <i>escort, reception on arriving and leaving</i>. <span class=\"citation\">Y. Maasr. II, 49ᵈ</span> other people <span dir=\"rtl\">דלית אלוויתיה שכיחא לון</span> (read … <a href=\"#\" data-headword=\"תָּא\">תא</a>) who do not frequently meet with a reception (an offer of refreshments &amp;c.). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">דַּלְוַויָיתֵיה וכ׳</span> (= <span dir=\"rtl\">דאל</span>) who may fairly expect a reception. Cmp. <a href=\"#\" data-headword=\"אִילַּוָּיוּתָא\">אִילַּוָּיוּתָא</a>.</div>","alt":["אַלְוַויְיתָא"]},"1806":{"h":"אלוונתית","r":"A01806","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֲלוּנְטִית II\"><span dir=\"rtl\">אֲלוּנְטִית</span> II</a></div>","alt":[]},"1807":{"h":"אלווס","r":"A01807","html":"<div class=\"sense\"> Ar. read <a href=\"#\" data-headword=\"אַלְוִוים\">אַלְוִוים</a>.</div>","alt":[]},"1808":{"h":"אַלְוָותָא","r":"A01808","html":"<div class=\"sense\"> <span class=\"citation\">B. Bath. 73ᵃ</span>, v. <a href=\"#\" data-headword=\"*אִלִּיתָא\">אִלִּיתָא</a> a. <a href=\"#\" data-headword=\"אַלָּתָא\"><a href=\"#\" data-headword=\"אַלָּתָא\">אַלָּתָא</a>.</a></div>","alt":[]},"1809":{"h":"אֱלוּל","r":"A01809","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (b. h.) <i>Elul</i>, the sixth month of the Hebrew calendar, containing twenty nine days, varying between the seventh of August and the second of October. <span class=\"citation\">R. Hash. I, 1</span>. <span class=\"citation\">Ib. 19ᵇ</span>; a. fr. <span class=\"citation\">Y. Shek. III, beg. 47ᵇ</span> bot. <span dir=\"rtl\">בני א׳</span> animals born in Elul. <span class=\"citation\">Targ. Y. Num. XIV, 37</span> <a href=\"#\" data-headword=\"אֵילוּל\">אילול</a>. Targ. II Esth. III, 7.</div>","alt":[]},"1810":{"h":"אלולוגין","r":"A01810","html":"<div class=\"sense\">, <span class=\"citation\">Tosef. Kel. B. Bath. VI, 9</span> read <a href=\"#\" data-headword=\"אַנְלוֹגִין\">אַנְלוֹגִין</a>.</div>","alt":["אלולננין"]},"1811":{"h":"אֱלוּלי","r":"A01811","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"אֱלוּל\">אֱלוּל</a>) <i>born in Elul.</i> Pl. <span dir=\"rtl\">אֱלוּלִיִּים</span>, <span dir=\"rtl\">אֱלוּלִיִּין</span>. <span class=\"citation\">Y. Shek. III, beg. 47ᵇ</span>; a. e.</div>","alt":[]},"1812":{"h":"אִלּוּלֵי","r":"A01812","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִלֵּימָא II\">אִילּ׳</a></div>","alt":["אִלּוּלֵיפוֹן","אִלּוּלָפוֹן"]},"1813":{"h":"אָלוּם","r":"A01813","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">אלם</span>; √<span dir=\"rtl\">אל</span>, cmp. <a href=\"#\" data-headword=\"חָלַם I\">חלם</a>, <span dir=\"rtl\">חלב</span> &amp;c.) <i>a mucilaginous plant</i> (cmp. Lat. Alum), prob. <i>Silphium</i>, a kind of <i>Laserpitium</i> or <i>Asafœtida</i>. <span class=\"citation\">T’bul Yom I, 5</span> (Var. in Ar. <span dir=\"rtl\">אילום</span>, <span dir=\"rtl\">הלום</span>). Cmp. <a href=\"#\" data-headword=\"אֱלָל\">אֱלָל</a>.</div>","alt":[]},"1814":{"h":"אֲלוּמָּא","r":"A01814","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> 2).—Pl. <span dir=\"rtl\">אֲלוּמַּיָּיא</span>. <span class=\"citation\">Targ. Ruth II, 7</span>; <span class=\"citation\">15</span>.</div>","alt":[]},"1815":{"h":"אֲלוּמָּה","r":"A01815","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b> <i>binding, making sheaves.</i> <span class=\"citation\">Peah VI, 9</span> (<span class=\"citation\">10</span>) <span dir=\"rtl\">נתנה … לא׳</span> grain stalks intended for binding sheaves <i>thereof</i> (but not for binding the latter into bundles of sheaves <a href=\"#\" data-headword=\"עֹמֶר\">עֹמֶר</a>, Maim.)—[For binding sheaves <i>therewith</i> R. S.].</div><div class=\"sense\"><b>—2)</b> <i>sheaf.</i> <span class=\"citation\">Ex. R. s. 31</span>.—Pl. <span dir=\"rtl\">אֲלוּמֹּות</span>. <span class=\"citation\">B. Mets. 22ᵇ</span> sq. <i>large sheaves</i>, opp. <span dir=\"rtl\">כריכות</span>.</div>","alt":[]},"1816":{"h":"אַלֹּון I","r":"A01816","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> v. <a href=\"#\" data-headword=\"אַלָּה\">אַלָּה</a>) <i>oak.</i> <i>—</i> Pl. <span dir=\"rtl\">אַלֹּונִים</span>. <span class=\"citation\">Gen. R. s. 15</span> <span dir=\"rtl\">א׳ בלוטין</span> the bibl. <i>allonim</i> means <i>b’lutin</i>, v. <a href=\"#\" data-headword=\"בָּלוּט\">בָּלוּט</a>. [<span class=\"citation\">Ib.</span> <span dir=\"rtl\">אלמוגים א׳</span> read <a href=\"#\" data-headword=\"אַלְוִוים\">אַלְוִים</a>, v. <a href=\"#\" data-headword=\"אַלְוָה\">אַלְוָה</a>, <a href=\"#\" data-headword=\"אַלְמוּג\">אַלְמוּג</a>]. <span class=\"citation\">R. Hash. 23ᵃ</span> <span dir=\"rtl\">א׳ בוטמי</span>, v. <a href=\"#\" data-headword=\"בּוּטְמָא\">בּוּטְמָא</a>; <span class=\"citation\">B. Bath. 80ᵇ</span> <span dir=\"rtl\">א׳ בוטני</span>, v. <a href=\"#\" data-headword=\"בּוּטְנָא I\">בּוּטְנָא</a>. [<span class=\"citation\">Gen. R. s. 60</span> (play on <i>hallazeh</i> <span class=\"citation\">Gen. XXIV, 6</span>) <span dir=\"rtl\">א׳ זה</span> he is an oak (of fine appearance); Rashi refers to next w.]</div>","alt":[]},"1817":{"h":"אַלֹּון II","r":"A01817","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (ἄλλος acc.) <i>another</i>. <span class=\"citation\">Gen. R. s. 81</span> in Greek <i>allon</i> means <a href=\"#\" data-headword=\"אַחֵר\">אַחֵר</a>; Pesik. Zakh. p. 24ᵃ <span dir=\"rtl\">א׳ תרי</span> (read <a href=\"#\" data-headword=\"אַחֵר\">אַחֵר</a>) another (one more).</div>","alt":[]},"1818":{"h":"אֲלוּנְטִית I","r":"A01818","html":"<div class=\"sense\"> (<a href=\"#\" data-headword=\"אֲלוּנְתִּית\">אֲלוּנְתִּית</a>) (interchanging with <a href=\"#\" data-headword=\"לוּנְטִית\">לוּנְטִית</a> q. v.) f. (<a href=\"#\" data-headword=\"לוּט\">לוּט</a>, <i>to cover, wrap</i>, cmp. <span class=\"citation\">I Sam. XX, 10</span>, a. <span dir=\"rtl\">לאט</span> in H. Dict.; <a href=\"#\" data-headword=\"נ\">נ</a> inserted) <i>wrapping cloth, sheet, bathing clothes</i>. <span class=\"citation\">Sabb. 40ᵇ</span> <span dir=\"rtl\">מיחם אדם אלונט׳</span> (Ms. M. <span dir=\"rtl\">אלונת׳</span>, <span class=\"citation\">Tosef. ib. III</span> (<span class=\"citation\">IV), 7</span> <span dir=\"rtl\">אלונתת</span>) one may warm a sheet on the Sabbath to put it on the stomach; <span class=\"citation\">Y. Sabb. XIX, 17ᵃ</span> bot. [<span class=\"citation\">Gen. R. s. 80</span> to put on a wound, prob. next w.]—<span class=\"citation\">Sabb. 147ᵇ</span> (Ms. M. always <span dir=\"rtl\">אלונת׳</span>, Ar. <span dir=\"rtl\">לונט׳</span>). <span class=\"citation\">Men. 72ᵃ</span>.—<span class=\"citation\">Y. Erub. VIII, 25ᵇ</span> top.—Pl. <span dir=\"rtl\">אֲלוּנְטִיאוֹת</span> <span class=\"citation\">Sabb. XXII, 5</span> (<span class=\"citation\">147ᵃ</span>). <span class=\"citation\">Sabb. 147ᵇ</span> <span dir=\"rtl\">בעשר אלונטית</span> (read <span dir=\"rtl\">טִיאוֹת …</span>, or … <span dir=\"rtl\">טִיֹּות</span>). <span class=\"citation\">Tosef. ib. XVI</span> (<span class=\"citation\">XVII), 15</span> <span dir=\"rtl\">אֲלוּנְטָאוֹת</span> (Var. <a href=\"#\" data-headword=\"אלנטיאות\">אֲלֻנְטִיאוֹת</a>, <span dir=\"rtl\">לֻנְטִיאוֹת</span>). <span class=\"citation\">Ib. 17</span> <span dir=\"rtl\">אנלונטאות</span> (Var. <a href=\"#\" data-headword=\"אלנטיאות\">אלנטיאות</a>).</div>","alt":[]},"1819":{"h":"אֲלוּנְטִית II","r":"A01819","html":"<div class=\"sense\"> corr. <a href=\"#\" data-headword=\"אֲלוּנְתִּית\">אֲלוּנְתִּית</a> (<a href=\"#\" data-headword=\"אֲלוּנְתִּית\">אֲלַנְתִּית</a>) f., <a href=\"#\" data-headword=\"אֲלִינְתִּין\">אֲלִינְתִּין</a> m. (a corrupt. of οἰνάνθη, οἰνάνθινος, œnanthe, œnanthinus; cmp. <a href=\"#\" data-headword=\"אניגרון\">אניגרון</a> as to <a href=\"#\" data-headword=\"נ\">נ</a> a. <a href=\"#\" data-headword=\"ל\">ל</a>) made of the grape (or <i>leaves</i>) of wild vine (œnanthe), whence </div><div class=\"sense\"><b>1)</b> <i>an aromatic water</i>. Y. Ber. VI, 10ᵈ he who sprinkles <span dir=\"rtl\">אלינת׳</span> œnanthe.</div><div class=\"sense\"><b>—2)</b> <i>an unguent</i>. Y. ib. I, 3ᵃ top <span dir=\"rtl\">סכין אלוונ׳ וכ׳</span> (corr. acc.) you may oint a sick person with œn. on the Sabbath. Y. Sabb. XIV, 14ᶜ bot. <a href=\"#\" data-headword=\"אֲלִינְתִּין\">אלינתין</a>. <span class=\"citation\">Y. Shebi. VII, beg. 37ᵇ</span> <span dir=\"rtl\">יצאת א׳ … לתְּפֵילִין</span> (read … <span dir=\"rtl\">תית</span>) except œn. which is only for children (after circumcision).</div><div class=\"sense\"><b>—3)</b> <i>a wine</i> (vinum œnanthinum), used esp. after bathing. <span class=\"citation\">Ab. Zar. 30ᵃ</span> (expl. as a mixture of old wine, pure water and balsam); <span class=\"citation\">Sabb. 140ᵃ</span> <span dir=\"rtl\">אלונט׳</span> ed. (Ms. M. <span dir=\"rtl\">אלונת׳</span>). <span class=\"citation\">Ḥull. 6ᵃ</span> wine to be put <span dir=\"rtl\">לתוך הא׳</span> into a mixture called <i>ăluntith</i>; <span class=\"citation\">Tosef. Dem. I, 24</span>. Y. Bets. I, 60ᵈ top.</div>","alt":[]},"1820":{"h":"אלוניסתין","r":"A01820","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֲלִנִסְטִי\">אֲלִנִסְטִי</a></div>","alt":[]},"1821":{"h":"אֲלוּנְכָא","r":"A01821","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (= <a href=\"#\" data-headword=\"לוֹנְכָא\">לוּנְכָא</a> q. v.) <i>spear-head, javelin.</i> Pl. <a href=\"#\" data-headword=\"*אֲלַנְקֵי\">אֲלוּנְכֵי</a>. <span class=\"citation\">Git. 70ᵃ</span> <span dir=\"rtl\">בא׳ דפרסאי</span> (Ar. <span dir=\"rtl\">בלונכי</span>) with Persian (poisoned) javelins.</div>","alt":[]},"1822":{"h":"אַלּוּנְקֵי","r":"A01822","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*אֲלַנְקֵי\">אַלַּנְקֵי</a></div>","alt":[]},"1823":{"h":"אֲלוּנְתִּית","r":"A01823","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֲלוּנְטִית I\">אֲלוּנְטִית</a></div>","alt":[]},"1824":{"h":"אלוסטרוס","r":"A01824","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַלַּס\">אַלַּס</a></div>","alt":[]},"1825":{"h":"אַלּוּף","r":"A01825","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>prince, chief.</i> <span class=\"citation\">Gen. R. s. 20</span> beg. <span dir=\"rtl\">אלופוֹ של עולם</span> the world’s chief (<i>Aleph</i>, i.e. Adam).</div>","alt":[]},"1826":{"h":"אָלוּשׁ","r":"A01826","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"> (b. h.) <i>Alush</i>, one of the stations of the Israelites on their journey to Kanaan. <span class=\"citation\">Yoma 10ᵃ</span>. <span class=\"citation\">Gen. R. s. 48</span> (play on <i>lushi</i>, <span class=\"citation\">Gen. XVIII, 6</span>). Y. Bets. II, beg. 61ᵃ</div>","alt":[]},"1827":{"h":"אלות","r":"A01827","html":"<div class=\"sense\"> <span class=\"citation\">Pesik. R. s. 22</span> <span dir=\"rtl\">כ&quot;ד א׳</span>, read <a href=\"#\" data-headword=\"בּוּלָאוֹת\">בּוּלָאוֹת</a>, v. <a href=\"#\" data-headword=\"*בּוּלִי I\">בּוּלִי</a></div>","alt":[]},"1828":{"h":"אַלְוָתָא","r":"A01828","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"אַלְוָא\">אַלְוָא</a>) <i>a piece of aloe-wood</i>. <span class=\"citation\">Bets. 33ᵇ</span>; v. <a href=\"#\" data-headword=\"אַלָּתָא\">אַלָּתָא</a>.</div>","alt":[]},"1829":{"h":"אַלּוּתָא","r":"A01829","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*אִלִּיתָא\">אִלִּיתָא</a> a. <a href=\"#\" data-headword=\"אַלָּתָא\"><a href=\"#\" data-headword=\"אַלָּתָא\">אַלָּתָא</a>.</a></div>","alt":[]},"1830":{"h":"*אלטיכסייא","r":"A01830","html":"<div class=\"sense\">, <span class=\"citation\">Gen. R. s. 8</span> א׳ שלך Ar., ed. <span dir=\"rtl\">תכסיס א׳ שלך …</span>, <span class=\"citation\">Yalk. Ps. 834</span> <span dir=\"rtl\">תכסיס אלתמסין</span>, prob. <span dir=\"rtl\">אַלְטַכְסִיסִין</span> (v. <a href=\"#\" data-headword=\"אַל־\">אַל־</a> a. <a href=\"#\" data-headword=\"טַכְסִיס\"><a href=\"#\" data-headword=\"טַכְסִיס\">טַכְסִיס</a>)</a><i>chief of the court-ceremonies</i> (i.e. the angel of Truth); Rashi: <i>seal</i> (?).</div>","alt":["אלטיכסייה"]},"1831":{"h":"אֱלָטִין","r":"A01831","html":"<div class=\"sense\"> (ἐλάτη) <i>fir-trees</i>. Tanḥ. T’rum. 9 ברוש א׳ Bibl. <i>b’rosh</i> means <i>firs</i></div>","alt":[]},"1832":{"h":"*אלטינון","r":"A01832","html":"<div class=\"sense\">, a corruption of <span dir=\"rtl\">יַאנְטִינוֹן</span> for <span dir=\"rtl\">יַאנְתִּינוֹן</span> m. (ἰάνθινον, Aquila <span class=\"citation\">Ex. XXV, 5</span>) <i>violet-colored</i>. <span class=\"citation\">Koh. R. to I, 9</span> <span dir=\"rtl\">אלט׳</span>; <span class=\"citation\">Y. Sabb. II, 4ᵈ</span> (expl. bibl. <a href=\"#\" data-headword=\"תַּחַשׁ\">תחש</a> as a color <span dir=\"rtl\">לשם צבעו</span>, v. Ges. H. Dict. s. v. <a href=\"#\" data-headword=\"תַּחַשׁ\">תַּחַשׁ</a>). [<span class=\"citation\">Esth. R. to I, 6</span> <a href=\"#\" data-headword=\"טיינון\">טיינון</a> (Var. <span dir=\"rtl\">סיינון</span>) read <a href=\"#\" data-headword=\"יָקִינְטִין\">יקינטינון</a>].</div>","alt":["טיינון"]},"1833":{"h":"אלי I","r":"A01833","html":"<div class=\"sense\"><i>to curse</i>. <span class=\"citation\">Sifré Num. 18</span> (ref. to <span class=\"citation\">Num. XVIII, 21</span>) <span dir=\"rtl\">לאלה שיהו אָלִין בה וכ׳</span> ‘as a curse’ means that people shall curse by her (pointing to her), ‘may happen unto thee what happened to …’.</div>","alt":["אָלָה"]},"1834":{"h":"אלי II","r":"A01834","html":"<div class=\"sense\"> (= <a href=\"#\" data-headword=\"יְלֵל\">ילל</a>, v. <a href=\"#\" data-headword=\"אִילְיָא\">אִילְיָא</a>) <i>to lament, wail</i>. <span class=\"citation\">Targ. II Sam. I, 17</span>; a. e.</div><div class=\"sense\"><b>Pa. אַלָּא</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"אלי I\">same</a>. <span class=\"citation\">Targ. Jud. XI, 40</span> <span dir=\"rtl\">לאַלָּאָה</span> (some ed. <span dir=\"rtl\">לאֲלָאָה</span>).</div></div>","alt":["אֲלָא"]},"1835":{"h":"אֱלִי","r":"A01835","html":"<div class=\"sense\"><i>mourning</i>, v. <a href=\"#\" data-headword=\"*אַלְיָתָא\">אַלְיָתָא</a> and <a href=\"#\" data-headword=\"אַלִּיתָא\">אַלִּיתָא</a>.</div>","alt":[]},"1836":{"h":"אֶלְיָא","r":"A01836","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִילְיָא\">אִילְיָא</a></div>","alt":["אִלְיָא"]},"1837":{"h":"אליאס","r":"A01837","html":"<div class=\"sense\"> read <a href=\"#\" data-headword=\"*אִילִיאוֹס\">אִילִיאוֹס</a> q. v.</div>","alt":[]},"1838":{"h":"אַלִּיבָּא","r":"A01838","html":"<div class=\"sense\"> (= <span dir=\"rtl\">אַל־לי׳</span> = <span dir=\"rtl\">עַל־לי׳</span>) <i>according to the opinion, in the sense of</i>. <span class=\"citation\">B. Kam. 13ᵃ</span>, a. fr. <span dir=\"rtl\">א׳ דמאן</span> in whose sense? in accordance with whom? <span class=\"citation\">Sot. 21ᵃ</span> <span dir=\"rtl\">א׳ דהלכתא</span> in accord. with the adopted decision. <span class=\"citation\">Sabb. 28ᵇ</span>, a. v. fr. <span dir=\"rtl\">א׳ דר׳</span> in the sense, developing the opinion, of R.—.</div>","alt":[]},"1839":{"h":"אַלְיָה","r":"A01839","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>attachment</i>, whence </div><div class=\"sense\"><b>1)</b>  (cmp. <a href=\"#\" data-headword=\"זָנָב\">זָנָב</a>, <a href=\"#\" data-headword=\"גְּנוּבְתָּא I\">גֹּונְבָא</a>) <i>tail, fat-tail</i>. <span class=\"citation\">Ab. Zar. 25ᵃ</span> (ref. to <span class=\"citation\">I Sam. IX, 24</span>) what means <i>v’heãleha</i> (and that which is upon [or by] it)? <span dir=\"rtl\">שוק וא׳</span> that means the leg (with thigh) and the fat-tail. <span dir=\"rtl\">מאי והעליה וכ׳</span> and why is it called ‘and that which is upon it’? Because the leg is near the fat-tail (back). <span class=\"citation\">Ḥull. 117ᵃ</span>; a. fr.—<span dir=\"rtl\">כלפי א׳</span> (Ar. s. v. <a href=\"#\" data-headword=\"כְּלַפֵּי\">כלפי</a>; ed. <span dir=\"rtl\">כלפי לָיָיא</span>, Mss. <a href=\"#\" data-headword=\"לָיָא\">לָיָא</a>) <i>towards the tail!</i> i.e. <i>just the reverse!, reverse it</i>. <span class=\"citation\">Pes. 5ᵇ</span>; <span class=\"citation\">Sabb. 93ᵇ</span>; <span class=\"citation\">Ab. Zar. 75ᵃ</span>; a. fr. [Rashi: <span dir=\"rtl\">כלפי ליֵיא</span> where are you turning to?]</div><div class=\"sense\"><b>—2)</b> <i>ear-lap.</i> <span class=\"citation\">Keth. 5ᵇ</span></div>","alt":[]},"1840":{"h":"אֵלִיָּהוּ","r":"A01840","html":"<div class=\"sense\"> (b. h.) pr. n. m. <i>Eliyahu, Elijah</i>, the great prophet in the days of Ahab, freq. represented, in Talmud and Midrashim, as intervening in behalf of the pious and punishing wrong-doers, and expected, in the Messianic days, to clear up doubts and prepare the heavenly kingdom; cmp. <span class=\"citation\">Mal. III, 23</span>.—<span class=\"citation\">Ber. 58ᵃ</span>, a. fr. <span dir=\"rtl\">אתא א׳ אידמי ליה וכ׳</span> E. came and appeared to him in the disguise of &amp;c. <span class=\"citation\">Gen. R. s. 33</span>, a. fr. <span dir=\"rtl\">אתא א׳ זכור לטוב</span> E., whose memory be blessed, came &amp;c. <span class=\"citation\">B. Mets. I, 8</span> (<span class=\"citation\">37ᵃ</span>), a. fr. <span dir=\"rtl\">יהא מונח עד שיבוא א׳</span> let it be deposited until E. shall come (and decide to whom it belongs, i.e. an indefinite time until the matter be cleared up). <span class=\"citation\">Men. 45ᵃ</span>; a. fr.—סֵדֶר אֵלִיָהוּ־ <i>Seder Eliyahu</i>, name of a lost Talmudic treatise, divided into Seder Eliyahu Rabba (Large) and S. E. Zuta (Small). <span class=\"citation\">Keth. 106ᵃ</span> (of legendary origin).</div>","alt":[]},"1841":{"h":"אֱלִיהוּא","r":"A01841","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"> (b. h.) <i>Elihu</i>, one of Job’s friends. <span class=\"citation\">Y. Sot. V, end, 20ᵈ</span>. <span class=\"citation\">Yalk. Job 919</span>. <span class=\"citation\">B. Bath. 15ᵇ</span></div>","alt":[]},"1842":{"h":"אֶלְיְהוֹעֵינַי","r":"A01842","html":"<div class=\"sense\"> (b. h.) pr. n. m. <i>Elioenai</i>, a highpriest. <span class=\"citation\">Par. III, 5</span>.</div>","alt":["אֶלְיוֹעֵנַי"]},"1843":{"h":"אַלְיוֹן","r":"A01843","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (√<a href=\"#\" data-headword=\"לוי\">לוי</a>, v. <a href=\"#\" data-headword=\"אַלְיָה\">אַלְיָה</a>) <i>thumb, great toe.</i> Pl. <span dir=\"rtl\">אַלְיוֹנִים</span>. <span class=\"citation\">Pesik. R. s. 31</span> <span dir=\"rtl\">אַלְיוֹנֵי ידיהם</span> their thumbs; <span class=\"citation\">Midr. Till. to Ps. CXXXVII, 4</span>; Yalk. a. l.</div>","alt":[]},"1844":{"h":"אִלְיוֹן","r":"A01844","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Ex. XXIX, 20</span>; a. e.—<span class=\"citation\">Git. 69ᵃ</span> <span dir=\"rtl\">טופרא דאִלְייוֹנָא</span> (Rashi <span dir=\"rtl\">אליינא</span>, corr. acc.) the nail of the thumb.—Pl. <span dir=\"rtl\">אִלְיוֹנַיָּא</span>. <span class=\"citation\">Targ. Ps. CXXXVII, 4</span> <span dir=\"rtl\">קטעו לואי אִלְיוֹנֵיהוֹן בככיהון</span> (missing in some ed.) the Levites cut their thumbs off with their teeth; v. quot. in <a href=\"#\" data-headword=\"אַלְיוֹן\">preced.</a></div>","alt":["אִלְיוֹנָא","אִיל׳"]},"1845":{"h":"אליוסטון","r":"A01845","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִלְיַסְטוֹן\">אִלְיַסְטוֹן</a></div>","alt":[]},"1846":{"h":"אֶלְיוֹעֵינִי","r":"A01846","html":"<div class=\"sense\">, v. <span dir=\"rtl\">אֶלְיְהִוֹ׳</span></div>","alt":[]},"1847":{"h":"אִלְיוֹפּוֹלִיס","r":"A01847","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִלְמָלֵא\">אִילְי׳</a></div>","alt":[]},"1848":{"h":"אִלְיוּתָא","r":"A01848","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (אלי II) <i>wail, eulogy</i>. <span class=\"citation\">Targ. Job III, 7</span>; v. <a href=\"#\" data-headword=\"אִילַּוָּיוּתָא\">אִילַּוָּיוּתָא</a>.</div>","alt":[]},"1849":{"h":"אֱלֶיוְתְּרוֹפּוֹלִיס","r":"A01849","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"> (Ἐλευθερόπολις) <i>Eleutheropolis</i> (Freetown), an Idumean town corresponding to <i>Hori</i> (<span class=\"citation\">Gen. XIV, 6</span>). <span class=\"citation\">Gen. R. s. 42</span> (ed. corrup. <span dir=\"rtl\">מטרופ׳</span>) read with Ar. <span dir=\"rtl\">ואת החורי א׳ ולמה קורא אותה א׳ שבררו … אותה ויצאו להן לחירות</span> they selected it for their residence and made themselves independent.</div>","alt":[]},"1850":{"h":"אַלִּיחְרוֹק","r":"A01850","html":"<p class=\"morphology\">pr. n.</p><div class=\"sense\"><i>Alliḥrok</i>, name of an Egyptian eparchy or nomos, prob. <i>Heracleotes</i>. <span class=\"citation\">Targ. Y. Gen. X, 6</span>; <span class=\"citation\">I Chr. I, 8</span> (h. text <a href=\"#\" data-headword=\"*פּוּט\">פוט</a>), ed. Rahm. <span dir=\"rtl\">אלייחרק</span> (Var. <span dir=\"rtl\">אליחרק</span>).</div>","alt":[]},"1851":{"h":"אֲלִיטָא","r":"A01851","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֲלִיטָא III\"><span dir=\"rtl\">חֲלִיטָא</span> III</a></div>","alt":[]},"1852":{"h":"אִלְיָיה","r":"A01852","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִילְיָא\">אִילְיָא</a></div>","alt":[]},"1853":{"h":"אִלְיַיסְטֹן","r":"A01853","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִלְיַסְטוֹן\">אִלְיַסְטוֹן</a></div>","alt":[]},"1854":{"h":"אַלְיָית","r":"A01854","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (אלי II) <i>female wailer.</i> <span class=\"citation\">Kel. XVI, 7</span> <span dir=\"rtl\">רביעית של א׳</span> the wailer’s musical instrument. <span class=\"citation\">Ib. XV, 6</span>.—Ch. <a href=\"#\" data-headword=\"אָלְיְתָא\">אָלְיְתָא</a> q. v.</div>","alt":["אַלְיָת"]},"1855":{"h":"אֱלִיל","r":"A01855","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (אלל <i>to roll</i>, sec. r. of <a href=\"#\" data-headword=\"אֲוַל\">אול</a>; cmp. <a href=\"#\" data-headword=\"חוּל\">חול</a> a. <span dir=\"rtl\">גִּלּוּלִים</span>) </div><div class=\"sense\"><b>1)</b>  (cacophem.) <i>idol.</i> <span class=\"citation\">Ab. Zar. IV, 3</span> (Talm. ed. <span dir=\"rtl\">ע&quot;ז</span>); a. e.—Pl. <span dir=\"rtl\">אֱלִילִים</span>. <span dir=\"rtl\">עבודת א׳</span> (abbr. <span dir=\"rtl\">ע&quot;א</span>) <i>idolatry;</i> also <i>idol</i> (cmp. <a href=\"#\" data-headword=\"יִרְאָה\">יִרְאָה</a>). <span class=\"citation\">Snh. 97ᵇ</span>. <span class=\"citation\">Yoma 9ᵇ</span>; a fr.</div><div class=\"sense\"><b>—2)</b> <i>offal of meat</i>, <i>v.</i> <a href=\"#\" data-headword=\"אֱלָל\">אֱלָל</a>.</div>","alt":[]},"1856":{"h":"אֱלִיל ²","r":"A01856","html":"<div class=\"sense\">—Pl. <span dir=\"rtl\">אֱלִילַיָּא</span>. <span class=\"citation\">Targ. Y. Lev. I, 2</span>.</div>","alt":[]},"1857":{"h":"אֱלֵיל","r":"A01857","html":"<div class=\"sense\"> (= <a href=\"#\" data-headword=\"יָלֵיל\">יְלֵיל</a>) <i>to lament</i>.<span class=\"citation\">Targ. Is. XV, 4</span> (<span class=\"citation\">XIV, 31</span>); <span class=\"citation\">Joel I, 11</span>.</div>","alt":[]},"1858":{"h":"אַלֵּיל","r":"A01858","html":"<div class=\"sense\"> Pa. of <a href=\"#\" data-headword=\"אֲלַל\">אֲלַל</a>.</div>","alt":[]},"1859":{"h":"אַלִּילָא","r":"A01859","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"אַלֵּיל\">preced.</a>) <i>spy.</i> <i>—</i> Pl. <a href=\"#\" data-headword=\"אַדִּילֵי\">אַלִּילֵי</a>. <span class=\"citation\">Targ. Gen. XLII, 9</span>; a. e. (ed. Berl. <span dir=\"rtl\">אָלִי׳</span>).</div>","alt":[]},"1860":{"h":"אֵלִים","r":"A01860","html":"<div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"מִלְוָון\">בֵּית א׳</a> pr. n. pl. <i>Beth-Elim</i>, near Mount Tabor. <span class=\"citation\">Gen. R. s. 99</span> beg. Mekh. Yithro s. 5 <a href=\"#\" data-headword=\"אֱלֹהִים\">(אלהים</a>).</div><div class=\"sense\"><b>—2)</b>  <a href=\"#\" data-headword=\"אֵלִים\">אֵלִים</a> pl. of <a href=\"#\" data-headword=\"אַיִל\">אַיִל</a> q. v.</div>","alt":[]},"1861":{"h":"אֲלֵים","r":"A01861","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֲלַם\">אֲלַם</a></div>","alt":[]},"1862":{"h":"אַלִּים","r":"A01862","html":"<p class=\"morphology\">m.</p><div class=\"sense\">, <a href=\"#\" data-headword=\"אַלִּימָא\">אַלִּימָא</a> f. (<span dir=\"rtl\">אלם</span>) <i>strong, influential; violent</i>. <span class=\"citation\">Targ. Y. Gen. XXV, 23</span>; a. e.—<span class=\"citation\">Git. 60ᵇ</span>, a. fr. <span dir=\"rtl\">כל דא׳ גבר</span> whoever is in power wins (right of possession in cases in which the judge is unable to decide). <span class=\"citation\">Ḥull. 39ᵇ</span> <span dir=\"rtl\">איניש אלמא</span> a powerful man (defying the law).—<span class=\"citation\">Keth. 14ᵃ</span> <span dir=\"rtl\">א׳ ליה בריא</span> to him the positive assertion is the stronger argument.—Pl. <span dir=\"rtl\">אַלִּימֵי</span> <span class=\"citation\">Ḥull. 76ᵃ</span> <i>thick</i> (sinews). <span class=\"citation\">Kidd. 59ᵃ</span> <span dir=\"rtl\">באגא דא׳</span> a village community of violent men.—Fem. <span class=\"citation\">Kidd. 44ᵇ</span> <span dir=\"rtl\">מי א׳ כיד אביה</span> is she as strong, has she the same authority as her father has? <span class=\"citation\">B. Mets. 34ᵃ</span> <span dir=\"rtl\">מי א׳ ממתניתן</span> is (the Boraitha) stronger (less pliable) than our Mishnah?—<span class=\"citation\">Ḥull. 48ᵇ</span> <a href=\"#\" data-headword=\"אַלִּימְתָּא\">אַלִּימְתָּא</a> the strong, thick (pin).—Pl. <a href=\"#\" data-headword=\"אַלִּימְתָּא\">אַלִּימָתָא</a>. <span class=\"citation\">Yeb. 43ᵃ</span> <a href=\"#\" data-headword=\"א׳\">א׳</a> strong, thick combs.</div>","alt":["אַלְּמָא"]},"1863":{"h":"אַלִּימָא","r":"A01863","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַלִּים\">preced.</a></div>","alt":[]},"1864":{"h":"אִלֵּימָא I","r":"A01864","html":"<div class=\"sense\"><b>1)</b>  (= (= <a href=\"#\" data-headword=\"אִין I\">אִין</a> <i>if</i>; <a href=\"#\" data-headword=\"לֵי\">לי</a> = <a href=\"#\" data-headword=\"לָא I\">לָא</a> <i>not;</i> מא <i>quidem, somehow</i>) <i>unless, but for</i> (followed by <span dir=\"rtl\">ש־</span>; cmp. <a href=\"#\" data-headword=\"אִלְמָלֵא\"><span dir=\"rtl\">אִלְמָלֵא</span> I</a>). <span class=\"citation\">Num. R. s. 18</span>, end <span dir=\"rtl\">אי׳ מֵי … שמעמ׳ וכ׳</span> but for the sticky substance in the nose intercepting the evil smell.</div><div class=\"sense\"><b>—2)</b>  (= <span dir=\"rtl\">אִילּוּ־מָא</span> if somehow) <i>if</i> (ruling the verb without mediation of a relative; cmp. <a href=\"#\" data-headword=\"אִלְמָלֵא\">אִלְמָלֵא</a> 2). Ib. <span dir=\"rtl\">א׳ תופשת וכ׳</span> if (the harsh ringing sound) should take a permanent hold of his ear, it would be bound up (with his body, sub. <span dir=\"rtl\">בלבו</span> as in Tanḥ. Ḥukkath 1, where our w. is substituted by <a href=\"#\" data-headword=\"אִלְמָלֵא\">אִלְמָלֵא</a>).</div><div class=\"sense\"><b>—3)</b>  v. <a href=\"#\" data-headword=\"אִילֵימָא\">אִילֵימָא</a></div>","alt":["אִילֵּימָא"]},"1865":{"h":"אִלֵּימָא II","r":"A01865","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><b>1)</b> <i>mute</i>, v. <a href=\"#\" data-headword=\"אִלְּמָא\">אִלְּמָא</a>. <span class=\"citation\">Targ. Y. Ex. IV, 11</span>.—</div><div class=\"sense\"><b>*2)</b> <i>thick</i>, v. <a href=\"#\" data-headword=\"אַלִּים\">אַלִּים</a>. <span class=\"citation\">Ḥull. 76ᵇ</span></div>","alt":["אִילֵּ׳","(אֱלִימָא)"]},"1866":{"h":"אַלִּימוּתָא","r":"A01866","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (אֲלַם 1) <i>strength, force</i>. <span class=\"citation\">Targ. Job XXX, 21</span>. <span class=\"citation\">Targ. Y. Ex. XXV, 2</span>. Cmp. <a href=\"#\" data-headword=\"אוּלְמָא\">אוּלְמָא</a>.</div>","alt":["אַלְּמוּתָא"]},"1867":{"h":"אִלֵּימְנָא","r":"A01867","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (אֲלַם 3) <i>mute</i>. <span class=\"citation\">Targ. Ps. XXXVIII, 14</span> Ms. (ed. <a href=\"#\" data-headword=\"אִילְּמָנָא\">אִילְּמָנָא</a>).</div>","alt":[]},"1868":{"h":"אַלִּימְתָּא","r":"A01868","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַלִּים\">אַלִּים</a></div>","alt":[]},"1869":{"h":"אֲלִינְתִּין","r":"A01869","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֲלוּנְטִית I\">אֲלוּנְטִית</a></div>","alt":["אֲלִינְתִּית"]},"1870":{"h":"*אָלִיס","r":"A01870","html":"<p class=\"morphology\">m.</p><div class=\"sense\">, only in pl. <span dir=\"rtl\">אֲלִיסִים</span>, <a href=\"#\" data-headword=\"אֲנִיסִין\">אֲלִיסִין</a> &amp;c. (<span dir=\"rtl\">אלס</span>, cmp. <span dir=\"rtl\">אלץ</span> in Hebr. Dict. a. <span dir=\"rtl\">רסס</span>, <span dir=\"rtl\">רצץ</span>) <i>ruins, debris</i>. <span class=\"citation\">Lev. R. s. 19</span> (referring to <span class=\"citation\">Amos VI, 11</span>) <span dir=\"rtl\">הדין רסיסה אית מיניה אל׳</span> (read <a href=\"#\" data-headword=\"רְסִיסָא\">רסיסא</a>) of what is demolished by making breaches, there remain ruins, <span dir=\"rtl\">והדין בקיעא לית מיניה אי</span> while of what is demolished by chopping, no ruins remain; <span class=\"citation\">Koh. R. to X, 18</span> (corr. acc.); <span class=\"citation\">Cant. R. to IV, 14</span>. Cmp. <a href=\"#\" data-headword=\"בִּיזָּא\">בִּיזָא</a> and <a href=\"#\" data-headword=\"*אִלְסִיס\">אִלְסִיס</a>.</div>","alt":["אֲלִיס","(אִילִיס)"]},"1871":{"h":"אֲלֵיס","r":"A01871","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֲלַס\">אֲלַס</a></div>","alt":[]},"1872":{"h":"אִלְיַסְטוֹן","r":"A01872","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (ἡλιαστός, acc., fr. ἡλιάζω, v. Gr. Dict.) <i>a luscious wine</i> (vinum dulce) for which the grapes were to be dried in the sun for three days, after which they were gathered and trodden on the fourth during the full fervor of the midday heat (Sm. Ant. s. v. <i>Vinum;</i> Columella XII, 27). <span class=\"citation\">Men. VIII, 6</span> אליוסטון Mish. (Ar. ed. Koh. <span dir=\"rtl\">אלייס׳</span>, Talm. ed. 86ᵇ <a href=\"#\" data-headword=\"הליסטיון\">הליסטיון</a>, <span dir=\"rtl\">היל׳</span>). <span class=\"citation\">B. Bath. 97ᵇ</span> אלייסטון Ar. (Var. a. ed. <span dir=\"rtl\">היליסטון</span>; Ms. <span dir=\"rtl\">והלאסטון</span>, <span dir=\"rtl\">והיליסטיון</span>; v. Rabb. D. S. a. l.). <span class=\"citation\">Tosef. Men. IX, 9</span> (from which B. Bath. l. c. is quoted) <a href=\"#\" data-headword=\"אִלְיַסְטוֹן\">אליסטון</a>.</div>","alt":["אִלְיַיסְטוֹן","הִלְיַיסְטוֹן"]},"1873":{"h":"אֱלִיעֶזֶר","r":"A01873","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Eliezer</i>, 1) servant of Abraham.</div><div class=\"sense\"><b>1)</b>  servant of Abraham. <span class=\"citation\">Gen. R. s. 44</span>; a. fr. 2) several Tanaim: a) E. ben Hyrcanus; E. b. Jacob, E. bar Zadok, disciples of R. Johanan b. Zaccai of the second gener.—b) E. b. Judah, E. b. Matathias; E. b. Ḥisma, of the third gener.—c) E. hak-Kappar, a late member of the fifth gener.</div>","alt":[]},"1874":{"h":"אֲלֵיף","r":"A01874","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֲלַף I\">אֲלַף</a></div>","alt":[]},"1875":{"h":"אליפיס","r":"A01875","html":"<div class=\"sense\">, Y. Shebi. IV, 35ᶜ top, read <a href=\"#\" data-headword=\"*אִלְסִיס\">אִלְסִיס</a>.</div>","alt":[]},"1876":{"h":"*אֶלִּיקָה","r":"A01876","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (ἕλιξ, acc. … κα) <i>wind-lass</i> for launching ships. <span class=\"citation\">Y. Sabb. VII, 10ᶜ</span> top, read: <span dir=\"rtl\">ההן דמגפר אעין למני וחבלין לא׳</span> he who pitches wood for vessels or ropes for a wind-lass.</div>","alt":[]},"1877":{"h":"*אֲלִיקִי","r":"A01877","html":"<div class=\"sense\"> (a disguise of <a href=\"#\" data-headword=\"אֱלֹהִים\">אלהים</a> for the purpose of avoiding the utterance of the divine name, cmp. <a href=\"#\" data-headword=\"אֱלוֹהַּ\">אֱלוֹהַּ</a>) <i>by God! forsooth</i> (ironically). Pesik. Baḥod. p. 104ᵃ אלי׳ אני תובע בה Ar. (ed. <span dir=\"rtl\">אל אהא</span>, Ms. Oxf. <span dir=\"rtl\">אליקי איני</span>) forsooth, I shall propose to her, i.e. do you believe I shall &amp;c.? <span class=\"citation\">Cant. R. to I, 4</span> <span dir=\"rtl\">אלעי׳ אני נותן וכ׳</span> forsooth (do you believe) I shall give &amp;c. [V. Pesik. l. c. note 81.]</div>","alt":["אַלְעִיקִי"]},"1878":{"h":"אֶלְיָקִים","r":"A01878","html":"<div class=\"sense\"> (b. h.) pr. n. m. <i>Eliakim</i>. <span class=\"citation\">Ab. Zar. 58ᵃ</span> R. El. attendant of Rabba.</div>","alt":[]},"1879":{"h":"אלירא","r":"A01879","html":"<div class=\"sense\"> read <a href=\"#\" data-headword=\"אִלַּרְיָא\">אִלַּרְיָא</a>.</div>","alt":[]},"1880":{"h":"אֶלִישָׁע","r":"A01880","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Elisha</i>, </div><div class=\"sense\"><b>1)</b>  the prophet. <span class=\"citation\">Ber. 10ᵇ</span>. <span class=\"citation\">Gen. R. s. 25</span>; a. e.</div><div class=\"sense\"><b>—2)</b>  E. ben Abuyah, surnamed <a href=\"#\" data-headword=\"אַחֵר\">אַחֵר</a>, q. v. <span class=\"citation\">Aboth. IV, 20</span>; <span class=\"citation\">M. Kat. 20ᵃ</span></div><div class=\"sense\"><b>—3)</b>  one E. surnamed <span dir=\"rtl\">בעל כנפים</span> ‘winged’. <span class=\"citation\">Sabb. 49ᵃ</span>; <span class=\"citation\">130ᵃ</span>. <span class=\"citation\">Y. Ber. II, 4ᶜ</span> bot.</div>","alt":[]},"1881":{"h":"בֵּי אֱלִישָׁפָט","r":"A01881","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בֵּלְשָׁפָט\">בֵּלְשָׁפָט</a></div>","alt":[]},"1882":{"h":"אַלְיָת","r":"A01882","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַלְיָית\">אַלְיָית</a></div>","alt":[]},"1883":{"h":"אָלְיְתָא","r":"A01883","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>wailing woman.</i> Pl. <a href=\"#\" data-headword=\"אָלְיְתָא\">אָלְיָתָא</a>. <span class=\"citation\">Targ. Jer. IX, 16</span> (<span class=\"citation\">17</span>) ed. Ven. <a href=\"#\" data-headword=\"אֲיֵלִיתָא\">אֲיֵלִיתָן</a>, ed. Vien. <a href=\"#\" data-headword=\"*אַלְיָתָא\">אֶלְיָתָא</a>.</div>","alt":[]},"1884":{"h":"*אַלְיָתָא","r":"A01884","html":"<div class=\"sense\"> f. = <a href=\"#\" data-headword=\"אִלְיוּתָא\">אַלְיוּתָא</a>. <span class=\"citation\">Gen. R. s. 15</span>, end; Pesik. Ron. p. 142ᵇ <span dir=\"rtl\">א׳ ובכיתא</span> wailing and weeping; v. <a href=\"#\" data-headword=\"אַלִּיתָא\">אַלִּיתָא</a></div>","alt":[]},"1885":{"h":"אַלְיְתָא","r":"A01885","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> , <i>fat-tail</i>. <span class=\"citation\">Targ. Ex. XXIX, 22</span>; a. e.—<span class=\"citation\">Ḥull. 127ᵃ</span> <span dir=\"rtl\">בשמתא נרש … ואליתיה</span> excommunicated be Narash with its fat, skin and tail, i.e. all its inhabitants.</div>","alt":["(אַלִּיתָא)"]},"1886":{"h":"אַלִּיתָא","r":"A01886","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"אֵלָה\">אֵלָה</a>, <a href=\"#\" data-headword=\"אַלֹּון I\">אַלֹּון</a> &amp;c.) </div><div class=\"sense\"><b>1)</b> <i>fig-tree</i> (of a certain species).—<span dir=\"rtl\">בְּרַת א׳</span> name of a fig species. <span class=\"citation\">Gen. R. s. 15</span>, end <span dir=\"rtl\">ברת א׳ וכ׳</span> Ar. (ed. <a href=\"#\" data-headword=\"אלי I\">אלי</a>) it is called <i>brath alitha</i> (daughter of mourning, v. <a href=\"#\" data-headword=\"*אַלְיָתָא\">אַלְיָתָא</a>), because it has brought wailing and weeping into the world (as the fruit of the tree of knowledge).</div><div class=\"sense\"><b>—2)</b> <i>wood of the fig-tree</i>, used as kindling wood on the altar (h. . <span class=\"citation\">Tam. II, 4</span> (Mish. <span dir=\"rtl\">תא …</span>, Talm. 29ᵃ … <span dir=\"rtl\">תה</span>). <span class=\"citation\">Yoma 24ᵇ</span>. Y. ib. II, 39ᶜ top.—Pl. <span dir=\"rtl\">אַלִּיתוֹת</span>. <span class=\"citation\">Par. III, 9</span>.</div>","alt":["אֲלִיתָא"]},"1887":{"h":"*אִלִּיתָא","r":"A01887","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (pronunc. and meaning doubtful) <i>Illitha</i>, something supposed to render fire-proof or extinguish the fire. <span class=\"citation\">Snh. 108ᵇ</span> יש לנו דבר אחד וא׳ שמה Ar. (ed. <span dir=\"rtl\">וע׳</span>) we have something, its name is Ill. [perhaps to be read <span dir=\"rtl\">דבר אחר</span> a (female) idol]; <span class=\"citation\">Yalk. Job 906</span> <a href=\"#\" data-headword=\"עלְעִל\">עיל׳</a>, Ms. <span dir=\"rtl\">עליונה</span>]. [<span class=\"citation\">B. Bath. 73ᵃ</span> ומחינן ליה באלי׳ Ar. Var. s. v. <a href=\"#\" data-headword=\"אַלָּתָא\">אלתא</a>, ed. <a href=\"#\" data-headword=\"אַלּוּתָא\">אַלּוּתָא</a>, Rashi <a href=\"#\" data-headword=\"אַלְוָותָא\">אַלְוָותָא</a>, Ms. Oxf. <span dir=\"rtl\">ואית לן</span>, <a href=\"#\" data-headword=\"אַלְוָותָא\">אלוותא</a> pl. of <a href=\"#\" data-headword=\"אַלָּתָא\">אַלָּתָא</a>. The use of the masc. gend. in connection with the word, makes the passage appear spurious.]</div>","alt":["עִלִּיתָא"]},"1888":{"h":"אַלִּיתָה","r":"A01888","html":"<div class=\"sense\"><i>, </i> pl. <span dir=\"rtl\">אַלִּיתוֹת</span>, v. <a href=\"#\" data-headword=\"אַלִּיתָא\">אַלִּיתָא</a>.</div>","alt":[]},"1889":{"h":"אִלֵּךְ","r":"A01889","html":"<div class=\"sense\"> = <a href=\"#\" data-headword=\"אִילֵּין\">אִילֵּין</a>. <span class=\"citation\">Dan. III, 12</span>; <span class=\"citation\">13</span>.</div>","alt":[]},"1890":{"h":"אֲלַכְסָא","r":"A01890","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Alaxa, Lixah</i>, abbrev. of Alexander. <span class=\"citation\">Y. Keth. V, beg. 29ᶜ</span> R. Al.—Ib. IX, 33ᵇ <span dir=\"rtl\">א׳ אמר לו ר׳ מנא</span> (read <span dir=\"rtl\">לר׳ מנא</span>); <span class=\"citation\">Y. Shebu. VII, 38ᵃ</span> bot. <span dir=\"rtl\">ליכסה וכ׳</span> name of a gentile judge.</div>","alt":["לִיכְסָה"]},"1891":{"h":"אֲלַכְסוֹן","r":"A01891","html":"<div class=\"sense\"> (= <a href=\"#\" data-headword=\"לוֹכְסָן\">לוכסן</a>, λοξός; cmp. howev. ἀλλάξ)</div><div class=\"sense\"><b>1)</b>  (adv.) <i>athwart, crosswise</i>. <span class=\"citation\">Tosef. Kel. B. Mets. VIII, 5</span> two feet &amp;c. of a bed cut off <a href=\"#\" data-headword=\"א׳\">א׳</a> crosswise; (<span class=\"citation\">Kel. XVIII, 5</span> <a href=\"#\" data-headword=\"לוֹכְסָן\">לוכסן</a>).</div><div class=\"sense\"><b>—2)</b>  <a href=\"#\" data-headword=\"אֲלַכְסוֹן\">אֲלַכְסוֹן</a>, ch. form <a href=\"#\" data-headword=\"אֲלַכְסוֹן\">אֲלַכְסוֹנָא</a> m. <i>diagonal line, diameter</i>. <span class=\"citation\">B. Bath. 101ᵇ</span>; <span class=\"citation\">Succ. 8ᵃ</span> <span dir=\"rtl\">כל אמתא … באלכסונָהּ</span> a figure of one square cubit has a diagonal line of 1<sup>2</sup>/<sub>5</sub> cubits (approximately). <span class=\"citation\">Men. 35ᵃ</span>; <span class=\"citation\">Meg. 24ᵇ</span> must be square <span dir=\"rtl\">בתפרן ובאֲלַכְסוֹנָן</span> both as to their seams (not warped) and as to the measure of their diagonal lines. <span class=\"citation\">Erub. 59ᵃ</span> מידת העיר ואלכסונָהּ Ms. K. (ed. <span dir=\"rtl\">בא׳</span>, v. Rashi a. l.) the measure of the circumference of the town plus its diameter. <span class=\"citation\">B. Bath. 99ᵃ</span> <span dir=\"rtl\">ודילמא בא׳ הוו קיימי</span> perhaps the Cherubim in the Sanctuary were placed across the room; a. fr.</div>","alt":[]},"1892":{"h":"אֲלַכְסִין","r":"A01892","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"אֲלַכְסָא\">אֲלַכְסָא</a>) <i>Alexandrians</i>, name of a <i>nut</i>, prob. <i>a species of pistachio</i>. <span class=\"citation\">Ab. Zar. 14ᵃ</span> <a href=\"#\" data-headword=\"אֲלַכְסִין\">אלכסין</a> ed. (Ms. M. <a href=\"#\" data-headword=\"אֲלַכְסִין\">אלכסנדרין</a>, Ar. <a href=\"#\" data-headword=\"אכלסין\">אכלסין</a>). Cmp. <a href=\"#\" data-headword=\"אִלְסָרִין\">אִלְסָרִין</a>.</div>","alt":["אֲלַכְסַנְדְּרִין"]},"1893":{"h":"אֲלֶכְסַנְדְּרָא","r":"A01893","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Alexander</i>. <span class=\"citation\">Y. Dem. II, 22ᶜ</span> top, (an Amora of a place called Tsadoka). <span class=\"citation\">Cant. R. to IV, 12</span>; v. <a href=\"#\" data-headword=\"אֲלֶכְסַנְדְּרִי\">אֲלֶכְסַנְדְּרִי</a>.</div>","alt":[]},"1894":{"h":"אֲלֶכְסַנְדְּרוֹס","r":"A01894","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Alexander</i>. </div><div class=\"sense\"><b>1)</b>  A. the Great, <a href=\"#\" data-headword=\"מוּקְדּוֹן\">מוקדון</a> the Macedonian. <span class=\"citation\">Targ. Cant. VI, 8</span>; Targ. II, <span class=\"citation\">Esth. I, 2</span>.—<span class=\"citation\">Tam. 31ᵇ</span>; a. fr.</div><div class=\"sense\"><b>—2)</b>  name of a judge and of a robber. <span class=\"citation\">Y. Ber. IX, 13ᵇ</span> top (for <a href=\"#\" data-headword=\"אֲלֶכְסַנְדַּרְיָא\">אלכסנדריאה</a> ib. read our w.).</div>","alt":["אֲלַכְ׳"]},"1895":{"h":"אֲלֶכְסַנְדְּרִי","r":"A01895","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><b>1)</b> <i>Alexandrian</i>. Sifra B’ḥukk. chap. V, Lulianus the Alex.</div><div class=\"sense\"><b>—2)</b>  pr. n. m. <i>Alexandri</i>, an Amora. <span class=\"citation\">Y. R. Hash. IV, 59ᶜ</span> bot; a. e.—Cant. R. to IV, 2 <span dir=\"rtl\">דרא …</span> (corr. acc.).</div><div class=\"sense\"><b>—3)</b>  v. <a href=\"#\" data-headword=\"אֲלַכְסִין\">אֲלַכְסִין</a>.—Pl. <span dir=\"rtl\">אֲלֶכְסַנְדְּרִיִּים</span>; fem. <a href=\"#\" data-headword=\"אֲלֶכְסַנְדְּרִית\">אֲלֶכְסַנְדְּרִיֹּות</a>. <span class=\"citation\">Men. 100ᵃ</span> <i>Alexandrians</i>. <span class=\"citation\">Ib. 28ᵇ</span> <span dir=\"rtl\">כוסות א׳</span> (<span class=\"citation\">Yalk. Ex. 369</span> … <span dir=\"rtl\">רִיֹּות</span>) Alexandrian cups (lengthy and narrow). <span class=\"citation\">Tosef. Meg. III</span> (<span class=\"citation\">II), 6</span> <span dir=\"rtl\">בה&quot;כ של א׳</span> a Synagogue built by Alexandrians in Jerusalem.</div>","alt":[]},"1896":{"h":"אֲלֶכְסַנְדַּרְיָא","r":"A01896","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Alexandria</i>, in Egypt. <span class=\"citation\">Targ. Ez. XXX, 15</span>; a. e.—<span class=\"citation\">Y. Ḥag. II, 77ᵈ</span>; a. fr.—<span class=\"citation\">Kel. XV, 1</span>, v. next w.—<span class=\"citation\">Midr. Till. to Ps. XIX</span>, a ship coming <span dir=\"rtl\">מא׳</span>. V. <a href=\"#\" data-headword=\"*אַכְסַנְדַּרְיָא\">אַכְסַנְדַּרְיָא</a>.</div>","alt":["אֲלֶכְסַנְדְּרִיאָה","אֲלַכְ׳"]},"1897":{"h":"אֲלֶכְסַנְדְּרִית","r":"A01897","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>Alexandrian.</i> <span class=\"citation\">Kel. XV, 1</span> ספינה א׳ Mish. ed. (Talm. ed. <span dir=\"rtl\">ס׳ אלכסנדריא</span>) Alexandrian ship, i.e. Sea ship with water reservoirs. <span class=\"citation\">Sabb. 90ᵃ</span>, a. e. <span dir=\"rtl\">נתר א׳</span> Alex. nitron. <span class=\"citation\">Tosef. Nidd. IV, 17</span> Cleopatra <span dir=\"rtl\">מלכת א׳</span> (ed. Zuck. <span dir=\"rtl\">יס</span>—) Egyptian queen.—Pl. <a href=\"#\" data-headword=\"אֲלֶכְסַנְדְּרִית\">אֲלֶכְסַנְדְּרִיֹּות</a>, v. <a href=\"#\" data-headword=\"אֲלֶכְסַנְדְּרִי\">אֲלֶכְסַנְדְּרִי</a>.</div>","alt":[]},"1898":{"h":"אָלַל","r":"A01898","html":"<div class=\"sense\"> (sec. r. of <a href=\"#\" data-headword=\"אֲוַל\">אוּל</a>, v. <a href=\"#\" data-headword=\"אֲוַל\">אֲוַל</a>; cmp. <a href=\"#\" data-headword=\"עָלַל\">עלל</a>) </div><div class=\"sense\"><b>1)</b> <i>to circle.</i> <i> Pi.</i> אִילֵּל <i>to go around; to espy, track</i>. Cant. R. beg. (play on <a href=\"#\" data-headword=\"תּוּר I\">תּוּר</a> a. <a href=\"#\" data-headword=\"תּוֹרָה\">תֹּורָה</a>) <span dir=\"rtl\">אחר ד&quot;ת אִילַּלְתָּ</span> thou didst search after the words of the Law. <span class=\"citation\">Pesik. R. s. 47</span> <i>ḥafar</i> (<span class=\"citation\">Job XXXIX, 29</span>) <span dir=\"rtl\">לשון מְאַלֵּל</span> has the meaning of espying (ed. incorr. <span dir=\"rtl\">יליל</span>, v. ed. Friedm. p. 190ᵇ).—[</div><div class=\"sense\"><b>2)</b> <i>to point out;</i></div><div class=\"sense\"><b>3)</b> <i>to tie around; to be strong;</i> v. <a href=\"#\" data-headword=\"אֵל\">אֵל</a>, <a href=\"#\" data-headword=\"אלי I\"><span dir=\"rtl\">אלי</span> I</a>, <a href=\"#\" data-headword=\"אֵלָה\">אֵלָה</a>, <a href=\"#\" data-headword=\"אִילָּן\">אִילָּן</a> &amp;c., a. <span dir=\"rtl\">אלם</span>.]</div>","alt":[]},"1899":{"h":"אֲלַל","r":"A01899","html":"<div class=\"sense\">, <i>Pa.</i> <a href=\"#\" data-headword=\"אַלֵּיל\">אַלֵּיל</a> ch. same. <span class=\"citation\">Targ. Num. XIII, 2</span>; a. fr.—Deriv. <a href=\"#\" data-headword=\"אַלִּילָא\">אַלִּילָא</a>, <a href=\"#\" data-headword=\"מְאַלְלָא\">מְאַלְּלָא</a>.</div>","alt":[]},"1900":{"h":"אֱלָל","r":"A01900","html":"<div class=\"sense\"> ch. m. (b. h. <a href=\"#\" data-headword=\"אֱלִיל\">אֱלִל</a> <span class=\"citation\">Job XIII, 4</span>; v. <a href=\"#\" data-headword=\"אֱלִיל\">אֱלִיל</a>; cmp. <span dir=\"rtl\">הלל</span>) <i>soft, lax object</i>, whence <i>fatty substance, offal of meat</i>. Targ. Job. l. c.—<span class=\"citation\">Ḥull. IX, 1</span> (<span class=\"citation\">Ib. 121ᵃ</span>, diff. of opin. as to what kind of offal is meant in the Mish., v. <a href=\"#\" data-headword=\"מַרְדְּקָא\">מַרְדְּקָא</a>). Ib. <span dir=\"rtl\">הא׳ המכונס</span> the offal gathered (as a ball). <span class=\"citation\">Zeb. III, 4</span>.—<span class=\"citation\">Toh. I, 4</span> <a href=\"#\" data-headword=\"אֱלִיל\">אֱלִיל</a>. <span class=\"citation\">Meïl. 7ᵃ</span> א׳ כיון דלית ביה וכ׳ <i>ălal</i>, because there is no substantial value in it. <span class=\"citation\">Zeb. 35ᵃ</span> <span dir=\"rtl\">פיגל בא׳</span> if one had an inappropriate thought about <i>ălal</i> of fowls (which is fit to eat).</div>","alt":[]},"1901":{"h":"אַלְלָא","r":"A01901","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אֲלַל\">אֲלַל</a>; cmp. b. h. <a href=\"#\" data-headword=\"דָּרַךְ\">דָּרַךְ</a>) <i>treading the wine or olive press; quantity put into the press at a time</i>. <span class=\"citation\">B. Mets. 105ᵃ</span> הא באתרא … בא׳ Ar. (ed. <a href=\"#\" data-headword=\"*אימיקנטרון\">או׳</a>) the one Rabbi treats of a place where they ordinarily put one <i>khor</i> (measure) into the press at a time, &amp;c. <span class=\"citation\">Esth. R. to I, 2</span> (referring to Esth. l. c., and <span class=\"citation\">Neh. XIII, 15</span> ‘in those days’; play on <i>al’la</i> a. <i>al’lay;</i> v. <a href=\"#\" data-headword=\"אַלְלַי\">next w.</a>) <span dir=\"rtl\">א׳ וּוַי וכ׳</span> ‘<i>wine pressing</i>’ (on Sabbath, Neh. l. c.) and ‘woe’ (persecution as punishment) were those days marked for.</div>","alt":["אוּלְלָא"]},"1902":{"h":"אַלְלַי","r":"A01902","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"אלי II\"><span dir=\"rtl\">אלי</span> II</a>, <i>woe</i>. <span class=\"citation\">Lev. R. s. 17</span>, a. e.; v. <a href=\"#\" data-headword=\"אַלְלַיָּא\">next w.</a> Tanḥ. Aḥaré 2, <span dir=\"rtl\">אלילים</span> (corr. acc.); ed. Bub. 3.</div>","alt":[]},"1903":{"h":"אַלְלַיָּא","r":"A01903","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"אַלְלַי\">preced.</a>) <i>woe-makers</i>, a word coined for playing on <span dir=\"rtl\">הוֹלְלִים</span> (<span class=\"citation\">Ps. LXXV, 5</span>, a. e.). <span class=\"citation\">Lev. R. s. 20</span>; a. e.; v. <a href=\"#\" data-headword=\"וַיָּנַיָּא\">וַויָּנַיָּיא</a> for correct vers.</div>","alt":[]},"1904":{"h":"אָלַם","r":"A01904","html":"<div class=\"sense\"> , v. <a href=\"#\" data-headword=\"אָלַל\">אָלַל</a>) </div><div class=\"sense\"><b>1)</b>  [to surround]; <i>to connect, tie</i> (cmp. <span dir=\"rtl\">אסר</span>. <a href=\"#\" data-headword=\"חָגַר I\">חגר</a>); intr. <i>to be tied up, excluded, lonely, mute;</i> v. <a href=\"#\" data-headword=\"אִלֵּם\">אִלֵּם</a>, <a href=\"#\" data-headword=\"אַלְמוֹן II\"><span dir=\"rtl\">אַלְמוֹן</span> II</a>, <a href=\"#\" data-headword=\"אַלְמָנָה\">אַלְמָנָה</a>, <a href=\"#\" data-headword=\"אוּלָם I\">אוּלָם</a>.</div><div class=\"sense\"><b>—2)</b> <i>to grow, be strong</i>, v. <a href=\"#\" data-headword=\"אֲלַם\">אֲלַם</a>. Cmp. <a href=\"#\" data-headword=\"אַלְמוֹן I\"><span dir=\"rtl\">אַלְמוֹן</span> I</a>. [Cmp. <span dir=\"rtl\">אֵלֶם</span> <span class=\"citation\">Ps. LVIII, 2</span>; <span class=\"citation\">LXX</span> ἄρα, a. v. <a href=\"#\" data-headword=\"אוּלָם I\"><span dir=\"rtl\">אוּלָם</span> I</a>.]</div>","alt":[]},"1905":{"h":"אֲלַם","r":"A01905","html":"<div class=\"sense\"> intr. <a href=\"#\" data-headword=\"אֲלֵים\">אֲלֵים</a> (אַלֵּים <i>Pa.</i>, <span dir=\"rtl\">עלים</span>) (v. <a href=\"#\" data-headword=\"אָלַם\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>to be</i> or <i>grow strong, to grow</i>. <span class=\"citation\">Targ. I Chr. XXII, 12</span> (<span class=\"citation\">13</span>) <a href=\"#\" data-headword=\"אֲלַם\">אֲלַם</a> (h. text <a href=\"#\" data-headword=\"אָמַץ\">אֱמָץ</a>, Var. <span dir=\"rtl\">עילם</span>). <span class=\"citation\">Targ. O. Deut. XXXI, 6</span>; <span class=\"citation\">7</span>; <span class=\"citation\">23</span> ed. Vien. <a href=\"#\" data-headword=\"א׳\">א׳</a> (ed. Berl. <a href=\"#\" data-headword=\"ע׳\">ע׳</a>, v. Berl. Targ. O. II, p. 59).—<span class=\"citation\">B. Bath. 124ᵃ</span>; <span class=\"citation\">135ᵇ</span> (he left them) <span dir=\"rtl\">דיקלא וא׳</span> a slender palm-tree and it grew thick.</div><div class=\"sense\"><b>—2)</b> <i>to tie</i>, v. <a href=\"#\" data-headword=\"אֲלוּמָּא\">אֲלוּמָּא</a>.</div><div class=\"sense\"><b>—3)</b> <i>to be mute;</i> v. Ithp.</div><div class=\"sense\"><b>Pa. אַלֵּים</b> <div class=\"sense\"><b>1)</b> <i>to be strong</i>, v. supra.</div><div class=\"sense\"><b>—2)</b> <i>to strengthen, support.</i> <span class=\"citation\">Targ. II Chr. XI, 17</span>; a. e. Part. pass. f. <span dir=\"rtl\">מְאַלְּמָא</span> <i>resolved, insisting upon</i>. <span class=\"citation\">Targ. Ruth I, 18</span> (h. text <span dir=\"rtl\">מתאמצת</span>).—<span class=\"citation\">B. Kam. 90ᵃ</span> <span dir=\"rtl\">אַלְמוּהָ רבנן וכ׳</span> the Rabbis fortified the husband’s right (gave him superior privileges). <span class=\"citation\">Kidd. 43ᵃ</span> <span dir=\"rtl\">אַלּוּמֵי קא מְאַלִּימְנָא למילתיה</span> (Rashi <span dir=\"rtl\">אַלְּמוּהָ</span>) we (the court) give him privileges.</div><div class=\"sense\"><b>—3)</b> <i>to overpower</i>. <span class=\"citation\">Sabb. 156ᵇ</span> <span dir=\"rtl\">אַלְּמֵיה יצריה</span> his appetite overwhelmed him.</div></div><div class=\"sense\"><b>Ithpa. אִתְאַלֵּם</b> <div class=\"sense\"><b>1)</b> <i>to make one’s self strong, to summon strength</i>. <span class=\"citation\">Targ. Job XXXVI, 19</span>.</div><div class=\"sense\"><b>—2)</b> <i>to become mute, be silenced</i>. <span class=\"citation\">Targ. Ps. XXXIX, 10</span>. <span class=\"citation\">Targ. Koh. XII, 6</span>. [<span class=\"citation\">Targ. Ps. XC, 10</span> <span dir=\"rtl\">מִתְאַלְּמִין</span> (for h. text <a href=\"#\" data-headword=\"בַּהָם\">בָּהֶם</a>?). [<span class=\"citation\">Targ. Job VI, 6</span> Ms. Vers. <span dir=\"rtl\">מִתְאַלֵּם</span> (?), h. text <a href=\"#\" data-headword=\"חַלָּמוּת\">חלמות</a>!.]</div></div>","alt":[]},"1906":{"h":"אִלֵּם","r":"A01906","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><b>1)</b>  cmp. <a href=\"#\" data-headword=\"חֵרֵשׁ\">חֵרֵשׁ</a>) <i>mute, unable to speak</i>, also <i>ignorant.</i> <span class=\"citation\">Ter. I, 6</span>; a. fr.—Ruth. R. to IV, 1 (ref. to <i>almoni</i>, Ruth. l. c.) <span dir=\"rtl\">א׳ היה מד&quot;ת</span> he was unable to speak of (excluded from) the Law (ignorant).—Pl. <span dir=\"rtl\">אִילְּ׳ אִלְּמִין אִלְּמִים</span>. <span class=\"citation\">Snh. 71ᵃ</span>; <span class=\"citation\">100ᵃ</span>.—Fem. <span dir=\"rtl\">אִלֶּמֶת</span>, <a href=\"#\" data-headword=\"אִלֵּימָא II\">אִילֶּ׳</a>. <span class=\"citation\">Num. R. s. 9</span>. <span class=\"citation\">Ḥull. 79ᵃ</span>. <span class=\"citation\">Sot. 10ᵇ</span> <a href=\"#\" data-headword=\"אִסְקְרִיטִין\">אי׳</a>; a. e.</div>","alt":["אִילֵּם"]},"1907":{"h":"אִלְּמָא","r":"A01907","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Ex. IV, 11</span>.—Pl. <span dir=\"rtl\">אִילְּמֵי</span> &amp;c. <span class=\"citation\">Ḥag. 3ᵃ</span>; <span class=\"citation\">Yalk. Ex. 356</span>; Deut. 440. [<span class=\"citation\">Ḥull. 76ᵇ</span> <span dir=\"rtl\">חד אילימא</span>, v. <a href=\"#\" data-headword=\"אִלֵּימָא II\"><span dir=\"rtl\">אִלֵּימָא</span> II</a>, 2.]</div>","alt":["אִילְּמָא","אִילֵּימָא","אֲלוּמָא"]},"1908":{"h":"אַלְּמָא","r":"A01908","html":"<div class=\"sense\"><i>strong</i>, v. <a href=\"#\" data-headword=\"אַלִּימָא\">אַלִּימָא</a>.</div>","alt":[]},"1909":{"h":"אַלְמָא","r":"A01909","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (cmp. b. h. <span dir=\"rtl\">אֵלֶם</span>, v. <a href=\"#\" data-headword=\"אָלַם\">אָלַם</a>) <i>confirmation;</i> (dial. term) <i>consequently</i>. <span class=\"citation\">Pes. 2ᵇ</span> <span dir=\"rtl\">א׳ אור וכ׳</span> consequently <i>ôr</i> means day-light. <span class=\"citation\">Sabb. 151ᵃ</span>; a. fr.</div>","alt":[]},"1910":{"h":"אַלָּמָּא","r":"A01910","html":"<div class=\"sense\"> (= <span dir=\"rtl\">על למה</span>) <i>why?, wherefore?</i> <span class=\"citation\">Erub. 3ᵃ</span> <span dir=\"rtl\">אלמא אמר וכ׳</span> why did R. … say &amp;c.?—<span class=\"citation\">Yoma 2ᵇ</span> <span dir=\"rtl\">אלמה לא ניבעי וכ׳</span> why should separation not be required &amp;c.?; a. fr.</div>","alt":["אַלָּמָּה"]},"1911":{"h":"אַלְמוּג","r":"A01911","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><b>1)</b> <i>red coral</i>. <span class=\"citation\">Tosef. Kel. B. Mets. III, 13</span>; <span class=\"citation\">Kel. XIII, 6</span>; <span class=\"citation\">Sabb. 59ᵇ</span>; Y. ib. VI, 8ᵇ top.</div><div class=\"sense\"><b>—2)</b>  pl. <span dir=\"rtl\">אַלְמוּגִים</span>, <span dir=\"rtl\">אַלְמוּגִין</span> <i>a species of cedar-tree</i>, prob. <i>coral-wood</i> (v. infra as to various opinions). <span class=\"citation\">R. Hash. 23ᵃ</span>; <span class=\"citation\">B. Bath. 80ᵇ</span> sq. <span dir=\"rtl\">א׳ כסיתא</span> <i>almugim</i> is coral (apparently a confusion of <i>coral</i> and <i>coral-wood</i>). <span class=\"citation\">Y. Keth. VII, end, 31ᵈ</span> א׳ אלוים <i>alm</i>. is the aloe-wood (agallochum); (<span class=\"citation\">Gen. R. s. 15</span> beg. <a href=\"#\" data-headword=\"אלווס\">אלווס</a> Ar., ed. <span dir=\"rtl\">אלוום</span>, <span dir=\"rtl\">אלונים</span> corr. acc.). <span class=\"citation\">Pesik. R. s. 33</span> (ref. to <span class=\"citation\">II Chr. II, 7</span> a. <span class=\"citation\">I Kings X, 12</span>); v. <span dir=\"rtl\">גלומי</span>.</div>","alt":[]},"1912":{"h":"אַלְמוֹגָא","r":"A01912","html":"<div class=\"sense\"><i>, </i> pl. <span dir=\"rtl\">אַלְמוּגִין</span>, <span dir=\"rtl\">אַלְמוּגַיָּיא</span> ch. same. <span class=\"citation\">Targ. I Kings X, 11</span>; <span class=\"citation\">12</span>. <span class=\"citation\">II Chr. IX, 10</span>; <span class=\"citation\">11</span>.</div>","alt":[]},"1913":{"h":"אַלְמוֹן I","r":"A01913","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <span dir=\"rtl\">אלם</span>) <i>a cedar species, oak</i> [or <i>terebinth</i>]. . <span class=\"citation\">R. Hash. 23ᵃ</span>; <span class=\"citation\">B. Bath. 80ᵇ</span>; v. <a href=\"#\" data-headword=\"בּוּטְמָא\">בּוּטְמָא</a> a. <a href=\"#\" data-headword=\"בְּלוּט\">בְּלוּט</a>.</div>","alt":[]},"1914":{"h":"אַלְמוֹן II","r":"A01914","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> , v. <span dir=\"rtl\">אלם</span>) [<i>tied up, secluded;</i> cmp. <span class=\"citation\">Targ. I Sam. XXI, 3</span> <a href=\"#\" data-headword=\"טָמִיר\">טמיר</a> for h. <span dir=\"rtl\">אלמני</span>] <i>widower</i>. <span class=\"citation\">Keth. 7ᵇ</span>; a. fr.</div>","alt":[]},"1915":{"h":"אַלְמוֹנִי","r":"A01915","html":"<div class=\"sense\"> m. (b. h. <a href=\"#\" data-headword=\"אַלְמוֹנִי\">אַלְמֹנִי</a> <i>unnamed, unknown</i>, v. <a href=\"#\" data-headword=\"אַלְמוֹן II\">preced.</a>) pr. n. m. <i>Almoni</i>. <span class=\"citation\">Ruth R. to IV, 1</span> <span dir=\"rtl\">פלני א׳ וכ׳</span> the man’s name was Ploni Almoni. Cmp. <a href=\"#\" data-headword=\"אִלֵּם\">אִלֵּם</a>.</div>","alt":[]},"1916":{"h":"אלמיג","r":"A01916","html":"<div class=\"sense\"> <span class=\"citation\">Tosef. Kel. B. Mets. III, 13</span> read <a href=\"#\" data-headword=\"אַלְמוּג\">אַלְמוּג</a>.</div>","alt":[]},"1917":{"h":"*אִלְמֵין","r":"A01917","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (prob. corrupt., for <a href=\"#\" data-headword=\"לִימֵין\">לִימִין</a> λιμὴν) <i>harbor</i>. <span class=\"citation\">Y. Succ. II, beg. 52ᵈ</span> <span dir=\"rtl\">בנתונה בא׳</span> when the ship lies in port.</div>","alt":[]},"1918":{"h":"אִלְמָלֵא","r":"A01918","html":"<div class=\"sense\"><b>1)</b>  (= (= <span dir=\"rtl\">אילו־מא־לָא</span>) <i>if in any way not, if not, but for</i> (usu. without verb or followed by <a href=\"#\" data-headword=\"שֶׁ־\">שֶׁ־</a> or <a href=\"#\" data-headword=\"דְּ־\">דְּ־</a>; cmp. <a href=\"#\" data-headword=\"אִלֵּימָא I\"><span dir=\"rtl\">אִלֵּימָא</span> I</a>, 1). <span class=\"citation\">Snh. 49ᵃ</span> <span dir=\"rtl\">א׳ דוד וכ׳</span> but for David (studying the Law), Joab could wage no war. <span class=\"citation\">Meg. 12ᵇ</span> <span dir=\"rtl\">א׳ אגרות וכ׳</span> but for the previous letters. Tanḥ. Ḥukkath 1 (ed. Bub. 1 <span dir=\"rtl\">אם לא</span>); a. fr.</div><div class=\"sense\"><b>—2)</b>  (= <span dir=\"rtl\">אִילּוּ־מא־לֻא</span>: cmp. <a href=\"#\" data-headword=\"אִלֵּימָא I\"><span dir=\"rtl\">אִלֵּימָא</span> I</a>, 2) <i>if indeed</i>. <span class=\"citation\">Meg. 24ᵇ</span> <span dir=\"rtl\">אלמלי אתה לוי</span> [Ms. M. <span dir=\"rtl\">אלמלא לוי אתה</span>) if thou wert a Levite. <span class=\"citation\">Keth. 33ᵇ</span> <span dir=\"rtl\">אלמלא נגדוה וכ׳</span> if they had lashed Hananiah &amp;c. <span class=\"citation\">Sabb. 118ᵇ</span>; a. fr. [A differentiation of spelling which may have existed for the two opposite meanings of our w., is untraceable; v. Lowe, Pesachim, p. 28.] Cmp. <a href=\"#\" data-headword=\"אִילּוּלָא\">אִילּוּלֵי</a>.</div>","alt":["אִלְמָלֵי","אִילְ׳"]},"1919":{"h":"אִלְמֵן","r":"A01919","html":"<div class=\"sense\"> (deriv. of <a href=\"#\" data-headword=\"אַלְמָנָה\">next w.</a>) <i>to reduce to widowhood, bereave, desert</i>. <span class=\"citation\">Pes. 49ᵃ</span> <span dir=\"rtl\">ומְאַלְמֵן את אשתו</span> will be forced to desert his wife (to leave his home).—<i>Nithpa</i>. <span dir=\"rtl\">נִתְאַלְמְנָה</span> <i>to become a widow</i>. <span class=\"citation\">Y. Keth. II, beg. 26ᵃ</span> (Mishn. ed., a. Talm. Bab. <span dir=\"rtl\">נִתְאַרְמְלָה</span>, v. <a href=\"#\" data-headword=\"אִרְמֵל\">אִרְמֵל</a>).</div>","alt":[]},"1920":{"h":"אַלְמָנָה","r":"A01920","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> v. <a href=\"#\" data-headword=\"אַלְמוֹן I\">אַלְמוֹן</a>) <i>widow</i>. <span class=\"citation\">Keth. I, 1</span>; <span class=\"citation\">2</span>, v. <a href=\"#\" data-headword=\"אֵרוּסִין\">אֵרוּסִין</a>. <span class=\"citation\">Kidd. 75ᵃ</span> <span dir=\"rtl\">אַלְמָנַת עיסה</span> the widow of one of spurious descent; v. <a href=\"#\" data-headword=\"עִיסָה\">עִיסָה</a>; a. fr. Trnsf. <span dir=\"rtl\">דלת א׳</span> a <i>frameless</i> door (or <i>made of one piece</i>). <span class=\"citation\">Erub. 101ᵃ</span>; v. <a href=\"#\" data-headword=\"גְּשָׁמָה\">גַּשְׁמָה</a>.—Denom.</div>","alt":[]},"1921":{"h":"אַלְמָנוּת","r":"A01921","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (b. h.) <i>widowhood</i>. <span class=\"citation\">B. Bath. VI, 4</span> <a href=\"#\" data-headword=\"אֶבֶן\">בית א׳</a> (98ᵇ; Ms. M. <a href=\"#\" data-headword=\"אַרְמְלוּ\">אַרְמְלוּת</a>) a house in which to live in case of widowhood. <span class=\"citation\">Yeb. 45ᵃ</span>; a. e. <span class=\"citation\">Y. Keth. V, 29ᵈ</span> bot. <span dir=\"rtl\">הרי אני מיגדת אַלְמְנוּתִי</span>, v. <a href=\"#\" data-headword=\"אָגַד II\"><span dir=\"rtl\">אָגַד</span> II</a>.</div>","alt":[]},"1922":{"h":"אלנטיאות","r":"A01922","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֲלוּנְטִית I\"><span dir=\"rtl\">אֲלוּנְטִית</span> I</a></div>","alt":[]},"1923":{"h":"אֲלִנִסְטִי","r":"A01923","html":"<div class=\"sense\"> (read <span dir=\"rtl\">אלי׳</span> ἑλληνιστί) <i>Hellenic, in Greek</i>. Tanḥ. Tsav, 2 [a gloss] <span dir=\"rtl\">לשון א׳קטבך קטאב&quot;א</span> in Greek <i>katab’kha</i> (<span class=\"citation\">Hos. XIII, 14</span>) means κατάβα <i>descend;</i> v. <span class=\"citation\">Yalk. Jer. 333</span>. <span class=\"citation\">Y. Sot. VII, beg. 21ᵇ</span> <span dir=\"rtl\">שמע קלון קריין שמע אלונ׳</span> heard them read the <i>Sh’ma</i> in Greek.</div>","alt":["אֲלוּנִיסְתִּין"]},"1924":{"h":"*אֲלַנְקֵי","r":"A01924","html":"<p class=\"morphology\">f. pl.</p><div class=\"sense\"> (= <span dir=\"rtl\">על־ענקא</span> <i>on the neck</i>) <i>poles used to carry burdens on the shoulder of two or more persons</i> (v. Sm. Ant. s. v. <i>Falangæ, phalangæ</i>, which is of Semitic origin). <span class=\"citation\">Bets. 25ᵇ</span> what means ‘provided no carrying on shoulders takes place’? Ans. <span dir=\"rtl\">באלנקי …</span> Ar., Ms. M. (ed. <span dir=\"rtl\">באלו׳</span>) by means of <i>alanke</i> (phalangæ). Ib. <span dir=\"rtl\">למיפק אאלו׳</span> ed. (Ms. <span dir=\"rtl\">באל׳</span>) to be taken out &amp;c. (carried in a sedan chair through which poles are put). Ib. Am. and Mar Zut. allowed themselves to be carried on shoulders of men <span dir=\"rtl\">בשבתא דריגלא באלנ׳</span> Ar., Ms. M. (ed. our w. absent) on a Sabbath during the festive week on phalangæ (to the lecture room). V. <a href=\"#\" data-headword=\"*בְּלוּנְקֵי\">בְּלוּנְקֵי</a>.</div>","alt":["אֲלוּנְקֵי"]},"1925":{"h":"אֲלַס","r":"A01925","html":"<div class=\"sense\">, <i>Pa.</i> <a href=\"#\" data-headword=\"אַלַּס\">אַלַּס</a>, <span dir=\"rtl\">אַלֵּיס</span> (contr. of <span dir=\"rtl\">אלעס</span>, v. <span dir=\"rtl\">לעס</span>) <i>to craunch, bite</i>. <span class=\"citation\">B. Kam. 84ᵃ</span>. <span class=\"citation\">Git. 70ᵃ</span></div>","alt":[]},"1926":{"h":"אָלָס","r":"A01926","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Alas</i> (Valens; v. <a href=\"#\" data-headword=\"וָולִיס\">וָולָס</a>) </div><div class=\"sense\"><b>1)</b>  an Amora. <span class=\"citation\">Y. Kil. I, 27ᵃ</span> top.</div><div class=\"sense\"><b>—2)</b> (?) <span class=\"citation\">Snh. 64ᵃ</span> Sabta son of A.; v. <a href=\"#\" data-headword=\"*אַבְלַס\">אַבְלַס</a></div>","alt":[]},"1927":{"h":"אַלַּס","r":"A01927","html":"<p class=\"morphology\">pr. n.</p><div class=\"sense\"><i>Hellas</i> (= Græcia Magna). [That Italian places are meant in quot. below, is obvious from <span class=\"citation\">Targ. Ezek. XXVII, 7</span>, v. <a href=\"#\" data-headword=\"אִיטַלְיָא\">אִיטַלְיָא</a>.] <span class=\"citation\">Targ. Y. I Gen. X, 4</span> <span dir=\"rtl\">א׳ וטרסס</span> (h. text <span dir=\"rtl\">אלישה ותרשיש</span>) Hellas and Taras (Tarentum, v. <a href=\"#\" data-headword=\"טַרְסִיס\">טַרְסִיס</a>); Targ. Y. II ib.; Y. Meg. I, 71ᵇ bot. <span dir=\"rtl\">אלסטרסס</span>; <span class=\"citation\">Gen. R. s. 37</span>, beg. <a href=\"#\" data-headword=\"אלוסטרוס\">אלוסטרוס</a>, <span dir=\"rtl\">אלסיט׳</span> (corr. acc.). [Targ. Y. a. Midr. reflect geograph. a. ethnograph. conditions and notions of their own days.]</div>","alt":["אִלַּס"]},"1928":{"h":"*אִלְסִיס","r":"A01928","html":"<div class=\"sense\"> [the final <a href=\"#\" data-headword=\"ס\">ס</a> freq. read <span dir=\"rtl\">ם</span> in ed., as <span dir=\"rtl\">אֲלִיסִים</span> &amp;c.] f. (v. <a href=\"#\" data-headword=\"*אָלִיס\">אָלִיס</a>) pr. n. pl. <i>Ilsis</i> &amp;c. (grottoes near Tiberias; v. Jos. B. J. II, 20, 6) <i>ruins</i> of fortified caves. <span class=\"citation\">Koh. R. to III, 9</span> <span dir=\"rtl\">אלס׳</span>. <span class=\"citation\">Y. Shebi. IV, 35ᶜ</span> top <a href=\"#\" data-headword=\"אליפיס\">אליפיס</a>; <span class=\"citation\">Gen. R. s. 34</span> <a href=\"#\" data-headword=\"אילטיס\">אילטיס</a>; Ruth. R. to I, 17 <span dir=\"rtl\">(<a href=\"#\" data-headword=\"*אימיקנטרון\">או׳</a>) <a href=\"#\" data-headword=\"אילוסיס\">אילוסיס</a></span>; <span class=\"citation\">Yalk. Ezek. 351</span> <span dir=\"rtl\">אלפטס</span>; cmp. <a href=\"#\" data-headword=\"בְּטִיטָא\">בְּטִיטָא</a> a. <a href=\"#\" data-headword=\"אִיצְטַדִּין\">אִיצְטַדִּין</a>.</div>","alt":["אֲלִיסִיס","(אילוסיס)"]},"1929":{"h":"אִלְסָרִין","r":"A01929","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*אִלְצָרִין\">אִלְצָרִין</a></div>","alt":[]},"1930":{"h":"אֶלְעָזָר","r":"A01930","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Elazar</i>. </div><div class=\"sense\"><b>1)</b>  E. b. Poïra, counsellor of John Hyrcanus. <span class=\"citation\">Kidd. 66ᵃ</span></div><div class=\"sense\"><b>—2)</b>  Several Tanaim: a) E. b. Azariah; E. b. Arakh. of the second generation; b) E. b. P’rata; E. of Modim, of the third gener.—c) E. b. Jacob; E. b. Shamua; E. b. Simon (bar Yoḥai); E. b. R. Yose the Galilean, of the fourth gener.</div><div class=\"sense\"><b>—3)</b>  Several Amoraim: a) E. b. Antigonus; E. b. R. Yannai, of the second gener. <span class=\"citation\">Y. Ber. V, 9ᵇ</span> bot.; a. e.—b) E. bar Abina. Ib. I, 3ᶜ bot.—c) R. Lazar or E. (in Babli E. b. P’dath) one of the most renowned Amoraim of the third gener. <span class=\"citation\">Erub. 65ᵇ</span>; a. v. fr.</div>","alt":["לָעְזָר"]},"1931":{"h":"אַלְעִיקִי","r":"A01931","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*אֲלִיקִי\">אֲלִיקִי</a></div>","alt":[]},"1932":{"h":"אֶלֶף","r":"A01932","html":"<div class=\"sense\"> (b. h.) <i>thousand.</i> <i> Du.</i> <span dir=\"rtl\">אַלְפַּיִם</span>.—Pl. <span dir=\"rtl\">אֲלָפִים</span>.—א׳ אלפים <i>a million</i>. <span class=\"citation\">Gen. R. s. 8</span> <span dir=\"rtl\">שני א׳</span>; a. fr.—<span class=\"citation\">Ex. R. s. 5</span> אַלְפַּיִם <i>two thousand</i> (men); a. e.</div>","alt":[]},"1933":{"h":"אֲלַף I","r":"A01933","html":"<div class=\"sense\"> <span class=\"citation\">Targ. O. Ex. XXXVIII, 25</span> <a href=\"#\" data-headword=\"אֲלַף I\">אַלַּף</a> ed. Berl. (Y. <span dir=\"rtl\">אלפא</span>); a. fr.—<span class=\"citation\">Snh. 95ᵇ</span> <span dir=\"rtl\">חד א׳</span> one thousand. <span class=\"citation\">Bekh. 8ᵇ</span> <span dir=\"rtl\">מאה א׳ זוזי</span> one hundred thousand zuz; a. fr.—Pl. <span dir=\"rtl\">אַלְפִין</span>, <a href=\"#\" data-headword=\"אַלְלַיָּא\">אַלְפַיָּא</a>. <span class=\"citation\">Targ. Ex. XXXVIII, 26</span>; a. fr. <span class=\"citation\">Targ. I Sam. XVIII, 8</span>; a. fr.—<span class=\"citation\">Y. Dem. VII, 26ᵇ</span> bot.; a. fr.</div>","alt":["אַלַּף","אַלְפָא"]},"1934":{"h":"אֲלַף II","r":"A01934","html":"<div class=\"sense\"> , √לף <i>to join, be joined</i>) <i>to become used; to learn, study, train one’s self</i>.—אֲלִיף <i>accustomed, used to</i>. <span class=\"citation\">Targ. I Sam. XVII, 39</span>. <span class=\"citation\">Targ. O. Num. XXII, 30</span>.—<span class=\"citation\">Targ. Deut. V, 1</span>; a. fr. (v. also <a href=\"#\" data-headword=\"יְלֵיף\">יְלֵיף</a>).—<span class=\"citation\">Cant. R. to II, 2</span> <span dir=\"rtl\">צבי רבי דייליף</span> would you like to study? <span class=\"citation\">B. Bath. 111ᵇ</span> top <span dir=\"rtl\">גוד לית דין צבי למילף</span> take me away from here, this man has no desire to learn (but only to argue). <span class=\"citation\">Taan. 4ᵃ</span> man is bound <span dir=\"rtl\">למֵילַף נפשיה בניחותא</span> [prob. <span dir=\"rtl\">למַלֵּיף</span>, v. infra] to train himself to be gentle; a. fr.</div><div class=\"sense\"><b>Pa. אַלֵּיף  אַלַּף</b> <div class=\"sense\"><i>to train, teach</i>. <span class=\"citation\">Targ. Ps. XVIII, 35</span> <a href=\"#\" data-headword=\"מַלֵּיף\">מַלֵּיף</a> (= <span dir=\"rtl\">מְאַלֵּף</span>). <span class=\"citation\">Targ. Prov. XI, 25</span>; a. fr.—<span class=\"citation\">Koh. R. to IX, 10</span> thou didst emigrate <span dir=\"rtl\">למילף</span> for the sake of studying, <span dir=\"rtl\">והוא גלי לאַלָּפָא</span> but he emigrated for the sake of teaching. Y. Dem. I, 22ᵃ top <span dir=\"rtl\">ולא כן אַלְּפָן רבי</span> (not <span dir=\"rtl\">איל׳</span>) did you not teach us thus?—<span dir=\"rtl\">א׳ זכו</span>, v. infra.</div></div><div class=\"sense\"><b>Af. אוֹלֵף</b> <div class=\"sense\"> as <i>Pa.</i> <span class=\"citation\">Lev. R. s. 30</span> <span dir=\"rtl\">(<a href=\"#\" data-headword=\"מַלֵּיף\">מַלֵּיף</a>) <span dir=\"rtl\">מוֹלִיף עלי זכו</span></span> offers arguments in my favor.</div></div><div class=\"sense\"><b>Ithpa. אִתְאַלַּף</b> <div class=\"sense\"><i>to exercise, practice, exert one’s self</i>. <span class=\"citation\">Targ. Is. II, 4</span>; <span class=\"citation\">XXVI, 9</span>.</div></div>","alt":["אֲלֵיף","(יְלֵיף)"]},"1935":{"h":"אל\"ף","r":"A01935","html":"<div class=\"sense\"><i>Alef</i>, the first letter of the Alphabet. <span class=\"citation\">Y. Snh. I, 18ᵃ</span> bot.; a. fr. <span class=\"citation\">Y. Yeb. IV, 6ᵃ</span> <span dir=\"rtl\">כל שהוא בה&quot;י רבה באל&quot;ף רבא</span> (referring to <i>harbah arbeh</i> <span class=\"citation\">Gen. III, 16</span>) the embryo that counts <i>harbah</i> with Hé, (the numerical value being 212—days), will grow; that which counts <i>arbeh</i> with Alef (i.e. 208 days, or less than seven months) will lie down (die); (cmp. <a href=\"#\" data-headword=\"הַרְבָּה\">הַרְבָּה</a> for differ. versions).—<span class=\"citation\">B. Bath. 168ᵇ</span> <span dir=\"rtl\">א׳ בית וכ׳</span> mere Alef Beth (arbitrary words). <span class=\"citation\">Gen. R. s. 1</span> <span dir=\"rtl\">הא׳ קרא תגר</span> the Alef complained.—<span class=\"citation\">Y. Sabb. XVI, 15ᶜ</span> top <span dir=\"rtl\">א׳ בי&quot;ת אחד</span> one of the alphabetical acrostics (chapters) of Lamentations.—Pl. <span dir=\"rtl\">אלפ&quot;ין</span>. <span class=\"citation\">Sabb. 103ᵇ</span>. <span class=\"citation\">Ex. R. s. 38</span>; a. e.—<a href=\"#\" data-headword=\"אָאִין\">אָאִין</a>. Y. Ber. II, 4ᵈ bot. they pronounce <span dir=\"rtl\">עיינין א׳</span> Ayins like Alefs.—[<span class=\"citation\">Sabb. 103ᵇ</span> <span dir=\"rtl\">אלף אלף דאאזרך וכ׳</span> ed. (Ms. M. omits <span dir=\"rtl\">דאאזרך</span>) they differ as to one who wrote on the Sabbath two such letters as Alef, Alef (of <i>ăazzerkha</i> <span class=\"citation\">Is. XLV, 5</span>) being merely vowels; v. <a href=\"#\" data-headword=\"*בגלטורי\">בגלטורי</a>.]</div>","alt":[]},"1936":{"h":"אלפ\"א","r":"A01936","html":"<div class=\"sense\"><b>1)</b>  ch. <i>Alfa</i> = Alef. Cant. R. beg. the poet <span dir=\"rtl\">כד עביד א׳ בית&quot;א</span> when writing alphabetical acrostics. Lam. R. introd. (R. Ḥama b. Ḥ.) <span dir=\"rtl\">מן תלתא תלתא פסוקי בא׳ בית&quot;א</span> belonging to the alphab. acrostics (in Lamentations) of three verses for each letter.; a. fr.</div><div class=\"sense\"><b>—2)</b>  (ἄλφα) <i>Alpha</i>, the first letter of the Greek Alphabet. <span class=\"citation\">Shek. III, 2</span>. <span class=\"citation\">Men. VIII, 1</span> <span dir=\"rtl\">א׳ לסולת</span> best quality of flour. <span class=\"citation\">Ib. 6</span>.</div>","alt":[]},"1937":{"h":"אַלְפָא","r":"A01937","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֲלַף I\"><span dir=\"rtl\">אֲלַף</span> I</a></div>","alt":[]},"1938":{"h":"אִלְפָא","r":"A01938","html":"<div class=\"sense\"><i>ship</i>, v. <a href=\"#\" data-headword=\"אִילפָא I\">אִילְפָא</a>.</div>","alt":[]},"1939":{"h":"אַלְפַבֵּטָרִין","r":"A01939","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (ἀλφαβητάριον) <i>alphabetic acrostics, songs</i>. <span class=\"citation\">Ruth R. to III, 13</span> (ed. <a href=\"#\" data-headword=\"אלפבתרין\">אלפנטרין</a>, <a href=\"#\" data-headword=\"אלפבתרין\">אלפבתרין</a>, corr. acc.).</div>","alt":[]},"1940":{"h":"אַלֶּפְבֵּיתָא","r":"A01940","html":"<div class=\"sense\"> m., pl. <span dir=\"rtl\">אַלֶּפְבֵּיתִין</span> same. <span class=\"citation\">Koh. R. to I, 13</span>; v. <a href=\"#\" data-headword=\"אלפ\">אלפ&quot;א</a></div>","alt":[]},"1941":{"h":"אלפבתרין","r":"A01941","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַלְפַבֵּטָרִין\">אלפבטרין</a></div>","alt":["אלפנטרין"]},"1942":{"h":"אִלְפֵּס","r":"A01942","html":"<div class=\"sense\"> c. (= <a href=\"#\" data-headword=\"לֶפֶס\">לֶפֶס</a> q. v.) <i>a tightly covered pot, stew-pot</i>, contrad. to <span dir=\"rtl\">קדירה</span> a boiling pot. <span class=\"citation\">Ned. 51ᵃ</span> a dish goes first in a pot <span dir=\"rtl\">קודם שיורד לאי׳</span> before it is put in a stew-pot for steaming. <span class=\"citation\">Y. Ḥall. I, 58ᵃ</span> top.—<span class=\"citation\">Pes. 37ᵃ</span> מעשה אי׳ <i>stew</i>.—<span class=\"citation\">Gen. R. s. 1</span>, end <span dir=\"rtl\">כא׳ וכיסויו</span> as a pot with its lid.—Pl. <span dir=\"rtl\">אִלְפְּסִין</span>. <span class=\"citation\">Bets. 32ᵃ</span>, v. <a href=\"#\" data-headword=\"*אִירוֹנִית\">אִירוֹנִית</a>.</div>","alt":["אִילְפֵּס"]},"1943":{"h":"*אִלְצָרִין","r":"A01943","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (Syr. <span dir=\"rtl\">אלסרא</span> P. Sm. 155; 212; an abbrev. of <a href=\"#\" data-headword=\"אֲלַכְסִין\">אלכסנדרין</a>, v. <a href=\"#\" data-headword=\"אֲלַכְסִין\">אֲלַכְסִין</a>) <i>a species of pistachio</i> (tree or fruit). <span class=\"citation\">Y. Dem. II, beg. 22ᵇ</span>; Y. Maasr. I, 48ᵈ bot. <span dir=\"rtl\">אלצ׳</span>.—<span class=\"citation\">Tosef. ib. I, 1</span> <span dir=\"rtl\">אילס׳</span>. <span class=\"citation\">Ib. III, 14</span> <a href=\"#\" data-headword=\"אילאסרין\">אִילָאסָרִין</a> ed. Zuck. (Var. <span dir=\"rtl\">אלרסין</span>).</div>","alt":["אִלְסָרִין"]},"1944":{"h":"*אלקולאון","r":"A01944","html":"<div class=\"sense\"> <span class=\"citation\">Cant. R. to I, 11</span> <span dir=\"rtl\">שלמד א׳ בדעתו של הקב&quot;ה</span>, a corruption; read: <span dir=\"rtl\"><span dir=\"rtl\">שלמד אונקלס</span> (<a href=\"#\" data-headword=\"עֲקִילַס\">עקילס</a>) <span dir=\"rtl\">בן אחותו של הדריינוס</span></span>; cmp. Tanḥ. <span class=\"citation\">Mishp. 5</span>. [The entire clause seems to be a gloss.]</div>","alt":["אלקולאין"]},"1945":{"h":"*אַלְקוּם","r":"A01945","html":"<div class=\"sense\"> (b. h.) a symbolized pr. n.: <i>No-Standing</i>. <span class=\"citation\">Y. R. Hash. I, 57ᵃ</span> bot. <span dir=\"rtl\">ומלך א׳ עמו</span> but the King (the Lord)—no standing (on his decrees) is with him; he desires not to insist upon his decrees (but permits repentance to set them aside).</div>","alt":[]},"1946":{"h":"אלקט","r":"A01946","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִלְקְטִי\">next w.</a></div>","alt":["אילקט","אלקטו"]},"1947":{"h":"אִלְקְטִי","r":"A01947","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (ἑλικτή, sub. κλῖμαξ; v. also <a href=\"#\" data-headword=\"הִילְקְטִי\">הִילְקְטִי</a>) <i>winding staircase</i>. <span class=\"citation\">Tosef. Erub. VIII, 11</span> (<span class=\"citation\">V</span>, end) five compartments <span dir=\"rtl\">הפתוחות לא׳</span> ed. Zuck. (ed. <a href=\"#\" data-headword=\"אלקט\">אלקט</a>) opening towards a common winding staircase. Ib. <span dir=\"rtl\">ואסורין בהילקטי</span> ed. Zuck. (ed. <span dir=\"rtl\">באלקטון</span>, Var. <span dir=\"rtl\">בדיאלקטו</span></div>","alt":["אִילְ׳"]},"1948":{"h":"אִלְקָטִית","r":"A01948","html":"<p class=\"morphology\">f.</p><div class=\"sense\">, pl. <span dir=\"rtl\">אִלְקְטִיֹּות</span> (<span dir=\"rtl\">לקט</span>, v. <a href=\"#\" data-headword=\"הֶילְקֵט\">הֶילְקֵט</a>) <i>stack of grain, shed for stacks</i> in the field. [Comment. fr. <a href=\"#\" data-headword=\"קַיָּיט\">קייט</a> summer.] <span class=\"citation\">Maasr. III, 7</span> the stores in <span dir=\"rtl\">הבורגנין והא׳</span> (Ms. M. <span dir=\"rtl\">אלנקטיות</span>) turrets and sheds in the field are exempt from tithes (until brought home).</div>","alt":[]},"1949":{"h":"אֱלָקָא","r":"A01949","html":"<div class=\"sense\"> = <a href=\"#\" data-headword=\"אֱלָהּ\">אֱלָהָא</a>, <a href=\"#\" data-headword=\"אֱלֹהִים\">אֱלֹהִים</a>, v. <span dir=\"rtl\">אֱלוֹהַּ</span></div>","alt":["אֱלֹקִים"]},"1950":{"h":"אלקים","r":"A01950","html":"<div class=\"sense\"> <span class=\"citation\">Pesik. R. s. 21</span>, ed. Fr. p. 108ᵃ, read <span dir=\"rtl\">ולוּקְיוֹס</span>, v. <a href=\"#\" data-headword=\"גַּיּיוּס\">גַּייוּס</a></div>","alt":[]},"1951":{"h":"אַלְקַפְטָא","r":"A01951","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (ἀργαπέτης, <span dir=\"rtl\">ארגבטא</span>, Palm. inscript., Zeitschr. der Deutsch. Morgenl. Ges. XVIII, 89—90; Syr. <span dir=\"rtl\">ארזבד</span>, Pers. arzabedes; v. Perl. Et. St. p. 105) <i>Arkafta</i>, a high dignitary in Persia. <span class=\"citation\">Targ. Y. Gen. XLI, 44</span> (ed. Vienna <span dir=\"rtl\">אַלְקַפֶּטַע</span>); a. e.—<span class=\"citation\">Shebu. 6ᵇ</span> <span dir=\"rtl\">אלקפ׳</span>. Y. ib. I, 32ᵈ bot. <span dir=\"rtl\">ארקב׳</span>. Y. Ber. II, 5ᵃ top Ar. (ed. <span dir=\"rtl\">בסא …</span>, corr. acc.).—<span class=\"citation\">Zeb. 96ᵇ</span> (prov.) <span dir=\"rtl\">ארקפת׳ נקטן ביד ריח׳ אתי ליה ליד</span> Ms. M. (ed. <span dir=\"rtl\">אלקפתא נקטן ריחא …</span>) the Ark. took <i>us</i> by the hand, and the scent came into the hand (undue pride of accidental acquaintances.</div>","alt":["אַרְקַפְטָא","אַרְקַבְטָא"]},"1952":{"h":"אלקפרין","r":"A01952","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַקְלִפְרִין\">אַקְלַפְרִין</a></div>","alt":[]},"1953":{"h":"אַלְקַפְתָּא","r":"A01953","html":"<div class=\"sense\"> = <a href=\"#\" data-headword=\"אַלְקַפְטָא\">אַלְקַפְטָא</a>.</div>","alt":[]},"1954":{"h":"אִלַּרְיָא","r":"A01954","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (ἱλάρια) <i>day of rejoicing</i>, both private and public; esp. <i>days of public rejoicings appointed by a new emperor, consisting of games, masquerades</i> &amp;c. Pesik. Sh’mini p. 193ᵇ while the King is engaged <span dir=\"rtl\">בא׳ שלו וכ׳</span> in his hilaria, ask of him what you need. <span class=\"citation\">Cant. R. to IV, 4</span> <span dir=\"rtl\">לא היו עומדין באלירא וכ׳</span></div>","alt":["אִילַ׳"]},"1955":{"h":"*אלריא","r":"A01955","html":"<div class=\"sense\"><i>a disease;</i> prob. a corruption of <a href=\"#\" data-headword=\"אִילְיָא\">אִילְיָיא</a> (εἰλεός, ileus) <i>iliac passion, spasm of the abdominal muscles connected with vomiting</i>. <span class=\"citation\">Git. 70ᵃ</span> מיושב אחזתו א׳ Ar. (ed. <a href=\"#\" data-headword=\"דלריא\">דלריא</a> as in the sentence following).</div>","alt":[]},"1956":{"h":"אַלָּתָא","r":"A01956","html":"<p class=\"morphology\">f.</p><div class=\"sense\">(= h. <a href=\"#\" data-headword=\"אַלָּה\">אַלָּה</a>) <i>post, pole, door-post</i>. <span class=\"citation\">Targ. Josh. XXIV, 26</span> (ed. Vien. I <a href=\"#\" data-headword=\"אִילַן\">אילנא</a>).—Pl. (of <span dir=\"rtl\">אלותא</span>) <a href=\"#\" data-headword=\"אַלְוָותָא\">אַלְוָותָא</a>. <span class=\"citation\">Targ. Is. VI, 4</span> <a href=\"#\" data-headword=\"אַלְוַאי\">אַלְוַות</a> (ed. Vien. <span dir=\"rtl\">אֵילָוַות</span>.) <span class=\"citation\">B. Bath. 73ᵃ</span> ומחינן ליה באלוותא Rashi (ed., sing. <span dir=\"rtl\">אלותא</span>) and we struck it with clubs; v., however, <a href=\"#\" data-headword=\"*אִלִּיתָא\">אִלִּיתָא</a>. <span class=\"citation\">Bets. 33ᵇ</span> <span dir=\"rtl\">ויהיב לן א׳ א׳</span> and gave us each several branches (Rashi), v., however, <a href=\"#\" data-headword=\"אַלְוָתָא\">אַלְוָתָא</a>.</div>","alt":["אֲלָתָא","(אַלּוּתָא)"]},"1957":{"h":"אַלְתּוּסְבְּרָאוֹת","r":"A01957","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אַל\">אַל</a> = <a href=\"#\" data-headword=\"עַל\">עַל</a>, a. <a href=\"#\" data-headword=\"תִּסְבָּרָא\">תוס׳</a>, v. <a href=\"#\" data-headword=\"תּוּסְבָּרָא\">תּוּסְבְּרָא</a>; cmp. <span class=\"citation\">I Chron. XXVII, 25</span>); v. <a href=\"#\" data-headword=\"אַל־\">אַל־</a>) <i>comes thesaurorum, chief-treasurer</i>. <span class=\"citation\">Midr. Till. to Ps. XV</span> <i>magor</i> (his resort, stores) that is <span dir=\"rtl\">א׳ שלו</span> his (the Roman Emperor’s) chief treasurer (or plur. treasurers).</div>","alt":[]},"1958":{"h":"אִלְתִּית","r":"A01958","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>Iltith</i>, name of a large fish (prob. from its place, v. <a href=\"#\" data-headword=\"חוּלְתָּא\">חוּלְתָּא</a>). <span class=\"citation\">Makhsh. VI, 3</span> (Mish. ed. <span dir=\"rtl\">אלתות</span>). <span class=\"citation\">Tosef. Kel. B. Mets. V, 7</span>.</div>","alt":[]},"1959":{"h":"אַלְתַּר","r":"A01959","html":"<div class=\"sense\"> (= <span dir=\"rtl\">עַל־אֲתַר</span>) <i>on the spot, forthwith</i>, always with <a href=\"#\" data-headword=\"לְ־\">לְ־</a>. <span class=\"citation\">Gitt. III, 3</span> (Mish. Talm. Y. <span dir=\"rtl\">על אתר</span>). <span class=\"citation\">R. Hash. 6ᵃ</span>; a. v. fr. (in Hebr. phraseol.).</div>","alt":[]},"1960":{"h":"אִם","r":"A01960","html":"<div class=\"sense\"><b>1)</b> <i>if, when</i>. Mekh. Yithro, end <span dir=\"rtl\">כל א׳ שבתורה רשות</span> every <i>Im</i> (If) in the Torah refers to voluntary actions (which you may or may not do) except three &amp;c. <span class=\"citation\">Y. Gitt. VII, 48ᵈ</span> <span dir=\"rtl\">בגין דאמר א׳</span> because he said, <i>If</i> (I die), i.e. conditional divorce. <span class=\"citation\">Succ. 53ᵃ</span> <span dir=\"rtl\">א׳ אני כאן</span> when I am here; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>whether.</i> <span class=\"citation\">Yoma III, 1</span>; a. fr.—א׳ … א׳ <i>whether … or</i>. <span class=\"citation\">Y. Pes. VI, beg. 33ᵃ</span> <span dir=\"rtl\">א׳ פסח וכ׳</span> whether or not the Passover ceremonies supersede the Sabbath; a. fr. [Ib. <span dir=\"rtl\">אם יש תוחלת</span> read <span dir=\"rtl\">יש וכ׳ אפשר</span>, as before.]—<span dir=\"rtl\">אִם כֵּן</span> (abbrev. <span dir=\"rtl\">א&quot;כ</span>) <i>if this be so</i>. <span class=\"citation\">Ber. I, 1</span>; a. fr.—<span dir=\"rtl\">אֶלָּא אִם כֵּן</span> (abbr. <span dir=\"rtl\">אא&quot;כ</span>) <i>only when indeed, not until, unless</i>. <span class=\"citation\">Keth. 76ᵃ</span>; a. fr.</div>","alt":[]},"1961":{"h":"אֵם","r":"A01961","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b> <i>mother</i>, freq. = <i>my mother</i>. <span class=\"citation\">Sabb. 134ᵃ</span>; a. fr.—Y. M. Kat. III, beg. 81ᶜ <span dir=\"rtl\">הניח חק אִמֹּו</span> left his mother’s lap (Palestine).—<span class=\"citation\">Num. R. s. 10</span> (ref. to <i>immo</i> <span class=\"citation\">Prov. XXXI, 1</span>) <span dir=\"rtl\">אמו זו … התורה וכ׳</span> ‘his mother’ that means the Law which trained Solomon and which is called a mother of those studying it, as you read (<span class=\"citation\">Prov. II, 3</span>; text <a href=\"#\" data-headword=\"אִם\">אִם</a> is read <a href=\"#\" data-headword=\"אֵם\">אֵם</a> <i>ēm</i>).</div><div class=\"sense\"><b>—2)</b> <i>womb, mouth of the womb</i>. <span class=\"citation\">Ḥull. III, 2</span> (<span class=\"citation\">54ᵃ</span>) <span dir=\"rtl\">ניטלה האם וכ׳</span> if the mouth of the womb is absent, cut out. <span class=\"citation\">Bekh. IV, 4</span> (<span class=\"citation\">28ᵇ</span>).—Trnsf. <i>legitimate existence, authority</i>. <span class=\"citation\">Succ. 6ᵇ</span>, a. fr. <span dir=\"rtl\">יש א׳ למסורת</span> the traditional Scripture text (letters without vowels) is authoritative in Biblical interpretation, opp. <span dir=\"rtl\">יש א׳ למקרא</span> the traditional reading (vowels) must guide us, e.g. <span dir=\"rtl\">בחלב</span> (<span class=\"citation\">Ex. XXIII, 19</span>) may be read <span dir=\"rtl\">בַּחֲלֵב</span> as the traditional vocalization, or <span dir=\"rtl\">בְּחֵלֶב</span> <i>in the fat of.—</i> Pl. <a href=\"#\" data-headword=\"אַמְהוּת\">אִמָּהוֹת</a>, <a href=\"#\" data-headword=\"אִימָּהוֹת\">אִימָּהוֹת</a>. <span class=\"citation\">Kidd. IV, 4</span> her genealogy must be traced back <span dir=\"rtl\">ארבע א׳</span> to the mothers of four generations (on each side) which is eight mothers. <span class=\"citation\">Y. Snh. II, 20ᵇ</span> bot. they are not <span dir=\"rtl\">אֲמָהוֹת אלא אִימָּהוֹת</span> maid-servants but mothers (of the nation).—Trnsf. <span dir=\"rtl\">א׳ של בצלים</span> <i>seed-onions.</i> <span class=\"citation\">Peah III, 4</span>. <span class=\"citation\">Erub. 29ᵃ</span>; a. e.—Ch. <a href=\"#\" data-headword=\"אֵימָא\">אִימָּא</a>. [<span class=\"citation\">Koh. R. to XII, 7</span> <span dir=\"rtl\">א׳ דבצלי׳</span>, v. <a href=\"#\" data-headword=\"אַמָּה\">אַמָּה</a>.]</div>","alt":[]},"1962":{"h":"אִמָּא","r":"A01962","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֵימָא\">אִימָּא</a></div>","alt":[]},"1963":{"h":"אַמָּא","r":"A01963","html":"<div class=\"sense\"><i>cubit</i>, v. <a href=\"#\" data-headword=\"אַמְּתָא\">אַמְּתָא</a>.</div>","alt":[]},"1964":{"h":"אְמָא I","r":"A01964","html":"<div class=\"sense\"> f. = h. <a href=\"#\" data-headword=\"אָמָה\">אָמָה</a>. <span class=\"citation\">Targ. O. Deut. XXIII, 18</span>; v. <a href=\"#\" data-headword=\"אַמְהָא\">אַמְהָא</a></div>","alt":["אָמָא"]},"1965":{"h":"אֲמָא II","r":"A01965","html":"<div class=\"sense\">, fut. <span dir=\"rtl\">יֵימָא</span>, imper. <a href=\"#\" data-headword=\"אֵימָא\">אֵימָא</a> (√אם <i>to join</i>, v. <a href=\"#\" data-headword=\"אָמַר I\">אמר</a>) <i>to say, speak, think</i>. <span class=\"citation\">Targ. Y. Gen. XXXIII, 10</span>.—Freq. in Talmud.—<span dir=\"rtl\">אפילו תימא</span> even if you will say, i.e. it may come right even if you assume that &amp;c. <span class=\"citation\">Succ. 13ᵇ</span>; a. fr.—<span dir=\"rtl\">מי לֵימָא</span>, (<a href=\"#\" data-headword=\"מִי I\">מי</a>)<a href=\"#\" data-headword=\"נֵימָא\">נֵימָא</a>, or <a href=\"#\" data-headword=\"לֵימָא\">לימא</a> must it be said, <i>does it mean to say?</i> Ib.; a. fr.—<span dir=\"rtl\">(<a href=\"#\" data-headword=\"וַאי\">ואי</a>) <span dir=\"rtl\">וכי תימא</span></span> and if you should object. Ib.; a. fr.—<span dir=\"rtl\">אלא אימא</span> but rather say, i.e. the correct version is. Ib.; a. fr.—<span dir=\"rtl\">אימא סיפא</span> now read the second clause, i.e. how will you understand &amp;c.? <span class=\"citation\">Ber. 21ᵇ</span>; a. fr.—אֵימָא I might think. Ib.; a. fr.—הוה אמינא I might have thought, I might have been led to believe. <span class=\"citation\">Erub. 74ᵇ</span> <span dir=\"rtl\">מאי הוה א׳</span> what might I have been led to believe?; a. fr.—<span dir=\"rtl\">נימא כוותיה</span> let him express his opinion in agreement with his authority, i.e. why does he not say so expressly? <span class=\"citation\">Taan. 3ᵃ</span>; a. fr.—<span class=\"citation\">Pes. 7ᵇ</span> <span dir=\"rtl\">היכי נימא</span> what else should he say? <span dir=\"rtl\">נימא למול</span> should he use the expression <i>lamol?</i>—<span class=\"citation\">Gitt. 47ᵇ</span>, a. fr. <span dir=\"rtl\">ס&quot;ד אמינא</span> it may occur to you to think; v. <a href=\"#\" data-headword=\"דַּעְתָּא\">דַּעְתָּא</a>. <span class=\"citation\">Yoma 85ᵇ</span> <span dir=\"rtl\">אי הואי התם הוה אמינא</span> had I been there, I should have said.—<span dir=\"rtl\">קאמינא</span> = <span dir=\"rtl\">קא אמינא</span> I say, speak of, v. <a href=\"#\" data-headword=\"קָא\">קָא</a>. <span class=\"citation\">Gitt. 47ᵇ</span>; a. fr.</div>","alt":["אֲמִי"]},"1966":{"h":"אִמָּאוּס","r":"A01966","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"> (Ἐμμαούς, Ἀμμαούς, hellenized form of <span dir=\"rtl\">חמה</span>, <a href=\"#\" data-headword=\"חַמְּתָא\">חמתה</a>) <i>Emmaus, Ammaus</i>, a town in the plain of Judæa (or Philistæa), renowned, in Talmudic days, for its warm springs and luxurious life. <span class=\"citation\">Koh. R. to VII, 7</span>, a. e. [<span class=\"citation\">Ib. 11</span> <span dir=\"rtl\">אימוניס</span> prob. <span dir=\"rtl\">אימאוס</span>.] Cmp. <a href=\"#\" data-headword=\"דִּימְסִית\">דימסית</a>. [Other forms: <a href=\"#\" data-headword=\"עִמְאוּם\">עמאוס</a>, <span dir=\"rtl\">עמיס</span>, <span dir=\"rtl\">אמאום</span>, <span dir=\"rtl\">עמאים</span>. For other places by that name, v. Neub. Géogr. p. 100.]</div>","alt":["אִימָּאוּס"]},"1967":{"h":"אַמַּאי","r":"A01967","html":"<div class=\"sense\"> (= <span dir=\"rtl\">עַל מַאי</span> = <a href=\"#\" data-headword=\"אַלָּמָּא\">אַלָּמָּה</a>) <i>wherefore? why?</i> א׳ לא <i>why not?</i> <span class=\"citation\">Sabb. 48ᵃ</span>. <span class=\"citation\">Erub. 70ᵃ</span>; a. v. fr.</div>","alt":[]},"1968":{"h":"אַמַּאן","r":"A01968","html":"<div class=\"sense\"> (= <span dir=\"rtl\">עַל מַאן</span>) <i>to whom?</i>, v. <a href=\"#\" data-headword=\"אַ־\">אַ־</a> and <a href=\"#\" data-headword=\"מַאן\">מַאן</a>.</div>","alt":[]},"1969":{"h":"אַמְבּוּהָ","r":"A01969","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (Pers. anbûh, Perl. Et. St. p. 18; cmp., however, <span dir=\"rtl\">מבוא עם</span> Ezek. <span class=\"citation\">Ezek. XXXIII, 31</span>) <i>crowd, escort</i>. <span class=\"citation\">Yoma 87ᵃ</span>; <span class=\"citation\">Snh. 7ᵇ</span>. <span class=\"citation\">Succ. 55ᵃ</span></div>","alt":["אַמְבּוּהָא"]},"1970":{"h":"אִמְבֹּול","r":"A01970","html":"<p class=\"morphology\">m.</p><div class=\"sense\">, pl. <span dir=\"rtl\">אִמְבֹּולִין</span> (= <a href=\"#\" data-headword=\"עִינְבּוֹל\">עִינְבֹּול</a>; <span dir=\"rtl\">ענב</span>) <i>little grape</i>, i.e. <i>clapper</i> in the bell. <span class=\"citation\">Y. Sabb. VI, beg. 7ᵈ</span> <span dir=\"rtl\">עשה להן אמבולי</span> (corr. acc.) he put clappers in. V. <a href=\"#\" data-headword=\"אִנְבֹּול\">אִנְבֹּול</a>.</div>","alt":[]},"1971":{"h":"*אמבוניא","r":"A01971","html":"<div class=\"sense\">, <span class=\"citation\">Lev. R. s. 5</span> על א׳ דסדום Ar. (ed. by cler. error <span dir=\"rtl\">אילנייא</span>) read <span dir=\"rtl\">אַמְבְּטַיָּא</span> <i>towers, battlements</i>; v. <a href=\"#\" data-headword=\"אַנְבְּטַי\">אַנְבְּטַי</a>.</div>","alt":[]},"1972":{"h":"אִמְבּוּרְקְלוֹן","r":"A01972","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (ἐμβούρικλον, imburuclum, corrupt. of involucrum, D. C. s. v.) <i>wrapper, cover, bundle</i>. <span class=\"citation\">Y. B. Mets. IV, beg. 9ᶜ</span> המחליף א … ין בא׳ Ar. (read … <span dir=\"rtl\">ון</span>; ed. <span dir=\"rtl\">אברוקלון באמבירוקלון</span>, corr. acc.) if one exchanges one bundle for another; cmp. <a href=\"#\" data-headword=\"צִיבּוּר\">ציבור</a> ibid.—Pl. <a href=\"#\" data-headword=\"אִנְבּוּרְקְרָאוֹת\">אִנְבּוּרְקְרָאוֹת</a>. <span class=\"citation\">B. Kam. 114ᵇ</span> ed. (Ar. <a href=\"#\" data-headword=\"אנבקראות\">אנבקראות</a>, Ms. M. <span dir=\"rtl\">אגבו׳</span>, v. Rabb. D. S. a. l. note).</div>","alt":["אִמְבּוּרִיקְלוֹן","אִנְבּוּרְקְרָא"]},"1973":{"h":"אַמְבְּטָה","r":"A01973","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"אַמְבְּטִי\">next w.</a>) <i>bottom</i>. <span class=\"citation\">Gen. R. s. 68</span>, v. <a href=\"#\" data-headword=\"דְּיֵיטָא\">דְּיִיטֵי</a>.</div>","alt":["אַמְבְּטִי"]},"1974":{"h":"אַמְבְּטִי","r":"A01974","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (√<span dir=\"rtl\">בט</span>, v. <a href=\"#\" data-headword=\"*אַבְטָא\">אַבְטָא</a>; <a href=\"#\" data-headword=\"מ\">מ</a> inserted) <i>bath-tub, bathing reservoir</i>. <span class=\"citation\">Ned. IV, 4</span> (Var. <span dir=\"rtl\">טיא …</span>). <span class=\"citation\">Ḥag. 15ᵃ</span> אב׳ Ar. (ed. <span dir=\"rtl\">אמב׳</span>); a. fr.—Pl. <span dir=\"rtl\">אִמְבְּטִיֹּות</span>, <span dir=\"rtl\"><span dir=\"rtl\">אַמְבְּטָאוֹת</span> (אמבטיאות</span>). <span class=\"citation\">Y. Sabb. III, 6ᵃ</span>.—Bab. <span class=\"citation\">ib. 40ᵃ</span> <span dir=\"rtl\">אמבטי׳</span> (Ar. <span dir=\"rtl\">אבטאות</span>); Tosef. ib. III (IV), 3 ed. Zuck. <span dir=\"rtl\">אבטאות</span> (Var. <span dir=\"rtl\">אמבטאות</span>) baths in large cities with ambulatories (v. Sm. Ant. s. v. <i>Baths</i>). [<span class=\"citation\">Y. Pes. III, beg. 29ᵈ</span> <span dir=\"rtl\">א׳ של בצק</span> (?), prob. a corruption.] Cmp. <a href=\"#\" data-headword=\"בְּטַח II\"><span dir=\"rtl\">בְּטַח</span> II</a>.</div>","alt":["אַבְּטִי"]},"1975":{"h":"*אַמְבָּטֵיס","r":"A01975","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (ἀναβάτης, contr. ἀμβάτης) prop. <i>rider, traveller</i> on horseback &amp;c.; hence (sub. <span dir=\"rtl\">חמור</span>) <i>an ass used for marching</i> through the desert alongside of (and sometimes tied to) the camel. <span class=\"citation\">Y. Sabb. V, 7ᵇ</span> top <span dir=\"rtl\">מהו א׳</span> what is an <i>ambates?</i> <span dir=\"rtl\">חמר סלק</span> the ass of the traveller (from Egypt to Asia). Y. Kel. VIII, 31ᶜ <a href=\"#\" data-headword=\"אבהנוס\">אבהנוס</a>, <a href=\"#\" data-headword=\"אבחטס\">אבחטס</a> (corr. acc.). V. <a href=\"#\" data-headword=\"לִיבְדְּקוֹס\">לִיבְדְּקוֹס</a>.</div>","alt":[]},"1976":{"h":"אַמְבְּטִיתָא","r":"A01976","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (deriv. of <span dir=\"rtl\">אמבטי</span>) <i>water of the bath-tub, waste of the bath-tub</i>. <span class=\"citation\">Y. Sabb. VIII, 11ᶜ</span> <span dir=\"rtl\"><span dir=\"rtl\">ההן דמשזג</span> (<span dir=\"rtl\">גו</span>) <span dir=\"rtl\">א׳ וכ׳</span></span> he who washes (his anus) in &amp;c., is liable to a disease of the rectum.</div>","alt":[]},"1977":{"h":"*אמבירוס","r":"A01977","html":"<div class=\"sense\">, read <span dir=\"rtl\">אֶמְפִּירוֹס</span> m. (ἔμπυρος) <i>fire-scathed</i>. <span class=\"citation\">Midr. Till. to Ps. XXII</span>, v. <a href=\"#\" data-headword=\"*אִימּוּס\">אִימּוּס</a>.</div>","alt":[]},"1978":{"h":"אִמְבְּרָא","r":"A01978","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"עִבּוּר\">עִבּוּרָא</a>; <a href=\"#\" data-headword=\"מ׳\">מ׳</a> inserted) <i>crop, store</i>. <span class=\"citation\">Keth. 105ᵃ</span> smelt at (was an expert of) <span dir=\"rtl\">א׳ דחמרא</span> (Rashi, pl.) wine stores.—Pl. <span dir=\"rtl\">אִמְבְּרֵי</span>. <span class=\"citation\">Gitt. 56ᵃ</span> <span dir=\"rtl\">קלנהו להנהו א׳ וכ׳</span> set fire to all those stores of wheat and barley.</div>","alt":[]},"1979":{"h":"אֶמְגּוּזָא","r":"A01979","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (= <a href=\"#\" data-headword=\"אֱגוּזָא\">אגוזא</a>, v. <a href=\"#\" data-headword=\"אִמְבְּרָא\">foreg.</a>) <i>nut</i>. <span class=\"citation\">Sabb. 109ᵇ</span> <span dir=\"rtl\">מא׳ אליבא וכ׳</span> from eating a nut on an empty stomach. <span class=\"citation\">Men. 35ᵃ</span> <span dir=\"rtl\">כי א׳</span> in the shape of a nut; a. e.—Pl. <a href=\"#\" data-headword=\"אֶמְגּוּזָא\">אֶמְגּוּזֵי</a>. <span class=\"citation\">Ḥull. 59ᵃ</span>. <span class=\"citation\">B. Mets. 60ᵃ</span></div>","alt":[]},"1980":{"h":"אַמְגֹּושָׁא","r":"A01980","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>magus, magian</i>, a Persian priest and interpreter of dreams; <i>magician, sorcerer</i>. <span class=\"citation\">Targ. Y. I Ex. VII, 15</span>; <span class=\"citation\">VIII, 16</span>.—B. Beth. 58ᵃ. <span class=\"citation\">Yoma 35ᵃ</span> (<span class=\"citation\">Ḥull. 62ᵇ</span>) <span dir=\"rtl\">פרוה א׳</span> Parvah is the name of a Persian magus after whom the cell in the Temple was named.—<span class=\"citation\">Sabb. 75ᵃ</span> א׳ רב ושמואל Var. (read <a href=\"#\" data-headword=\"אַמְגּוּשְׁתָּא\">אַמְגּוּשְׁתָּא</a>).—Pl. <a href=\"#\" data-headword=\"אַמְגּוּשִׁי\">אַמְגֹּושֵׁי</a>. <span class=\"citation\">Snh. 98ᵃ</span> <span dir=\"rtl\">אי בטלי יהירי בטלי א׳</span> when (in Israel) the haughty shall cease to exist, the magians (among the Persians) shall cease.</div>","alt":[]},"1981":{"h":"אַמְגּוּשִׁי","r":"A01981","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"אַמְגֹּושָׁא\">preced.</a>) <i>a follower of magianism, believer in sorcery</i>. <span class=\"citation\">M. Kat. 18ᵃ</span></div>","alt":[]},"1982":{"h":"אַמְגּוּשְׁתָּא","r":"A01982","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (deriv. of <a href=\"#\" data-headword=\"אַמְגּוּשִׁי\">preced. ws.</a>) <i>magianism, magian practices</i>. <span class=\"citation\">Sabb. 75ᵃ</span> א׳ רב ושמואל Ms. M. (ed. <a href=\"#\" data-headword=\"מָגוּשְׁתָּא\">מגושתא</a>, Var. <a href=\"#\" data-headword=\"אַמְגֹּושָׁא\">אמגושא</a>) as to magianism Rab and Samuel differ, one declaring it to be sorcery, the other—blasphemy.</div>","alt":[]},"1983":{"h":"*אַמְּגַיַּירְתֵּיה","r":"A01983","html":"<div class=\"sense\"><i>referring to</i> (<i>the blood</i>) <i>which made him a proselyte</i> (circumcision). <span class=\"citation\">Y. Ab. Zar. II, 41ᵃ</span> top <span dir=\"rtl\">ולא הוון אלא א׳</span> his visions as to bloodshed had reference only to that (blood) which made him &amp;c.; v. <a href=\"#\" data-headword=\"גּוּר\">גּוּר</a>.</div>","alt":[]},"1984":{"h":"אָמַד","r":"A01984","html":"<div class=\"sense\"> (√<a href=\"#\" data-headword=\"מִדְּ־\">מד</a>; v. <a href=\"#\" data-headword=\"מָדַד\">מָדַד</a>) <i>to form an approximate estimate, to guess; to appraise, judge, deliver an expert’s opinion</i>. <span class=\"citation\">Erub. 58ᵇ</span> <span dir=\"rtl\">אוֹמְדוֹ וכ׳</span> he forms an approximate estimate of the height of the hill, and passes on. <span class=\"citation\">Snh. 78ᵇ</span> <span dir=\"rtl\">אֲמָדוּהוּ למיתה</span> they (the experts) declared his injuries to be fatal; (Y. ib. IX, 27ᵃ bot., also <span dir=\"rtl\">עמד׳</span>) <span dir=\"rtl\">א׳ לחיים</span> the opinion was that he would recover; a. fr.—<span class=\"citation\">Ḥull. 51ᵃ</span> <span dir=\"rtl\">אמדה נפשה</span> the animal before taking a leap measures its strength.</div><div class=\"sense\"><b>Hif. הֶאֱמִיד</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"*אַמְּגַיַּירְתֵּיה\">same</a>. <span class=\"citation\">Gen. R. s. 64</span> <span dir=\"rtl\">שהאמידו אותה</span> they had appraised it (the field,—as to how much it would yield). V. <a href=\"#\" data-headword=\"אוּמָד\">אוּמָד</a></div></div>","alt":[]},"1985":{"h":"אֲמַד","r":"A01985","html":"<div class=\"sense\"> <span class=\"citation\">Bekh. 61ᵃ</span> להכי אמדתיך I guessed this was thy intention. <span class=\"citation\">Keth. 68ᵃ</span> <span dir=\"rtl\">הא דאמידניה</span> in the one case it means that we have formed an opinion about him (know whether he is stingy or liberal).—<i>Part. pass</i>. <span dir=\"rtl\">אָמִיד</span>. <span class=\"citation\">Arakh. 20ᵃ</span> <span dir=\"rtl\">הא א׳ וקאי</span> he stands appraised, he has been valued before this.—Hence <span dir=\"rtl\">אָמִיד</span> <i>believed to be wealthy</i>. <span class=\"citation\">B. Kam. 62ᵃ</span> <span dir=\"rtl\">איניש א׳</span>. <span class=\"citation\">Keth. 85ᵇ</span> ידענא ביה דלא א׳ I know he is not rich. <span class=\"citation\">B. Bath. 8ᵇ</span>.—<span class=\"citation\">Ib. 52ᵃ</span> <span dir=\"rtl\">אם אֲמִידָא לך</span> if you believe her to be wealthy. V. <a href=\"#\" data-headword=\"אוּמְדָּנָא\">אוּמְדָּנָא</a>.</div>","alt":[]},"1986":{"h":"*אַמַּדְלָא","r":"A01986","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (= <span dir=\"rtl\">על מדלא</span>, <span dir=\"rtl\">על מיד׳</span>; <a href=\"#\" data-headword=\"דלי\">דלי</a>; cmp. <a href=\"#\" data-headword=\"דָּלִית\">דָּלִית</a>) <i>watchman’s lodge on top of trees</i>. <span class=\"citation\">Sabb. 155ᵃ</span> דרגא דא׳ Ar., Ms. M. (ed. <span dir=\"rtl\">דמַדְלָא</span>) ladder for climbing up to the lodge.</div>","alt":["אַמִּידְלָא"]},"1987":{"h":"אמדלאי","r":"A01987","html":"<div class=\"sense\"> a word in a charm formula. <span class=\"citation\">Sabb. 67ᵃ</span> Ms. M. a. Ar. (ed. <a href=\"#\" data-headword=\"אמרלאי\">אמרלאי</a>).</div>","alt":[]},"1988":{"h":"*אִמִּדָּרוֹמָה","r":"A01988","html":"<div class=\"sense\"> = <span dir=\"rtl\">אִי מִדָּ׳</span> <i>or from Daromah</i>. <span class=\"citation\">Y. Hor. III, end, 48ᶜ</span></div>","alt":[]},"1989":{"h":"אַמָּה","r":"A01989","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> , v. <a href=\"#\" data-headword=\"אֵם\">אֵם</a>) </div><div class=\"sense\"><b>1)</b> <i>fore-arm, arm</i>. <span class=\"citation\">Sot. 12ᵇ</span>; <span class=\"citation\">Ex. R. s. 1</span> <span dir=\"rtl\">אמתה חד אמר ידה</span> the word <span dir=\"rtl\">אמתה</span> (<span class=\"citation\">Ex. II, 5</span>)—one says it means <span dir=\"rtl\">אַמָּתָהּ</span>, her arm, the other says it means <span dir=\"rtl\">אֲמָתָהּ</span>, her maid-servant (v. <a href=\"#\" data-headword=\"אָמָה\">אָמָה</a>).—Lam. R. introd. (R. <span class=\"citation\">Josh. 2</span>) <span dir=\"rtl\">א׳ דבצלי׳</span> an arm (direction-post) &amp;c.; v. <a href=\"#\" data-headword=\"בְּצַל\">בְּצַל</a>; <span class=\"citation\">Koh. R. to XII, 7</span> <span dir=\"rtl\">אם</span>.—<span dir=\"rtl\"><a href=\"#\" data-headword=\"אֱמֶת\">אַמַּת</a> (<span dir=\"rtl\">בית</span>) <span dir=\"rtl\">השחי</span></span> the arm up to the axilla, <i>arm-pit</i>, name of an opening in a Temple door; v. however, infra. 4).—2) <i>cubit</i>, a measure equal to the distance from the elbow to the tip of the middle-finger. <span class=\"citation\">Keth. 5ᵇ</span>; <span class=\"citation\">Men. 11ᵃ</span> <span dir=\"rtl\">זו א׳</span> this one (the middle-finger) is used for defining the cubit measure. <span class=\"citation\">Kel. XVII, 10</span> <span dir=\"rtl\">אַמַּת הבנין וכ׳</span> the standard cubit of the Temple proportions was six, that of the vessels five hand-breadths. <span class=\"citation\">Sabb. 31ᵃ</span> <span dir=\"rtl\">א׳ הבנין</span> the builder’s cubit (instrument).—<span dir=\"rtl\">א׳ על א׳</span> square-cubit. <span class=\"citation\">Yoma 31ᵃ</span>; a. e.—<span class=\"citation\">Zeb. 62ᵇ</span> <span dir=\"rtl\">(<a href=\"#\" data-headword=\"גָּרוּם\">גרומה</a>) <span dir=\"rtl\">א׳ גדומה</span></span>; <span class=\"citation\">Y. Yoma IV, 41ᶜ</span> bot. <span dir=\"rtl\">גמודה</span> a reduced cubit; v. <a href=\"#\" data-headword=\"גָּדַם\">גָּדַם</a>; also called <span dir=\"rtl\">א׳ בת ששה עצבות</span> a cubit of six hand-breadths pressed together (sorrowing), opp. to <span dir=\"rtl\"><a href=\"#\" data-headword=\"א׳\">א׳</a> (<span dir=\"rtl\">בת ששה</span>) <span dir=\"rtl\">שוחקות</span></span> a cubit of six wide-spread (laughing) hand-breadths. <span class=\"citation\">Erub. 3ᵇ</span>. <span class=\"citation\">Y. Shek. VI, end, 50ᵇ</span>.—<span class=\"citation\">Gen. R. s. 31</span> (<a href=\"#\" data-headword=\"א׳\">א׳</a>) <a href=\"#\" data-headword=\"*תְּבִיקִין\">תביקין</a> Theban (Egypt.) cubit(?). <span class=\"citation\">B. Bath. 99ᵇ</span> <span dir=\"rtl\">אמה בית השלחין</span> land for digging a dyke of one cubit’s width; <span dir=\"rtl\">א׳ בית הקילון</span> (Var. <a href=\"#\" data-headword=\"קַלּוֹן\">קלון</a>, <a href=\"#\" data-headword=\"סִילּוֹן I\">סילון</a>) land for a creek or pond for watering cattle and washing clothes, of one cubit’s width.</div><div class=\"sense\"><b>—3)</b>  (= <span dir=\"rtl\">אצבע</span>) <i>membrum virile</i>. <span class=\"citation\">Sabb. 108ᵇ</span>. <span class=\"citation\">Nidd. 13ᵃ</span> sq. <span class=\"citation\">B. Kam. 19ᵇ</span></div><div class=\"sense\"><b>—4)</b>  prop. <i>river-arm</i>, hence <i>canal, dyke, sewer.</i> <span class=\"citation\">Peah II, 2</span> <span dir=\"rtl\">אַמַּת המים</span>.—<span class=\"citation\">Yoma V, 6</span> <span dir=\"rtl\">אלו ואלו מתערבין בא׳</span> the blood of both was mixed in the sewer; <span class=\"citation\">Tam. III, 6</span>; <span class=\"citation\">B. Mets. 33ᵃ</span>; Y. Hor. III, 48ᵇ top <span dir=\"rtl\"><a href=\"#\" data-headword=\"אֱמֶת\">אמת</a> (<span dir=\"rtl\">בית</span>) <span dir=\"rtl\">השחי</span></span> a sewer in the Temple called <i>the duct of the arm-pit</i> (from its shape; v. Grætz Monatsschr. 1880, p. 289; [emendation <a href=\"#\" data-headword=\"שִׁית\">שית</a> unnecessary]; v. supra.—Pl. <span dir=\"rtl\">אַמֹּות</span> <i>cubits.</i> <span class=\"citation\">Kel. XVII, 10</span>; a. fr.</div>","alt":[]},"1990":{"h":"אָמָה","r":"A01990","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> v. <a href=\"#\" data-headword=\"אֵם\">אֵם</a>; cmp. <a href=\"#\" data-headword=\"אַמָּה\">preced.</a>) <i>hand-maid</i>. <span class=\"citation\">Sot. 12ᵇ</span>, v. <a href=\"#\" data-headword=\"אַמָּה\">preced.</a>; a. e.—Pl. <a href=\"#\" data-headword=\"אַמְהוּת\">אֲמָהוֹת</a>. <span class=\"citation\">Y. Snh. II, 20ᵇ</span> bot.; v. <a href=\"#\" data-headword=\"אֵם\">אֵם</a>; a. e.</div>","alt":[]},"1991":{"h":"אַמְהָא","r":"A01991","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Job XXXI, 13</span>. <span class=\"citation\">Targ. Gen. XVI, 1</span>; a. fr.—<span class=\"citation\">Y. M. Kat. III, 81ᵈ</span>.—<span class=\"citation\">Meg. 18ᵃ</span>; a. fr.—<span class=\"citation\">Erub. 53ᵇ</span>.—Pl. <a href=\"#\" data-headword=\"אַמְהֲתָא\">אַמְהָתָא</a>; <span dir=\"rtl\">אַמְהָן</span>. <span class=\"citation\">Targ. Gen. XX, 17</span>; a. fr.</div>","alt":["אַמְתָא","אַמְהֲתָא"]},"1992":{"h":"אַמְהוּ","r":"A01992","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <span class=\"citation\">Targ. O. Ex. XXI, 7</span> a. e. (Concrete: <i>servant</i>.); cmp. <a href=\"#\" data-headword=\"אִיתּוּ\">אִיתּוּ</a>.</div>","alt":[]},"1993":{"h":"אַמְהוּת","r":"A01993","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אָמָה\">אָמָה</a>) <i>servitude of a maid, servile condition</i>. Mekh. Mishp., sect. 3 <span dir=\"rtl\">קידוש אחר א׳</span> the father’s privilege of giving away his daughter in marriage is valid even after having hired her out as a servant.</div>","alt":[]},"1994":{"h":"אַמְהֲתָא","r":"A01994","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַמְהָא\">אַמְהָא</a></div>","alt":["אַמְהָתָא"]},"1995":{"h":"אַמָּהָתָא","r":"A01995","html":"<div class=\"sense\">, pl. of <a href=\"#\" data-headword=\"אַמְּתָא\">אַמְּתָא</a>.</div>","alt":[]},"1996":{"h":"*אֲמוֹדַאי","r":"A01996","html":"<div class=\"sense\">, with <a href=\"#\" data-headword=\"בַּר\">בַּר</a> m. <i>diver</i>. <span class=\"citation\">R. Hash. 23ᵃ</span>; <span class=\"citation\">B. Bath. 74ᵇ</span> Ms. a. Ar. (ed. <span dir=\"rtl\">בר אמוראי</span>).</div>","alt":[]},"1997":{"h":"אמודין","r":"A01997","html":"<div class=\"sense\"> <span class=\"citation\">Y. Snh. IX, 27ᵃ</span>, read <span dir=\"rtl\">אוּמָדִין</span>, pl. of <a href=\"#\" data-headword=\"אוּמָד\">אוּמָד</a>.</div>","alt":[]},"1998":{"h":"אִמּוּם","r":"A01998","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (= <span dir=\"rtl\">אמאום</span>, denom. of <a href=\"#\" data-headword=\"אֵם\">אֵם</a>) <i>model, form, shoe-maker’s last</i>, &amp;c. <span class=\"citation\">Kel. XXVI, 4</span>; <span class=\"citation\">XXIII, 1</span>.—<span class=\"citation\">Ib. XVI, 7</span> <span dir=\"rtl\">הא׳ של גודלי וכ׳</span> the block of the cap-makers; <span dir=\"rtl\">של עושי וכ׳</span> of dressmakers. <span class=\"citation\">Sabb. 141ᵇ</span> Ms. M. (ed. <a href=\"#\" data-headword=\"אימוס\">אימוס</a>, corr. acc.); a. fr.</div>","alt":["אִימּוּם"]},"1999":{"h":"אָמוֹן I","r":"A01999","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>artist;</i> (homilet.) a) = <a href=\"#\" data-headword=\"אוֹמָן\">אוֹמֵן</a>, <i>tutor</i>; b) = <a href=\"#\" data-headword=\"אָמוֹן I\">אָמוּן</a> <i>nursed</i> (<i>well-covered</i>)<i>;guarded;</i> c) = <a href=\"#\" data-headword=\"אָמוֹן II\">next w.</a>, <i>metropolis</i>, (great). <span class=\"citation\">Gen. R. s. 1</span>.</div>","alt":[]}};
